def ffmpeg_exe() -> str:
    found = shutil.which("ffmpeg")
    if found:
        return found
    try:
        import imageio_ffmpeg

        return imageio_ffmpeg.get_ffmpeg_exe()
    except ImportError as exc:
        raise RuntimeError("ffmpeg غير موجود. ثبّته أو ثبّت الحزمة imageio-ffmpeg") from exc


def probe_duration(path: Path) -> float:
    """يعود طول الفيديو بالثواني من مخرجات ffmpeg."""
    result = subprocess.run(
        [ffmpeg_exe(), "-hide_banner", "-i", str(path)],
        capture_output=True,
        text=True,
    )
    match = re.search(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)", result.stderr)
    if not match:
        raise ValueError("تعذّر قراءة طول الفيديو")
    h, m, s = match.groups()
    return int(h) * 3600 + int(m) * 60 + float(s)


# 🔒 كل براند ملفاته لوحده: الجداول دي فيها client_id. أي حاجة جديدة بتتسجّل للبراند المفتوح (trigger على كل اتصال)،
# والقوايم بتعرض بتاعة البراند ده بس: WHERE mine(client_id). القديم اللي من غير براند بيتحسب على أول براند.
BRAND_TABLES = ("coaches", "audio", "exports", "projects", "generations", "posts", "videos", "folders")


_BRAND = {"c": None, "f": None, "s": (), "t": 0.0}
_brand_tl = threading.local()


def brand_ids() -> tuple[str | None, str | None]:
    """(العلامة المفتوح، أول علامة) متخزنين ثانيتين، ومن غير ما يتحسبون داخل اتصال مرة أخرى (لكي لا يوجد لف ولا قفل للداتابيز)."""
    if time.time() - _BRAND["t"] < 2 or getattr(_brand_tl, "busy", False):
        return _BRAND["c"], _BRAND["f"]
    _brand_tl.busy = True
    try:
        _BRAND.update(c=active_client_id(), f=first_client_id(), s=tuple(json.loads(auth.get_setting("lib_share") or "[]")), t=time.time())
    except Exception:  # noqa: BLE001 — قبل ما الجداول تتعمل
        pass
    finally:
        _brand_tl.busy = False
    return _BRAND["c"], _BRAND["f"]


def db() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    if BRAND_COLS_READY.get("ok"):
        c, f = brand_ids()
        conn.create_function("cur_brand", 0, lambda: c, deterministic=True)
        conn.create_function("mine", 1, lambda cid: 1 if (cid == c if cid else (not c or c == f)) else 0, deterministic=True)
        # 🔗 فولدر متشارك بين البراندات (من «مكتبة محتويات البراند»): vis(client_id, 'chars') بيعرض بتاع كل البراندات
        sk = set(_BRAND["s"])
        conn.create_function("vis", 2, lambda cid, k: 1 if k in sk or (cid == c if cid else (not c or c == f)) else 0, deterministic=True)
        # 🗂️ الفيديوهات الجاهزة والمنشورات: القديم اللي مالوش براند مايظهرش في أي براند (مش بيتحسب على أول براند)
        conn.create_function("own", 1, lambda cid: 1 if (not c or (cid and cid == c)) else 0, deterministic=True)
        conn.create_function("vis_own", 2, lambda cid, k: 1 if (not c or (cid and (k in sk or cid == c))) else 0, deterministic=True)
        for t in BRAND_TABLES:
            conn.execute(f"CREATE TEMP TRIGGER IF NOT EXISTS brand_{t} AFTER INSERT ON main.{t} WHEN NEW.client_id IS NULL AND cur_brand() IS NOT NULL "
                         f"BEGIN UPDATE {t} SET client_id = cur_brand() WHERE rowid = NEW.rowid; END")
    else:
        conn.create_function("mine", 1, lambda cid: 1)
        conn.create_function("vis", 2, lambda cid, k: 1)
        conn.create_function("own", 1, lambda cid: 1)
        conn.create_function("vis_own", 2, lambda cid, k: 1)
    return conn


def share_keys() -> set[str]:
    """المجلدات الأساسية التي صاحب الأكاونت مشاركها بين كل العلامات (ideas, images, videos, voice, music, chars, exports)."""
    brand_ids()
    return set(_BRAND.get("s") or ())


