    # كل فيديو متولّد بيفتكر هو من أنهي فيديو خام (عشان الأرشيف)
    if "video_id" not in {c[1] for c in _conn.execute("PRAGMA table_info(generations)")}:
        _conn.execute("ALTER TABLE generations ADD COLUMN video_id TEXT")
