class PostOptions(BaseModel):
    tag_slide: int = 1  # في الكاروسيل: التاج على أنهي سلايد
    ig_tags: list[str] = []  # حسابات تتعمل تاج في إنستجرام
    ig_collab: bool = False  # البوست يظهر كمان في حساب المدرب (كولاب) لو وافق
    cover_ms: int | None = None  # الغلاف: فريم من الفيديو (بالملّي ثانية) لإنستجرام وتيك توك
    dm_on: bool = False          # 💬 «علّق بكلمة»: اللي يكتب الكلمة في الكومنت بيوصله رسالة على الخاص (إنستجرام وفيسبوك)
    dm_words: list[str] = []
    dm_message: str = ""
    dm_reply: str = ""
    dm_gate: bool = True         # 🔒 يسأله «عامل فولو؟» الأول، ولما يقول أيوة يوصله اللي طلبه


class PostIn(BaseModel):
    export_id: str
    caption: str = ""
    platforms: list[str]
    scheduled_at: datetime  # من المتصفح بتوقيت UTC
    options: PostOptions = PostOptions()


def clean_options(opts: PostOptions) -> str:
    tags = []
    for t in opts.ig_tags:
        h = sheets.clean_handle(t, "instagram")
        if t.strip() and not h:
            raise HTTPException(400, f"اسم الحساب غير مظبوط: {t.strip()}")
        if h and h not in tags:
            tags.append(h)
    if len(tags) > 20:
        raise HTTPException(400, "إنستجرام يقبل 20 تاج بالكتير")
    if opts.ig_collab and not tags:
        raise HTTPException(400, "الكولاب يحتاج حساب واحد على الأقل في خانة التاج")
    if opts.ig_collab and len(tags) > 3:
        raise HTTPException(400, "الكولاب يقبل 3 حسابات بالكتير")
    cover = max(0, int(opts.cover_ms)) if opts.cover_ms is not None else None
    out = {"ig_tags": tags, "ig_collab": opts.ig_collab, "cover_ms": cover, "tag_slide": max(1, int(opts.tag_slide or 1))}
    if opts.dm_on:
        words = [w.strip()[:30] for w in opts.dm_words if w.strip()][:10]
        if not words:
            raise HTTPException(400, "«علّق بكلمة»: اكتب الكلمة التي الأشخاص ستكتبها في التعليق")
        if not opts.dm_message.strip():
            raise HTTPException(400, "«علّق بكلمة»: اكتب الرسالة التي ستوصلهم على الخاص")
        out["dm"] = {"words": words, "message": opts.dm_message.strip()[:900], "reply": opts.dm_reply.strip()[:200], "gate": bool(opts.dm_gate)}
    return json.dumps(out)


def clean_post(conn: sqlite3.Connection, body: PostIn) -> tuple[str, str, str]:
    if not conn.execute("SELECT 1 FROM exports WHERE id = ?", (body.export_id,)).fetchone():
        raise HTTPException(400, "الفيديو غير موجود في المجلد")
    platforms = [p for p in dict.fromkeys(body.platforms) if publisher.valid_target(p)]
    if not platforms:
        raise HTTPException(400, "اختر منصة واحدة على الأقل")
    when = body.scheduled_at
    if when.tzinfo is None:
        raise HTTPException(400, "الموعد يجب يكون فيه المنطقة الزمنية")
    return json.dumps(platforms), when.astimezone(timezone.utc).isoformat(timespec="seconds"), body.caption.strip()


def set_post(post_id: str, **fields) -> None:
    fields["updated_at"] = now()
    cols = ", ".join(f"{k} = ?" for k in fields)
    with closing(db()) as conn, conn:
        old = conn.execute(POSTS_QUERY + " WHERE p.id = ?", (post_id,)).fetchone()
        conn.execute(f"UPDATE posts SET {cols} WHERE id = ?", (*fields.values(), post_id))
    status = fields.get("status")
    if old is not None and status in ("published", "failed") and status != old["status"]:
        name = old["carousel_name"] or old["export_name"] or (old["caption"] or "").split("\n")[0][:60] or "بوست"
        plats = "، ".join(dict.fromkeys(publisher.PLATFORMS.get(publisher.split_target(k)[0], (None, k))[1] for k in json.loads(old["platforms"] or "[]")))
        if status == "published":
            notify("post", "ok", f"نُشر: {name}", plats, "7", post_id)
            if (json.loads(old["options"] or "{}") or {}).get("dm") or dm_detect(old["caption"] or ""):
                threading.Thread(target=dm_start, args=(post_id,), daemon=True).start()
            try:
                batch_auto()
            except Exception:  # noqa: BLE001  (التحليل الأوتوماتيك عمره مايوقف النشر)
                pass
        else:
            notify("post", "bad", f"المنشور مااتنشرش: {name}", fields.get("error") or old["error"] or "", "7", post_id)


def send_post(post_id: str, old_remote_id: str | None = None) -> None:
    """يرفع الفيديو ويسلّم المنشور لـ Zernio (في الخلفية)."""
    try:
        if old_remote_id:
            publisher.cancel(old_remote_id)
        with closing(db()) as conn:
            r = conn.execute(POSTS_QUERY + " WHERE p.id = ?", (post_id,)).fetchone()
        if r is None or r["status"] != "sending":
            return
        if r["carousel_id"]:
            with closing(db()) as conn:
                _, cdata = load_carousel(conn, r["carousel_id"])
            remote_id = publisher.schedule_carousel(
                post_images(r["carousel_id"], cdata), r["caption"], r["scheduled_at"],
                publish_now=r["scheduled_at"] <= now(), options=json.loads(r["options"]) if r["options"] else {},
                targets=json.loads(r["platforms"] or "[]"),
            )
            set_post(post_id, status="scheduled", remote_id=remote_id, error=None)
            return
        if not r["export_filename"] or not (EXPORTS_DIR / r["export_filename"]).exists():
            raise publisher.PublishError("الفيديو حُذف من المجلد")
        remote_id = publisher.schedule(
            EXPORTS_DIR / r["export_filename"],
            r["caption"],
            json.loads(r["platforms"]),
            r["scheduled_at"],
            title=r["caption"].split("\n")[0].strip() or r["export_name"],
            ai_made=r["export_source"] == "studio",
            publish_now=r["scheduled_at"] <= now(),
            options=json.loads(r["options"]) if r["options"] else {},
        )
        set_post(post_id, status="scheduled", remote_id=remote_id, error=None)
    except (publisher.PublishError, httpx.HTTPError, HTTPException, subprocess.SubprocessError) as exc:
        detail = exc.detail if isinstance(exc, HTTPException) else exc
        set_post(post_id, status="failed", remote_id=None, error=f"تعذّر ذلك أسلّم المنشور لخدمة النشر: {detail}"[:500])


def after_save(post_id: str, when: str, old_remote_id: str | None) -> None:
    service = publisher.service_name()
    if service == "zernio":
        set_post(post_id, status="sending", remote_id=None)
        threading.Thread(target=send_post, args=(post_id, old_remote_id), daemon=True).start()
    elif when <= now():
        threading.Thread(target=publish_due_posts, daemon=True).start()


@app.post("/api/posts")
def create_post(body: PostIn):
    with closing(db()) as conn, conn:
        platforms, when, caption = clean_post(conn, body)
        options = clean_options(body.options)
        post_id = uuid.uuid4().hex[:12]
        # لو Zernio مربوط بيتسجّل «بيتبعت» على طول، عشان المجدول ميبعتهوش هو كمان (نسختين عند Zernio)
        status = "sending" if publisher.service_name() == "zernio" else "scheduled"
        conn.execute(
            "INSERT INTO posts (id, export_id, caption, platforms, scheduled_at, status, options, created_at, updated_at) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (post_id, body.export_id, caption, platforms, when, status, options, now(), now()),
        )
    after_save(post_id, when, None)
    with closing(db()) as conn:
        return post_to_dict(conn.execute(POSTS_QUERY + " WHERE p.id = ?", (post_id,)).fetchone())


@app.put("/api/posts/{post_id}")
def update_post(post_id: str, body: PostIn):
    with closing(db()) as conn, conn:
        row = conn.execute("SELECT status, remote_id, carousel_id FROM posts WHERE id = ?", (post_id,)).fetchone()
        if row is None:
            raise HTTPException(404, "المنشور غير موجود")
        if row["carousel_id"]:
            raise HTTPException(400, "هذا كاروسيل: الغيه من هنا وانشره مرة أخرى من صفحة الكاروسيل")
        if row["status"] in ("sending", "publishing", "published"):
            raise HTTPException(400, "هذا المنشور نُشر أو يُرسل الآن")
        if row["status"] == "failed" and row["remote_id"]:
            raise HTTPException(400, "هذا المنشور أُرسل لخدمة النشر وفشل. استخدم إعادة المحاولة، أو احذفه وأنشئ واحد جديد")
        platforms, when, caption = clean_post(conn, body)
        options = clean_options(body.options)
        conn.execute(
            "UPDATE posts SET export_id = ?, caption = ?, platforms = ?, scheduled_at = ?, status = 'scheduled', "
            "options = ?, error = NULL, updated_at = ? WHERE id = ?",
            (body.export_id, caption, platforms, when, options, now(), post_id),
        )
    after_save(post_id, when, row["remote_id"])
    with closing(db()) as conn:
        return post_to_dict(conn.execute(POSTS_QUERY + " WHERE p.id = ?", (post_id,)).fetchone())


@app.delete("/api/posts/{post_id}")
def delete_post(post_id: str):
    with closing(db()) as conn:
        row = conn.execute("SELECT status, remote_id FROM posts WHERE id = ?", (post_id,)).fetchone()
    if row is None:
        raise HTTPException(404, "المنشور غير موجود")
    if row["status"] in ("sending", "publishing"):
        raise HTTPException(400, "المنشور يُرسل الآن، انتظر ثواني")
    if row["remote_id"] and row["status"] in ("scheduled", "failed"):
        # لازم نلغيه عند Zernio الأول، وإلا هيتنشر برضه (حتى الفاشل ممكن يكون لسه متجدول على منصات تانية)
        try:
            publisher.cancel(row["remote_id"])
        except (publisher.PublishError, httpx.HTTPError) as exc:
            if row["status"] == "scheduled":
                raise HTTPException(400, f"تعذّر إلغاؤه عند خدمة النشر: {exc}") from exc
    with closing(db()) as conn, conn:
        conn.execute("DELETE FROM posts WHERE id = ?", (post_id,))
    return {"ok": True}


# ---------- البوستات اللي عند Zernio ومش في القايمة هنا ----------
def _remote_orphans() -> list[dict]:
    if publisher.service_name() != "zernio":
        return []
    try:
        remote = publisher.list_scheduled()
    except (publisher.PublishError, httpx.HTTPError) as exc:
        raise HTTPException(400, f"تعذّر الوصول لخدمة النشر: {exc}") from exc
    with closing(db()) as conn:
        known = {r["remote_id"] for r in conn.execute("SELECT remote_id FROM posts WHERE remote_id IS NOT NULL")}
    return [p for p in remote if p["id"] not in known]


@app.get("/api/posts/published")
def published_posts():
    """ما نُشر: منشورات العلامة المختارة بس (اللي اتعملت من البرنامج)، ولينك كل منصة من Zernio، وإذا لا يوجد Zernio من القائمة هنا."""
    with closing(db()) as conn:
        local = [post_to_dict(r) for r in conn.execute(POSTS_QUERY + " WHERE p.status = 'published' AND own(p.client_id) ORDER BY p.published_at DESC")]
    if publisher.service_name() != "zernio":
        return [{"id": p["id"], "content": p["caption"], "published_at": p["published_at"] or p["scheduled_at"],
                 "media_url": p["export_url"], "name": p["export_name"],
                 "platforms": [{"key": k, "status": "published", "url": None, "error": None} for k in p["platforms"]]}
                for p in local]
    try:
        remote = publisher.list_posts("published", 50)
    except (publisher.PublishError, httpx.HTTPError) as exc:
        raise HTTPException(400, f"تعذّر الوصول لخدمة النشر: {exc}") from exc
    by_remote = {p.get("remote_id"): p for p in local}
    with closing(db()) as conn:
        names = {r["remote_id"]: r["export_name"] for r in conn.execute(POSTS_QUERY + " WHERE p.remote_id IS NOT NULL")}
    out = []
    for r in remote:
        ours = by_remote.get(r["id"])
        if not ours:   # منشور مش من البرنامج ده أو من علامة تانية (نفس حساب خدمة النشر بيشيل منشورات ناس تانية): مايظهرش هنا
            continue
        out.append({
            "id": r["id"], "content": r["content"], "media_url": r["media_url"] or (ours or {}).get("export_url"),
            "published_at": r["published_at"] or next((x["published_at"] for x in r["platforms"] if x.get("published_at")), None) or r["scheduled_for"],
            "name": names.get(r["id"]), "platforms": r["platforms"],
        })
    out.sort(key=lambda x: x["published_at"] or "", reverse=True)
    return out


@app.get("/api/posts/remote")
def remote_orphans():
    return _remote_orphans()


class AdoptIn(BaseModel):
    remote_id: str


@app.post("/api/posts/adopt")
def adopt_remote_post(body: AdoptIn):
    """منشور متجدول عند Zernio ومش هنا: نضيفه للقايمة لكي تتابعه وتلغيه من هنا."""
    post = next((p for p in _remote_orphans() if p["id"] == body.remote_id), None)
    if post is None:
        raise HTTPException(404, "لم نجد هذا المنشور عند خدمة النشر، أو أنه موجود في القائمة بالفعل")
    try:
        when = datetime.fromisoformat(str(post["scheduled_for"]).replace("Z", "+00:00")).astimezone(timezone.utc)
    except ValueError:
        when = datetime.now(timezone.utc)
    post_id = uuid.uuid4().hex[:12]
    with closing(db()) as conn, conn:
        conn.execute(
            "INSERT INTO posts (id, export_id, caption, platforms, scheduled_at, status, remote_id, remote_media, created_at, updated_at) "
            "VALUES (?, '', ?, ?, ?, 'scheduled', ?, ?, ?, ?)",
            (post_id, post["content"], json.dumps(post["platforms"]), when.isoformat(timespec="seconds"),
             post["id"], post["media_url"], now(), now()),
        )
    return {"ok": True}


@app.post("/api/posts/remote/{remote_id}/cancel")
def cancel_remote_post(remote_id: str):
    if not any(p["id"] == remote_id for p in _remote_orphans()):
        raise HTTPException(404, "لم نجد هذا المنشور عند خدمة النشر، أو أنه موجود في القائمة بالفعل")
    try:
        publisher.cancel(remote_id)
    except (publisher.PublishError, httpx.HTTPError) as exc:
        raise HTTPException(400, f"تعذّر إلغاؤه عند خدمة النشر: {exc}") from exc
    return {"ok": True}


@app.post("/api/posts/{post_id}/retry")
def retry_post(post_id: str):
    with closing(db()) as conn:
        row = conn.execute("SELECT status, remote_id, scheduled_at, error FROM posts WHERE id = ?", (post_id,)).fetchone()
    if row is None or row["status"] != "failed":
        raise HTTPException(400, "هذا المنشور غير فاشل")
    if resend_without_tags(post_id, row["error"] or ""):   # التاج هو اللي موقّعه: نبعته من غيره
        return {"ok": True}
    if row["remote_id"]:
        # Zernio بتعيد المنصات اللي فشلت بس، فمفيش نشر مكرر
        try:
            publisher.retry(row["remote_id"])
        except (publisher.PublishError, httpx.HTTPError) as exc:
            raise HTTPException(400, str(exc)) from exc
        set_post(post_id, status="scheduled", error=None)
    else:
        set_post(post_id, status="sending" if publisher.service_name() == "zernio" else "scheduled", error=None)
        after_save(post_id, row["scheduled_at"], None)
    return {"ok": True}


# إنستجرام بيرفض البوست كله لو الحساب اللي عليه تاج أو كولاب برايفت أو اسمه غلط
IG_TAG_ERROR = re.compile(r"private profile|invalid username|cannot be accessed|cannot load user|user.{0,20}not found|collaborator", re.I)


def resend_without_tags(post_id: str, error: str) -> bool:
    """إذا إنستجرام رفض بسبب التاج/الكولاب: نشيل التاج وننشر على إنستجرام آخر مباشرة، ونقول للمستخدم."""
    if "إنستجرام" not in error or not IG_TAG_ERROR.search(error):
        return False
    with closing(db()) as conn:
        r = conn.execute(POSTS_QUERY + " WHERE p.id = ?", (post_id,)).fetchone()
    opts = json.loads(r["options"]) if r is not None and r["options"] else {}
    tags = opts.get("ig_tags") or []
    if r is None or not tags or r["carousel_id"] or not r["export_filename"] or not (EXPORTS_DIR / r["export_filename"]).exists():
        return False
    opts = {**opts, "ig_tags": [], "ig_collab": False}
    try:
        remote_id = publisher.schedule(EXPORTS_DIR / r["export_filename"], r["caption"], ["instagram"], now(),
                                       title=r["caption"].split("\n")[0].strip() or r["export_name"], ai_made=r["export_source"] == "studio",
                                       publish_now=True, options=opts)
    except (publisher.PublishError, httpx.HTTPError):
        return False
    with closing(db()) as conn, conn:
        conn.execute("UPDATE posts SET options = ? WHERE id = ?", (json.dumps(opts), post_id))
    set_post(post_id, status="scheduled", remote_id=remote_id, error=None)
    who = "، ".join("@" + t for t in tags)
    notify("post", "bad", f"شلت التاج من المنشور ({who})",
           f"إنستجرام رفض التاج والكولاب لأن الحساب برايفت أو الاسم خطأ، فالمنشور أُرسل مرة أخرى من غيرهم. صحّح اسم الحساب في صفحة المدرب أو اجعله عام.", "7", post_id)
    return True


# ---------------------------------------------------------------- 💬 «علّق بكلمة» على البوستات اللي بتتنشر من البرنامج
DM_PLATFORMS = ("instagram", "facebook")   # تيك توك مش بيسمح برسايل أوتوماتيك على الكومنتات في منطقتنا


DM_CTA = re.compile(r"(علّ?ق|علِّق|اكتب|كومنت|تعليق|comment)", re.I)


def dm_detect(caption: str) -> str:
    """التعليق النصي فيه دعوة «علّق بكلمة»؟ يعود الكلمة. أي منشور فيه هذه الدعوة الرد التلقائي يشتغل تلقائيًا بدون ما حد يفعّله."""
    for line in (caption or "").splitlines():
        if not DM_CTA.search(line):
            continue
        m = re.search(r"[«\"“'‘]\s*([^»\"”'’\n]{1,30}?)\s*[»\"”'’]", line) or re.search(r"كلمة\s+([\w\u0600-\u06FF]{2,30})", line) \
            or re.search(r"\b(?:comment|type)\s+([A-Za-z0-9]{2,30})\b", line, re.I)
        if m:
            return m.group(1).strip()
    return ""


def dm_start(post_id: str) -> None:
    """أول ما المنشور يُنشر: يشغّل الرد التلقائي على كل منصة إنستجرام/فيسبوك نُشر عليها.
    رقم المنشور عند المنصة يمكن يتأخر قليلًا بعد النشر، فنحاول كم مرة ثم نقف (لا يوجد ثريد يعمل مباشرة)."""
    import wacamp
    with closing(db()) as conn:
        r = conn.execute("SELECT * FROM posts WHERE id = ?", (post_id,)).fetchone()
    if not r or not r["remote_id"] and publisher.service_name() != "mock":
        return
    opts = json.loads(r["options"] or "{}")
    dm, done = opts.get("dm") or {}, dict(opts.get("dm_auto") or {})
    if not dm:   # الدعوة مكتوبة في الكابشن ومحدش ظبط الرسالة: بتتعمل من خطة المحتوى ولينك الواتساب
        word = dm_detect(r["caption"] or "")
        if not word:
            return
        d = dm_defaults_for(r["client_id"] or active_client_id())
        dm = {"words": [word], "message": d["message"], "reply": d["reply"], "auto": True, "gate": dmflow.settings(brain_row(r["client_id"] or "") or {})["on"]}
        opts["dm"] = dm
    flow = dmflow.settings(brain_row(r["client_id"] or active_client_id() or "") or {})
    gate = bool(dm.get("gate", flow["on"]))
    for tgt in json.loads(r["platforms"] or "[]"):
        plat, acc = publisher.split_target(tgt)
        if plat not in DM_PLATFORMS or (done.get(plat) or {}).get("id"):
            continue
        err = ""
        for attempt in range(4):
            try:
                if not acc:
                    acc = "m-acc" if publisher.service_name() == "mock" else publisher.resolve_targets([tgt])[0][1]
                pid = wacamp.platform_post_id(r["remote_id"] or post_id, plat)
                first = flow["ask"] if gate else dm["message"]   # 🔒 السؤال الأول، واللينك بيتبعت لما يرد «أيوة»
                a = wacamp.comment_automation(acc, pid, f"علّق بكلمة: {(r['caption'] or '')[:40]}", dm["words"], first, dm.get("reply") or "")
                done[plat] = {"id": a.get("id"), "error": None, "gate": gate}
                if gate and a.get("id"):
                    DM_STORE.add_gate(a["id"], acc, plat, dm["message"], dm["words"], post_id, r["client_id"] or "", flow)
                    dm_hook_ready()
                if a.get("id") and r["client_id"]:
                    wa_push(r["client_id"], "automations", a["id"])
                break
            except (wacamp.WaError, publisher.PublishError, httpx.HTTPError) as exc:
                err = str(exc)[:200]
                time.sleep(0 if publisher.service_name() == "mock" else 60 * (attempt + 1))
        else:
            done[plat] = {"id": None, "error": err}
            notify("post", "bad", "«علّق بكلمة» مااشتغلش", f"{publisher.PLATFORMS[plat][1]}: {err}", "7", post_id)
    with closing(db()) as conn, conn:
        conn.execute("UPDATE posts SET options = ? WHERE id = ?", (json.dumps({**opts, "dm_auto": done}), post_id))


