# ---------- 🗓️ خطة الشهر: الخطة بقت جدول. كل يوم كام بوست، وكل بوست بنوعه وقالبه وموضوعه وفكرته وهوكه.
# بتتعمل لما العقل يفهم العميل (PLAN_SCORE) وتكون فيه خطة محتوى، وبعد ما العميل يوافق بتنزل على الأوتوبايلوت:
# كل بوست بيتعمل في ميعاده بالفكرة دي (من غير ما المخ يقترح أفكار تانية)، والموافقة على الخطوات زي ما هي في الأوتوبايلوت.
MONTH_DAYS = 30
MONTH_KINDS = {"reel": "ريل بقالب", "carousel": "كاروسيل", "phone": "تصوير بالجوال", "avatar": "فيديو بالأفاتار", "custom": "قالب مخصص"}
MONTH_BUSY: dict[str, str] = {}


def month_formats(bid: str, code_tpls: list[dict]) -> list[dict]:
    """الأشكال الذي الخطة يمكنك تختار منها (ما الأوتوبايلوت يعرف يعملها فعلًا)."""
    out = [{"id": "phone", "kind": "phone", "name": "تصوير بالجوال (العميل يصوّر نفسه بالسكريبت)"},
           {"id": "carousel", "kind": "carousel", "name": "كاروسيل صور على إنستجرام"}]
    if any(t["ready"]["video"] or t["ready"]["photo"] for t in twins_list()):
        out.append({"id": "avatar", "kind": "avatar", "name": "فيديو نسخة العميل (أفاتار) يقول النص"})
    out += [{"id": f"auto:{a['id']}", "kind": "custom", "name": f"قالب مخصص: {a['name']}"} for a in automations_list() if a.get("saved")]
    out += [{"id": t["id"], "kind": "reel", "name": f"ريل بقالب «{t['name']}»: {t.get('desc', '')[:90]}"} for t in code_tpls[:40]
            if re.fullmatch(r"t-[\w-]+", str(t.get("id") or "")) and (MOTION_DIR / "r" / t["id"] / "reel.html").exists()]
    return out


def month_messages(b: dict, fmts: list[dict], start, days: int, per_day: int, times: list[str], extra: str) -> list[dict]:
    dates = [(start + timedelta(days=i)).isoformat() for i in range(days)]
    return [{"role": "system", "content": "أنت مخطط محتوى سوشيال محترف تعمل جدول نشر شهري حقيقي لبراند واحد. " + dialect.content(b) + " وأما الشرح (سبب اختيار كل منشور) فبالعربية الفصحى البسيطة. Return JSON only."},
            {"role": "user", "content": f"""العلامة:
{az.brain_text(b)[:4000]}

{algo.strategy_text(b)}
{extra}

الأشكال المتاحة (اختر id منهم بالضبط، ونوّع بينهم على قدر ما يناسب العلامة):
{chr(10).join(f"- {f['id']}: {f['name']}" for f in fmts)}

أنشئ جدول نشر هذه للأيام: {", ".join(dates)}
كل يوم {per_day} منشور في هذه المواعيد: {", ".join(times)}.
القواعد: امشي على مجموعات المواضيع ودوائر الجمهور وخلطة ٣-٢-١ ما في الخطة، واربط بالمواسم والترندات إذا في معادها، وماتكررش فكرة،
وكل منشور فكرته محددة جدًا (غير عامة) وهوكه جملة قصيرة تشد. الكاروسيل للمعلومات والقوائم والخطوات، والجوال للآراء والقصص والإجابات.
استعد JSON هذا بالشكل فقط:
{{"posts": [{{"date": "YYYY-MM-DD", "time": "HH:MM", "format": "id من الأشكال", "bucket": "مجموعة المواضيع", "title": "عنوان قصير",
  "idea": "الفكرة في جملة واحدة قصيرة (غير نص)", "hook": "الخطاف", "cta": "الدعوة", "why": "له هذا المنشور في هذا اليوم (جملة)",
  "aud": "اسم الجمهور المقصود بالضبط من «الجماهير المستهدفة» إذا موجودة، وإلا فارغ"}}]}}"""}]


def month_clean(raw: dict, fmts: list[dict], dates: set[str], times: list[str]) -> list[dict]:
    by = {f["id"]: f for f in fmts}
    out = []
    for p in (raw.get("posts") or []) if isinstance(raw, dict) else []:
        if not isinstance(p, dict) or str(p.get("date")) not in dates:
            continue
        f = by.get(str(p.get("format") or "")) or by.get("phone")
        t = str(p.get("time") or "")
        out.append({"id": uuid.uuid4().hex[:8], "date": str(p["date"]), "time": t if re.fullmatch(r"([01]\d|2[0-3]):[0-5]\d", t) else times[0],
                    "tpl": f["id"], "kind": f["kind"], "tpl_name": f["name"].split(":")[0].split(" (")[0],
                    **{k: str(p.get(k) or "").strip()[:400] for k in ("bucket", "title", "idea", "hook", "cta", "why", "aud")}})
    return out


def month_mock(fmts: list[dict], start, days: int, per_day: int, times: list[str]) -> list[dict]:
    raw = {"posts": [{"date": (start + timedelta(days=i)).isoformat(), "time": times[k % len(times)], "format": fmts[(i * per_day + k) % len(fmts)]["id"],
                      "bucket": "مجموعة تجريبية", "title": f"فكرة اليوم {i + 1} رقم {k + 1}", "idea": "فكرة تجريبية للجدول", "hook": "خطاف تجريبي",
                      "cta": "علّق بكلمة", "why": "تجربة"} for i in range(days) for k in range(per_day)]}
    return month_clean(raw, fmts, {(start + timedelta(days=i)).isoformat() for i in range(days)}, times)


def run_month(bid: str, per_day: int, times: list[str], code_tpls: list[dict]) -> None:
    try:
        b = brain_row(bid) or {}
        fmts = month_formats(bid, code_tpls)
        start = (datetime.now(timezone.utc) + timedelta(days=1)).date()
        if atlas.mock_mode():
            items = month_mock(fmts, start, MONTH_DAYS, per_day, times)
        else:
            usd = wallet.est(chars=60000)
            wallet.need(wallet.credits(usd), "خطة الشهر")
            seasons = "\n".join(f"- {i['name']} ({i['date']})" for i in fz.fit_seasons(((b.get("seasons") or {}).get("items") or []), b.get("market", ""))[:20])
            trends = "\n".join(f"- {t.get('title')}" for t in ((b.get("trends") or {}).get("items") or [])[:12] if t.get("title"))
            extra = "\n\n".join(x for x in (algo.batch_text(b), rivals.insight_text(b), f"المواسم:\n{seasons}" if seasons else "",
                                             f"الترندات في المجال الآن:\n{trends}" if trends else "") if x)[:4000]
            items = []
            for half in range(0, MONTH_DAYS, 10):   # ١٠ أيام في كل طلب: الرد أقصر وأضمن
                n = min(10, MONTH_DAYS - half)
                s0 = start + timedelta(days=half)
                msgs = month_messages(b, fmts, s0, n, per_day, times, extra + ("\n\nأفكار وُضعت من قبل (ماتكررهاش): " + " · ".join(x["title"] for x in items[-40:]) if items else ""))
                raw = az.parse_json(atlas.chat(msgs, carousel_settings()["text_model"], temperature=0.7, max_tokens=12000, json_mode=True, timeout=300), "خطة الشهر")
                items += month_clean(raw, fmts, {(s0 + timedelta(days=i)).isoformat() for i in range(n)}, times)
            wallet.charge(wallet.credits(usd), "عقل العلامة: خطة الشهر", bid)
        if not items:
            raise HTTPException(400, "العقل مرجعش جدول، جرّب مرة أخرى")
        month = {"status": "draft", "start": start.isoformat(), "days": MONTH_DAYS, "per_day": per_day, "times": times, "items": items, "made_at": now()}
        update_brain(bid, lambda d: d.update(month=month))
        MONTH_BUSY.pop(bid, None)
        notify("plan", "ok", "🗓️ خطة الشهر جاهزة", f"{len(items)} منشور · راجعها ووافق لكي تنزل على الأوتوبايلوت", "plan", bid)
    except Exception as exc:  # noqa: BLE001
        MONTH_BUSY[bid] = f"error:{str(getattr(exc, 'detail', None) or exc)[:200]}"


def month_out(bid: str) -> dict:
    b = brain_row(bid) or {}
    m = b.get("month") or None
    job = MONTH_BUSY.get(bid) or ""
    kn = fz.knowledge(b)
    return {"month": m, "kinds": MONTH_KINDS, "score": kn["score"], "need": PLAN_SCORE, "has_strategy": bool(b.get("strategy")),
            "know": kn, "ready": kn["ready"] and bool(b.get("strategy")),
            "status": "working" if job == "working" else "failed" if job.startswith("error") else "idle", "error": job[6:] if job.startswith("error") else None}


@app.get("/api/plan/month")
def month_get():
    return month_out(rivals_client())


class MonthIn(BaseModel):
    per_day: int = 0          # 0 = من الأوتوبايلوت (أو ٢)
    times: list[str] = []
    templates: list[dict] = []   # قوالب الكود من المعرض (id، الاسم، الوصف): الخطة بتختار منها


@app.post("/api/plan/month")
def month_make(body: MonthIn):
    bid = rivals_client()
    st = month_out(bid)
    if not st["ready"]:
        raise HTTPException(400, f"العقل ما زال فاهمك {st['score']}٪، والخطة تُنشأ من {PLAN_SCORE}٪ ومعها المجال وعن العلامة والجمهور. أكمل العقل أولًا")
    if st["status"] == "working":
        raise HTTPException(400, "الخطة تُنشأ الآن")
    ps = pilot_load()["settings"]
    times = [t for t in body.times if re.fullmatch(r"([01]\d|2[0-3]):[0-5]\d", t)] or [x["t"] for x in ps["times"]] or PILOT_BEST[2]
    per_day = max(1, min(6, body.per_day or len(times)))
    times = (times + PILOT_BEST[per_day])[:per_day] if len(times) < per_day else times[:per_day]
    MONTH_BUSY[bid] = "working"
    threading.Thread(target=run_month, args=(bid, per_day, sorted(times), body.templates[:60]), daemon=True).start()
    return month_out(bid)


class MonthItemIn(BaseModel):
    title: str | None = None
    idea: str | None = None
    hook: str | None = None
    cta: str | None = None
    time: str | None = None
    date: str | None = None
    tpl: str | None = None


@app.patch("/api/plan/month/items/{iid}")
def month_item_edit(iid: str, body: MonthItemIn):
    bid = rivals_client()

    def fn(d):
        m = d.get("month") or {}
        it = next((x for x in m.get("items") or [] if x["id"] == iid), None)
        if not it:
            raise HTTPException(404, "هذا المنشور غير في الخطة")
        if it.get("job"):
            raise HTTPException(400, "هذا المنشور بدأ يُنشأ في الأوتوبايلوت، عدّله من الطابور")
        for k in ("title", "idea", "hook", "cta"):
            if getattr(body, k) is not None:
                it[k] = getattr(body, k).strip()[:400]
        if body.time and re.fullmatch(r"([01]\d|2[0-3]):[0-5]\d", body.time):
            it["time"] = body.time
        if body.date and re.fullmatch(r"\d{4}-\d{2}-\d{2}", body.date):
            it["date"] = body.date
        if body.tpl:
            kind = "carousel" if body.tpl == "carousel" else pilot_kind(body.tpl) if body.tpl in ("phone", "avatar") or body.tpl.startswith("auto:") else "reel"
            it.update(tpl=body.tpl[:60], kind=kind, tpl_name=MONTH_KINDS.get(kind, ""))
    update_brain(bid, fn)
    return month_out(bid)


@app.delete("/api/plan/month/items/{iid}")
def month_item_delete(iid: str):
    bid = rivals_client()
    update_brain(bid, lambda d: (d.get("month") or {}).update(items=[x for x in (d.get("month") or {}).get("items") or [] if x["id"] != iid or x.get("job")]))
    return month_out(bid)


class MonthApplyIn(BaseModel):
    on: bool = True


@app.post("/api/plan/month/apply")
def month_apply(body: MonthApplyIn):
    """✅ موافق على الخطة: الأوتوبايلوت يسير عليها (كل منشور في موعده بفكرته)، أو ↩ يعود يختار بالدور من القوالب."""
    bid = rivals_client()
    m = (brain_row(bid) or {}).get("month")
    if body.on and not (m and m.get("items")):
        raise HTTPException(400, "أنشئ خطة الشهر أولًا")
    if body.on:
        update_brain(bid, lambda d: d["month"].update(status="applied", applied_at=now()))

    def fn(d):
        s = d["settings"]
        s["source"] = "plan" if body.on else "rotate"
        s["plan_bid"] = bid if body.on else ""
        if body.on:
            s["on"] = True
            s["times"] = [{"t": t, "mine": True} for t in m.get("times") or []] or s["times"]
            # المواعيد اللي اتعملت مهمتها بالدور ومابدأتش بتتشال، عشان الخطة تاخد مكانها
            d["jobs"] = [j for j in d["jobs"] if not (j.get("status") == "run" and j.get("phase") == "start" and not j.get("plan_item"))]
    pilot_update(fn)
    return {**month_out(bid), "pilot": pilot_state()}


# ---------- 📊 تحليل الدفعة: آخر ١٠ فيديوهات للبراند نفسه، وقاعدة ٥× و١٠× (playbook: batch)
def batch_out(bid: str) -> dict:
    bt = (brain_row(bid) or {}).get("batch") or {}
    calc = algo.batch_rows(bt.get("posts") or [], bt.get("metrics") or {}) if bt.get("posts") else None
    return {"platform": bt.get("platform") or "tiktok", "handle": bt.get("handle") or "", "fetched_at": bt.get("fetched_at"),
            "calc": calc, "verdict_text": algo.VERDICTS.get(calc["verdict"]) if calc else "", "analysis": bt.get("analysis"),
            "history": (bt.get("history") or [])[-6:], "live": rivals.live(), "algo_mode": algo.mode_on(brain_row(bid))}


@app.get("/api/batch")
def batch_get():
    return batch_out(rivals_client())


class BatchFetchIn(BaseModel):
    handle: str
    platform: str = "tiktok"


@app.post("/api/batch/fetch")
def batch_fetch(body: BatchFetchIn):
    """يجلب آخر منشورات حساب العلامة (ScrapeCreators) وكلامها المنطوق لكي التحليل يرى الخطاف."""
    bid = rivals_client()
    handle, platform = rivals.clean_handle(body.handle), body.platform if body.platform in rivals.PLATFORMS else "tiktok"
    if not handle:
        raise HTTPException(400, "اكتب اسم حساب العلامة")
    batch_pull(bid, handle, platform)
    return batch_out(bid)


def batch_pull(bid: str, handle: str, platform: str) -> None:
    try:
        posts = rivals.mock_posts(platform, handle) if not rivals.live() else rivals.profile_posts(platform, handle)
    except rivals.RivalsError as exc:
        raise HTTPException(400, str(exc)) from exc
    posts = sorted([p for p in posts if p["handle"].lower() == handle.lower()] or posts, key=lambda p: -(p.get("ts") or 0))[:algo.BATCH]
    if not posts:
        raise HTTPException(400, f"لم أجد منشورات للحساب @{handle}")
    if rivals.live():
        with ThreadPoolExecutor(5) as ex:
            for p, t in zip(posts, ex.map(lambda p: rivals.transcript(platform, p["url"]), posts)):
                p["spoken"] = t

    def fn(d):
        bt = d.setdefault("batch", {})
        if bt.get("analysis") and bt.get("posts"):   # الدفعة القديمة بتتحفظ في التاريخ
            calc = algo.batch_rows(bt["posts"], bt.get("metrics") or {})
            bt.setdefault("history", []).append({"at": bt.get("fetched_at"), "verdict": calc["verdict"], "best": calc["best"],
                                                 "hypothesis": (bt["analysis"] or {}).get("hypothesis", "")})
        bt.update(platform=platform, handle=handle, posts=posts, fetched_at=now(), analysis=None)
        bt["metrics"] = {k: v for k, v in (bt.get("metrics") or {}).items() if k in {str(p["id"]) for p in posts}}
    update_brain(bid, fn)


class BatchMetricIn(BaseModel):
    id: str
    leads: int | None = None
    follows: int | None = None


@app.patch("/api/batch/metric")
def batch_metric(body: BatchMetricIn):
    """العملاء/التسجيلات والمتابعين الذين جابهم كل فيديو (يكتبهم العميل من الإحصائيات أو ManyChat)."""
    bid = rivals_client()

    def fn(d):
        m = d.setdefault("batch", {}).setdefault("metrics", {})
        m[body.id] = {"leads": max(0, body.leads) if body.leads is not None else None, "follows": max(0, body.follows) if body.follows is not None else None}
    update_brain(bid, fn)
    return batch_out(bid)


@app.post("/api/batch/analyze")
def batch_analyze():
    bid = rivals_client()
    batch_run(bid)
    return batch_out(bid)


def batch_run(bid: str) -> None:
    brain = brain_row(bid) or {}
    bt = brain.get("batch") or {}
    if not bt.get("posts"):
        raise HTTPException(400, "اجلب الفيديوهات أولًا")
    calc = algo.batch_rows(bt["posts"], bt.get("metrics") or {})
    if atlas.mock_mode():
        res = algo.mock_batch(calc)
    else:
        try:
            raw = az.parse_json(atlas.chat(algo.batch_messages(az.brain_text(brain), algo.strategy_text(brain), calc), carousel_settings()["text_model"],
                                           temperature=0.5, max_tokens=7000, json_mode=True, timeout=300), "تحليل الدفعة")
        except (ValueError, atlas.AtlasError, httpx.HTTPError) as exc:
            raise HTTPException(502, f"التحليل لم يكتمل: {str(getattr(exc, 'detail', None) or exc)[:200]}") from exc
        res = algo.clean_batch(raw)
    res["at"] = now()

    def fn(d):
        d.setdefault("batch", {})["analysis"] = res
    update_brain(bid, fn)


def batch_auto() -> None:
    """⚡ كل ١٠ منشورات تُنشر: آخر ١٠ فيديوهات تتجاب وتتحلل تلقائيًا، والنتيجة تدخل في الأفكار القادمة."""
    bid = active_client_id()
    brain = brain_row(bid) if bid else None
    bt = (brain or {}).get("batch") or {}
    if not brain or not algo.mode_on(brain) or not bt.get("handle"):
        return
    with closing(db()) as conn:
        n = conn.execute("SELECT COUNT(*) FROM posts WHERE status = 'published'").fetchone()[0]
    if n - int(bt.get("auto_n") or 0) < algo.BATCH_EVERY:
        return

    def mark(d):
        d.setdefault("batch", {})["auto_n"] = n
    update_brain(bid, mark)   # قبل الشغل علشان مايتكررش لو بوستين اتنشروا مع بعض

    def work():
        try:
            batch_pull(bid, bt["handle"], bt.get("platform") or "tiktok")
            batch_run(bid)
            notify("batch", "ok", "📊 الدفعة حُلّلت تلقائيًا", f"آخر {algo.BATCH} فيديوهات اتحللوا، والأفكار القادمة ستسير على النتيجة", "7", bid)
        except Exception as exc:  # noqa: BLE001
            notify("batch", "bad", "📊 تحليل الدفعة التلقائي لم يكتمل", str(getattr(exc, "detail", None) or exc)[:200], "7", bid)
    threading.Thread(target=work, daemon=True).start()


class TriageIn(BaseModel):
    post: str = ""
    platform: str = ""
    keyword: str = ""      # كلمة الـ CTA اللي الناس بتكتبها في الكومنت
    dm_hint: str = ""      # الرسالة الخاصة لازم تقول إيه (مثلًا اللينك)
    comments: list[dict] = []


@app.post("/api/inbox/triage")
def inbox_triage(body: TriageIn):
    """يفرز التعليقات (عميل محتمل / سؤال / الكلمة / مشكلة / مدح / سبام) ويُجهّز رد لكل واحد، ورسالة خاصة للي تحتاجها."""
    coms = [{"id": str(c.get("id") or ""), "name": str(c.get("name") or "")[:60], "text": str(c.get("text") or "")[:500]}
            for c in body.comments if c.get("id") and str(c.get("text") or "").strip()][:60]
    if not coms:
        raise HTTPException(400, "لا يوجد تعليقات تحتاج رد")
    raw = growth.mock_triage(coms, body.keyword) if atlas.mock_mode() else growth_json(
        growth.triage_messages(growth_brand(), body.post, body.platform, body.keyword.strip()[:40], body.dm_hint.strip()[:400], coms), "فرز التعليقات")
    ids = {c["id"]: c for c in coms}
    out = []
    for it in raw.get("items") or []:
        cid = str(it.get("id") or "").strip("[] ")
        if cid not in ids:
            continue
        kind = str(it.get("type") or "other")
        if growth.keyword_hit(ids[cid]["text"], body.keyword):
            kind = "keyword"   # الكلمة نفسها مكتوبة: أكيد
        kind = kind if kind in growth.KINDS else "other"
        out.append({"id": cid, "type": kind, "label": growth.KINDS[kind], "reply": str(it.get("reply") or "").strip()[:600],
                    "dm": str(it.get("dm") or "").strip()[:800]})
    counts = {k: sum(1 for o in out if o["type"] == k) for k in growth.KINDS}
    return {"items": out, "counts": counts, "labels": growth.KINDS}


class ViralIn(BaseModel):
    niche: str = ""
    items: list[dict] = []   # [{url, account, hook, views, avg}]


@app.post("/api/viral")
def viral_finder(body: ViralIn):
    """«ما حسنًا في مجالك»: كل منشور بمشاهداته ÷ متوسط حسابه، وتحليل له الأعلى نجحوا، وأفكار بنفس الهيكل للعلامة."""
    rows = growth.outliers([i for i in body.items if isinstance(i, dict)][:30])
    if not rows:
        raise HTTPException(400, "أضف منشور واحد على الأقل")
    if not any(r["multiple"] for r in rows):
        raise HTTPException(400, "اكتب مشاهدات المنشور ومتوسط مشاهدات الحساب لكي نحسب المضاعف")
    raw = growth.mock_viral(rows) if atlas.mock_mode() else growth_json(growth.viral_messages(growth_brand(), body.niche.strip()[:200], rows), "التحليل")
    return {"rows": rows, "top": raw.get("top") or [], "pattern": str(raw.get("pattern") or ""), "ideas": raw.get("ideas") or []}


# ---------------------------------------------------------------- 🏆 منافسينك في المجال (rivals.py)
import rivals  # noqa: E402

RIVALS_BUSY: set[str] = set()


def brain_rivals(text: str, brain: dict | None) -> str:
    """ملف العلامة + ما ينجح عند المنافسين (للأفكار والنصوص والخطافات)."""
    rv = "\n\n".join(x for x in (algo.strategy_text(brain), algo.batch_text(brain), rivals.insight_text(brain)) if x)   # خطة المحتوى المعتمدة + المنافسين
    return text + (f"\n\n{rv}" if rv else "")


def rivals_state(bid: str) -> dict:
    return (brain_row(bid) or {}).get("competitors") or {}


def rivals_set(bid: str, **kw) -> None:
    def fn(d):
        c = d.setdefault("competitors", {})
        c.update(kw)
    update_brain(bid, fn)


def rivals_llm(messages: list[dict], what: str) -> dict:
    try:
        return az.parse_json(llm(messages, json_mode=True, temperature=0.4), what)
    except ValueError as exc:
        raise rivals.RivalsError(f"العقل استعد رد غير مفهوم ({what})") from exc


def rivals_fetch(platform: str, handle: str) -> dict:
    posts = rivals.mock_posts(platform, handle) if not rivals.live() else rivals.profile_posts(platform, handle)
    if not posts:
        raise rivals.RivalsError(f"لم أجد منشورات للحساب @{handle} على {rivals.PLATFORMS.get(platform, platform)}")
    it = rivals.summarize(platform, handle, posts)
    if rivals.live():   # الكلام المنطوق في أول بوستين: الهوك الحقيقي غالبًا مش في الكابشن
        for p in it["posts"][:2]:
            p["spoken"] = rivals.transcript(platform, p["url"])
    return it


def rivals_digest(brain: dict, items: list[dict]) -> dict:
    if not items:
        return {}
    if atlas.mock_mode():
        return rivals.mock_digest()
    return rivals.clean_digest(rivals_llm(rivals.digest_messages(brain, items), "تحليل المنافسين"))


def rivals_job(bid: str, step: str, fn) -> None:
    if bid in RIVALS_BUSY:
        raise HTTPException(409, "ما زال يعمل على المنافسين، انتظر قليلًا")
    RIVALS_BUSY.add(bid)
    rivals_set(bid, status="working", step=step, error=None)

    def run():
        try:
            fn()
            rivals_set(bid, status="ready", step=None, error=None, updated_at=time.time())
        except Exception as exc:  # noqa: BLE001
            rivals_set(bid, status="failed", step=None, error=str(getattr(exc, "detail", None) or exc)[:300])
        finally:
            RIVALS_BUSY.discard(bid)
    threading.Thread(target=run, daemon=True).start()


def rivals_key(i: dict) -> str:
    return f"{i['platform']}:{i['handle'].lower()}"


def rivals_search(bid: str, brain: dict, queries: list[str] | None = None) -> tuple[list[dict], list[str]]:
    """يبحث في المجال بكلام الأشخاص في السوق: منها نطلّع المنافسين والترند (أعلى منشورات آخر ٣٠ يوم)."""
    rivals_set(bid, step="يبحث في المجال…")
    if not rivals.live():
        return rivals.mock_search(brain), queries or ["تجربة"]
    qs = queries
    if not qs:
        raw = {} if atlas.mock_mode() else rivals_llm(rivals.queries_messages(brain), "كلمات البحث")
        qs = [str(q).strip()[:60] for q in raw.get("queries") or [] if str(q).strip()][:6] or [brain.get("domain") or brain.get("name") or ""]
    posts, errs = [], []
    for q in qs:
        for plat in rivals.PLATFORMS:
            try:
                posts += rivals.search(plat, q)
            except rivals.RivalsError as exc:
                errs.append(str(exc))
    if not posts and errs:
        raise rivals.RivalsError(errs[0])
    return posts, qs


def rivals_merge(bid: str, fresh: dict[str, dict] | None = None, found: list[dict] | None = None) -> None:
    """يكتب نتيجة العمل على الحالة الحالية: ما وافقت عليه أو رفضته وأنت ينتظر يظل كما هو."""
    fresh, found = fresh or {}, found or []

    def fn(d):
        cc = d.setdefault("competitors", {})
        ex = set(cc.get("excluded") or [])
        out = []
        for i in cc.get("items") or []:
            f = fresh.get(rivals_key(i))
            out.append({**f, **{k: i.get(k) for k in ("id", "why", "state", "pinned") if k in i}} if f else i)
        have = {rivals_key(i) for i in out}
        out += [f for f in found if rivals_key(f) not in have and rivals_key(f) not in ex]
        cc["items"] = out
    update_brain(bid, fn)


def rivals_discover(bid: str) -> None:
    """يجلب اقتراحات منافسين حتى ما يصبح فيه ١٠ ينتظرون موافقتك (المعتمدين واللي رفضتهم مابيتلمسوش)."""
    brain = brain_row(bid) or {}
    c = brain.get("competitors") or {}
    items = c.get("items") or []
    exclude = set(c.get("excluded") or []) | {rivals_key(i) for i in items}
    need = min(rivals.SUGGEST - sum(1 for i in items if not rivals.is_ok(i)), rivals.MAX_OK + rivals.SUGGEST - len(items))
    posts, qs = rivals_search(bid, brain)
    rivals_set(bid, trending=rivals.trending(posts), queries=qs, found_at=time.time())
    calls, found = len(qs) * len(rivals.PLATFORMS), []
    if need > 0:
        cands = rivals.candidates(posts, exclude)[:25]
        if not cands and not items:
            raise rivals.RivalsError("لم أجد حسابات في هذا المجال، جرّب تكتب «المجال» و«السوق» بشكل أوضح في الهوية")
        picks = []
        if atlas.mock_mode() or len(cands) <= need:
            picks = [{"i": k, "why": "من أعلى المشاهدات في البحث"} for k in range(min(need, len(cands)))]
        else:
            for p in rivals_llm(rivals.pick_messages(brain, cands, need), "اختيار المنافسين").get("picks") or []:
                try:
                    k = int(p.get("i"))
                except (TypeError, ValueError, AttributeError):
                    continue
                if 0 <= k < len(cands) and k not in [x["i"] for x in picks]:
                    picks.append({"i": k, "why": str(p.get("why") or "")[:200]})
            picks = picks[:need] or [{"i": k, "why": ""} for k in range(min(need, len(cands)))]
        for n, p in enumerate(picks):
            cd = cands[p["i"]]
            rivals_set(bid, step=f"يجلب منشورات @{cd['handle']} ({n + 1}/{len(picks)})…")
            calls += 3
            try:
                it = rivals_fetch(cd["platform"], cd["handle"])
            except rivals.RivalsError:
                continue
            found.append({**it, "id": uuid.uuid4().hex[:8], "why": p["why"], "state": "pending", "updated": time.time()})
    rivals_merge(bid, found=found)
    if rivals.live() and not atlas.mock_mode():
        wallet.charge(wallet.credits(wallet.est(scrape=calls, chars=12000)), "المنافسين: اقتراح منافسين", bid)


def rivals_refresh(bid: str, only: str | None = None, search: bool = True) -> None:
    """يحدّث منشورات المنافسين المعتمدين (أو واحد فقط)، والترند بنفس كلمات البحث."""
    brain = brain_row(bid) or {}
    c = brain.get("competitors") or {}
    calls = 0
    if search and not only:
        posts, qs = rivals_search(bid, brain, c.get("queries") or None)
        rivals_set(bid, trending=rivals.trending(posts), queries=qs)
        calls += len(qs) * len(rivals.PLATFORMS)
    todo = [i for i in c.get("items") or [] if (i["id"] == only if only else rivals.is_ok(i))]
    fresh = {}
    for n, it in enumerate(todo):
        rivals_set(bid, step=f"يحدّث @{it['handle']} ({n + 1}/{len(todo)})…")
        calls += 3
        try:
            fresh[rivals_key(it)] = {**it, **rivals_fetch(it["platform"], it["handle"]), "updated": time.time(), "error": None}
        except rivals.RivalsError as exc:
            fresh[rivals_key(it)] = {**it, "error": str(exc)[:200]}
    rivals_merge(bid, fresh=fresh)
    if calls and rivals.live() and not atlas.mock_mode():
        wallet.charge(wallet.credits(wallet.est(scrape=calls)), "المنافسين: تحديث المنشورات", bid)


def rivals_cycle(bid: str) -> None:
    """كل أسبوع: منشورات المعتمدين تُحدّث، وتأتي اقتراحات جديدة تنتظر موافقتك."""
    rivals_refresh(bid, search=False)
    rivals_discover(bid)


def rivals_audience_urls(items: list[dict]) -> list[tuple[str, str]]:
    return [(i["platform"], p["url"]) for i in items[:10] for p in (i.get("posts") or [])[:2] if p.get("url")]


def rivals_brief_cost(items: list[dict]) -> int:
    return wallet.credits(wallet.est(scrape=len(rivals_audience_urls(items)) * 3, chars=40000))


def rivals_brief(bid: str) -> None:
    """من المنافسين المعتمدين فقط: «ما ينجح لديهم» + 🎯 وصفة الاستهداف (نص جمهورهم بدون أسامي + هاشتاجاتهم)."""
    brain = brain_row(bid) or {}
    items = rivals.approved(brain.get("competitors") or {})
    sg = rivals.sig(items)
    rivals_set(bid, step="يحلّل ما ينجح لديهم…")
    digest = rivals_digest(brain, items)
    if not rivals.live() or atlas.mock_mode():
        aud, n = rivals.mock_audience(), 0
    else:
        said, urls = [], rivals_audience_urls(items)
        for k, (plat, url) in enumerate(urls):
            rivals_set(bid, step=f"يقرأ نص الجمهور ({k + 1}/{len(urls)})…")
            said += rivals.comments(plat, url, 40)
        rivals_set(bid, step="يكتب وصفة الاستهداف…")
        tags = rivals.hashtags([p for i in items for p in i["posts"]])
        aud = rivals.clean_audience(rivals_llm(rivals.audience_messages(brain, items, said, tags), "وصفة الاستهداف"))
        wallet.charge(rivals_brief_cost(items), "المنافسين: التحليل ووصفة الاستهداف", bid)
        n = len(said)
    rivals_set(bid, digest=digest, audience={**aud, "comments": n, "rivals": len(items), "sig": sg, "at": time.time()})


RIVALS_SETTLE = 6   # ثواني بعد آخر موافقة/رفض قبل ما الوصفة تتعمل (علشان لو بتوافق على كذا واحد ورا بعض)


def rivals_auto(bid: str) -> None:
    """العمل التلقائي (يتشيّك عندما الصفحة تُفتح أو تُحدّث، بدون ثريد يعمل مباشرة):
    لا يوجد منافسين ← يجلب اقتراحات · عدّى أسبوع ← تحديث واقتراحات جديدة · المعتمدين تغيّرون ← التحليل والوصفة."""
    if bid in RIVALS_BUSY:
        return
    b = brain_row(bid) or {}
    c = b.get("competitors") or {}
    now_ = time.time()
    try:
        if not c.get("items") and (b.get("domain") or b.get("about")):
            if now_ - float(c.get("auto_at") or 0) > 6 * 3600:   # لو فشل مانعيدش كل شوية
                rivals_set(bid, auto_at=now_)
                rivals_job(bid, "يبحث عن منافسين في مجالك…", lambda: rivals_discover(bid))
            return
        if c.get("items") and now_ - float(c.get("found_at") or c.get("updated_at") or 0) > rivals.STALE and now_ - float(c.get("auto_at") or 0) > 6 * 3600:
            rivals_set(bid, auto_at=now_)
            rivals_job(bid, "يحدّث المنافسين ويجلب اقتراحات جديدة…", lambda: rivals_cycle(bid))
            return
        ok = rivals.approved(c)
        sg = rivals.sig(ok)
        tried = c.get("brief_try") or {}
        if ok and sg != (c.get("audience") or {}).get("sig") and now_ - float(c.get("reviewed_at") or 0) > RIVALS_SETTLE \
                and not (tried.get("sig") == sg and now_ - float(tried.get("at") or 0) < 3600):
            rivals_set(bid, brief_try={"sig": sg, "at": now_})
            if rivals.live() and not atlas.mock_mode():
                wallet.need(rivals_brief_cost(ok), "وصفة الاستهداف")
            rivals_job(bid, "يعمل وصفة الاستهداف من منافسوك…", lambda: rivals_brief(bid))
    except HTTPException as exc:   # الرصيد خلص أو شغل تاني شغال: نبيّنها ونكمّل
        rivals_set(bid, status="failed", step=None, error=str(exc.detail)[:300])
    except wallet.NoCredits as exc:
        rivals_set(bid, status="failed", step=None, error=str(exc)[:300])


def rivals_out(bid: str) -> dict:
    b = brain_row(bid) or {}
    c = b.get("competitors") or {}
    items = [{**i, "state": "approved" if rivals.is_ok(i) else "pending"} for i in c.get("items") or []]
    ok = rivals.approved(c)
    aud = c.get("audience") or {}
    return {"client": bid, "name": b.get("name"), "live": rivals.live(), "platforms": rivals.PLATFORMS, "top": rivals.SUGGEST, "max_ok": rivals.MAX_OK,
            "algo_mode": algo.mode_on(b), "brain": {k: b.get(k) or "" for k in ("domain", "market", "audience", "language")},
            "items": items, "approved": sum(1 for i in items if i["state"] == "approved"), "pending": sum(1 for i in items if i["state"] == "pending"),
            "digest": c.get("digest") or {}, "trending": c.get("trending") or [], "status": c.get("status") or "", "step": c.get("step"),
            "error": c.get("error"), "updated_at": c.get("updated_at"), "found_at": c.get("found_at"), "excluded": len(c.get("excluded") or []),
            "audience": aud, "brief_due": bool(ok) and rivals.sig(ok) != aud.get("sig"), "audiences": b.get("audiences") or []}


def rivals_client() -> str:
    bid = active_client_id()
    if not bid:
        raise HTTPException(400, "أنشئ علامة أولًا")
    return bid


@app.get("/api/rivals")
def rivals_get():
    """«منافسوك»: الاقتراحات والتحديث والوصفة يحصلون تلقائيًا، وأنت توافق أو ترفض فقط."""
    bid = rivals_client()
    c = rivals_state(bid)
    if c.get("status") == "working" and bid not in RIVALS_BUSY:   # السيرفر اتعمله ريستارت والشغل وقف
        rivals_set(bid, status="failed", step=None, error="العمل توقف، سيُكمل تلقائيًا المرة القادمة")
    else:
        rivals_auto(bid)
    return rivals_out(bid)


@app.post("/api/rivals/discover")
def rivals_discover_ep():
    """اجلب اقتراحات زيادة الآن (حتى ١٠ ينتظرون موافقتك)."""
    bid = rivals_client()
    b = brain_row(bid) or {}
    if not (b.get("domain") or b.get("about")):
        raise HTTPException(400, "اكتب «المجال» في فرع الهوية أولًا، لكي نعرف ندوّر أين")
    if rivals.live() and not atlas.mock_mode():
        wallet.need(wallet.credits(wallet.est(scrape=40, chars=12000)), "اقتراح منافسين")
    rivals_job(bid, "يبحث عن منافسين في مجالك…", lambda: rivals_discover(bid))
    return rivals_out(bid)


@app.post("/api/rivals/refresh")
def rivals_refresh_ep(rid: str = ""):
    bid = rivals_client()
    rivals_job(bid, "يحدّث منشورات المنافسين…", lambda: rivals_refresh(bid, rid or None))
    return rivals_out(bid)


@app.post("/api/rivals/audience")
def rivals_audience_ep():
    """يعيد التحليل والوصفة الآن (إذا فشلت من قبل). بدون منافسين معتمدين لا يوجد وصفة."""
    bid = rivals_client()
    ok = rivals.approved(rivals_state(bid))
    if not ok:
        raise HTTPException(400, "يجب الموافقة على المنافسين الموجودين في صفحة المنافسين: يجب يصبح فيه منافس معتمد لكي الوصفة تُنشأ")
    if rivals.live() and not atlas.mock_mode():
        wallet.need(rivals_brief_cost(ok), "وصفة الاستهداف")
    rivals_set(bid, brief_try={"sig": rivals.sig(ok), "at": time.time()})
    rivals_job(bid, "يعمل وصفة الاستهداف من منافسوك…", lambda: rivals_brief(bid))
    return rivals_out(bid)


class RivalAddIn(BaseModel):
    handle: str
    platform: str = ""
    replace: str = ""   # id المنافس اللي هيتشال ويتحط ده مكانه


@app.post("/api/rivals/add")
def rivals_add(body: RivalAddIn):
    """تضيف حساب بنفسك (أو تبدّل واحد به). ما تضيفه يصبح معتمد مباشرة."""
    bid = rivals_client()
    handle = rivals.clean_handle(body.handle)
    plat = body.platform if body.platform in rivals.PLATFORMS else rivals.guess_platform(body.handle)
    if not handle:
        raise HTTPException(400, "اكتب اسم الحساب أو الرابط الخاص به")
    items = rivals_state(bid).get("items") or []
    if any(rivals_key(i) == f"{plat}:{handle.lower()}" for i in items):
        raise HTTPException(400, "هذا الحساب موجود بالفعل")
    if not body.replace and sum(rivals.is_ok(i) for i in items) >= rivals.MAX_OK:
        raise HTTPException(400, f"أقصى شيء {rivals.MAX_OK} منافس معتمد، أزل واحد أولًا")

    def work():
        it = rivals_fetch(plat, handle)
        new = {**it, "id": uuid.uuid4().hex[:8], "why": "أنت ما ضفته", "state": "approved", "updated": time.time()}

        def fn(d):
            cc = d.setdefault("competitors", {})
            lst = cc.get("items") or []
            gone = [i for i in lst if i["id"] == body.replace]
            if gone:
                cc["excluded"] = list({*(cc.get("excluded") or []), rivals_key(gone[0])})[-200:]
                lst = [new if i["id"] == body.replace else i for i in lst]
            else:
                lst = lst + [new]
            cc["items"] = lst
            cc["reviewed_at"] = time.time()
        update_brain(bid, fn)
    rivals_job(bid, f"يجلب منشورات @{handle}…", work)
    return rivals_out(bid)


class RivalReviewIn(BaseModel):
    approve: bool
    ids: list[str] = []   # فاضي = كل اللي مستنيين موافقتك


def rivals_review_apply(bid: str, ids: set[str] | None, approve: bool) -> None:
    def fn(d):
        cc = d.setdefault("competitors", {})
        lst = cc.get("items") or []
        hit = [i for i in lst if (i["id"] in ids if ids else not rivals.is_ok(i))]
        if approve:
            room = rivals.MAX_OK - sum(rivals.is_ok(i) for i in lst)
            for i in hit:
                if not rivals.is_ok(i) and room > 0:
                    i["state"], room = "approved", room - 1
        else:   # اللي بترفضه بيتشال ومايتقترحش تاني
            gone = {i["id"] for i in hit}
            cc["excluded"] = list({*(cc.get("excluded") or []), *(rivals_key(i) for i in hit)})[-300:]
            cc["items"] = [i for i in lst if i["id"] not in gone]
        cc["reviewed_at"] = time.time()
    update_brain(bid, fn)


@app.post("/api/rivals/review")
def rivals_review(body: RivalReviewIn):
    """✅ وافق / ✕ ارفض: على واحد أو أكثر، أو على كل الاقتراحات مرة واحدة."""
    bid = rivals_client()
    if body.approve and sum(rivals.is_ok(i) for i in rivals_state(bid).get("items") or []) >= rivals.MAX_OK:
        raise HTTPException(400, f"أقصى شيء {rivals.MAX_OK} منافس معتمد، أزل واحد أولًا")
    rivals_review_apply(bid, set(body.ids) or None, body.approve)
    return rivals_out(bid)


@app.delete("/api/rivals/{rid}")
def rivals_delete(rid: str):
    """تزيله (معتمد أو اقتراح)، ومايرجعش آخر في البحث."""
    bid = rivals_client()
    rivals_review_apply(bid, {rid}, False)
    return rivals_out(bid)


@app.post("/api/rivals/reset-excluded")
def rivals_reset_excluded():
    bid = rivals_client()
    rivals_set(bid, excluded=[])
    return rivals_out(bid)


# ---------------------------------------------------------------- 📣 إعلاناتك (adsmgr.py): ترويج بوست، إعلان جديد، جماهير. الاستهداف من 🎯 الوصفة
import adsmgr  # noqa: E402
import csv  # noqa: E402
import io  # noqa: E402

ADS_BOOSTABLE = ("facebook", "instagram", "tiktok", "linkedin", "pinterest", "x")


def ads_fee() -> int:
    """رسوم البرنامج على كل إعلان يُنشأ (مال الإعلان نفسها تتدفع للمنصة من حساب إعلانات العميل)."""
    try:
        return wallet.credits(float(os.environ.get("ADS_FEE_USD", "0.5")))
    except ValueError:
        return wallet.credits(0.5)


def ads_call(fn, *a, **kw):
    try:
        return fn(*a, **kw)
    except (adsmgr.AdsError, publisher.PublishError, httpx.HTTPError) as exc:
        raise HTTPException(400, str(exc)) from exc


def ads_mine(bid: str) -> list[dict]:
    return list((brain_row(bid) or {}).get("ads") or [])


def ads_remember(bid: str, ad: dict) -> None:
    def fn(d):
        d["ads"] = [*(d.get("ads") or []), ad][-300:]
    update_brain(bid, fn)


def ads_own(bid: str, ad_id: str) -> dict:
    hit = next((a for a in ads_mine(bid) if a["id"] == ad_id), None)
    if not hit:
        raise HTTPException(404, "هذا الإعلان لا الخاص بـ هذا العلامة")
    return hit


def ads_social() -> list[dict]:
    if publisher.service_name() == "mock":
        return MOCK_ACCOUNTS
    try:
        return [a for a in publisher.account_list() if acct_visible(a["id"])]
    except (publisher.PublishError, httpx.HTTPError):
        return []


def ads_recipe(bid: str) -> dict:
    """الاستهداف الجاهز من «🎯 وصفة الاستهداف» (إذا أُنشئت من منافسين معتمدين)."""
    c = rivals_state(bid)
    a = c.get("audience") or {}
    if not a.get("sig") or not rivals.approved(c):
        return {}
    m = a.get("meta") or {}
    return {"age": m.get("age") or [18, 45], "gender": m.get("gender") or "all", "countries": adsmgr.countries(m.get("locations") or []),
            "locations": m.get("locations") or [], "interests": m.get("interests") or [], "tt_interests": (a.get("tiktok") or {}).get("tt_interests") or [],
            "keywords": (a.get("google") or {}).get("keywords") or [], "negative": (a.get("google") or {}).get("negative") or [],
            "angles": a.get("angles") or [], "budget": a.get("budget") or "", "summary": a.get("summary") or ""}


@app.get("/api/ads")
def ads_get():
    bid = rivals_client()
    service = publisher.service_name()
    out = {"ready": service in ("zernio", "mock"), "mock": service == "mock", "platforms": {k: v[1] for k, v in adsmgr.PLATFORMS.items()},
           "goals": {k: adsmgr.goals_for(k) for k in adsmgr.PLATFORMS}, "ctas": adsmgr.CTAS, "min_budget": adsmgr.MIN_BUDGET, "fee": ads_fee(),
           "same_token": sorted(adsmgr.SAME_TOKEN), "social": ads_social(), "ad_accounts": [], "ads": [], "error": None, "recipe": ads_recipe(bid)}
    if not out["ready"]:
        return out
    try:
        out["ad_accounts"] = adsmgr.ad_accounts()
        mine = {a["id"]: a for a in ads_mine(bid)}
        live = {a["id"]: a for a in adsmgr.list_ads(set(mine))} if mine else {}
        out["ads"] = [{**m, **live.get(i, {"status": "unknown"})} for i, m in reversed(mine.items())]
    except (adsmgr.AdsError, publisher.PublishError, httpx.HTTPError) as exc:
        out["error"] = str(exc)[:300]
    with closing(db()) as conn:
        rows = conn.execute(POSTS_QUERY + " WHERE own(p.client_id) AND p.status = 'published' AND p.remote_id IS NOT NULL ORDER BY p.published_at DESC LIMIT 40").fetchall()
        out["posts"] = [{"id": r["id"], "caption": (r["caption"] or "")[:160], "published_at": r["published_at"], "name": r["export_name"] or r["carousel_name"] or "",
                         "platforms": [publisher.split_target(t)[0] for t in json.loads(r["platforms"]) if publisher.split_target(t)[0] in ADS_BOOSTABLE]}
                        for r in rows]
        out["posts"] = [p for p in out["posts"] if p["platforms"]]
        out["exports"] = [{"id": r["id"], "name": r["name"], "url": f"/media/exports/{r['filename']}"}
                          for r in conn.execute("SELECT id, name, filename FROM exports WHERE own(client_id) ORDER BY created_at DESC LIMIT 40")]
    return out


