LOGO_DEFAULTS = {"enabled": True, "size": 37, "x": 0, "y": 4, "opacity": 0.9, "on_outro": True}


def transcript_of(row: sqlite3.Row) -> dict:
    return json.loads(row["transcript"]) if row["transcript"] else {"status": "none", "words": []}


# ---------- ⚡ وضع الخوارزمية في المونتاج: تحليل بس (المحرر هو اللي بيطبّق ويحفظ، علشان مايتكتبش فوق شغل العميل)
def project_voice_words(conn: sqlite3.Connection, data: dict) -> tuple[str, list[dict]]:
    v = data.get("voice")
    if not v:
        return "none", []
    row = conn.execute("SELECT transcript FROM audio WHERE id = ?", (v["id"],)).fetchone()
    tr = transcript_of(row) if row else {"status": "none", "words": []}
    return tr.get("status") or "none", tr.get("words") or []


def project_silence_marks(conn: sqlite3.Connection, data: dict, min_len: float = algo.SILENCE_MIN) -> list[dict]:
    """السكتات في القطع التي بصوت: [{id, i (رقم القطعة), a, b, kind}] بأوقات الفيديو الأصلي."""
    clips = data.get("clips") or []
    n = len(clips)
    marks = []
    cache: dict[str, list] = {}
    for i, c in enumerate(clips):
        if c.get("disabled") or float(c.get("volume", 1) or 0) <= 0 or c.get("kf"):
            continue
        path = clip_source(conn, c["gen_id"])
        if not path or not media_info(path).has_audio:
            continue
        info = media_info(path)
        if str(path) not in cache:
            try:
                cache[str(path)] = silences(path, min(min_len, algo.SILENCE_MIN))
            except (subprocess.SubprocessError, OSError):
                cache[str(path)] = []
        a, b = float(c.get("start") or 0), float(c["end"] if c.get("end") is not None else info.duration)
        for m in algo.silence_marks(cache[str(path)], a, b, i == 0, i == n - 1, min_len):
            marks.append({"id": f"{i}-{m['a']}", "i": i, **m})
    return marks


def cut_silences(conn: sqlite3.Connection, data: dict, min_len: float) -> tuple[int, float]:
    """يشيل السكتات من القطع (كل قطعة تتقسم لحتت من غير السكوت، زي «احذف الأحمر» في المونتاج). يعود (عددها، ثوانيها)."""
    marks = project_silence_marks(conn, data, min_len)
    if not marks:
        return 0, 0.0
    out = []
    for i, c in enumerate(data.get("clips") or []):
        ms = sorted((m for m in marks if m["i"] == i), key=lambda m: m["a"])
        if not ms:
            out.append(c)
            continue
        path = clip_source(conn, c["gen_id"])
        end = float(c["end"]) if c.get("end") is not None else media_info(path).duration
        a, pieces = float(c.get("start") or 0), []
        for m in ms:
            if m["a"] - a > 0.05:
                pieces.append((a, m["a"]))
            a = max(a, m["b"])
        if end - a > 0.05:
            pieces.append((a, end))
        for k, (x, y) in enumerate(pieces):
            p = {**json.loads(json.dumps(c)), "start": round(x, 3), "end": round(y, 3)}
            if k:
                p.pop("trans", None)
            out.append(p)
    data["clips"] = out
    return len(marks), round(sum(m["b"] - m["a"] for m in marks), 1)


@app.post("/api/projects/{project_id}/algo-prep")
def project_algo_prep(project_id: str, min_sec: float = 0.0):
    """السكتات في الفيديوهات التي بصوت (بالأحمر للمراجعة)، وخطاف الشاشة، وحالة التعليق النصي.
    min_sec: أقل طول للسكتة (مستوى الإزالة: خفيف/متوسط/قوي)، والافتراضي algo.SILENCE_MIN."""
    min_len = min(2.0, max(0.25, min_sec)) if min_sec else algo.SILENCE_MIN
    with closing(db()) as conn:
        data = json.loads(get_project(conn, project_id)["data"])
        marks = project_silence_marks(conn, data, min_len)
        status, words = project_voice_words(conn, data)
    if data.get("voice") and status == "none":   # الكابشن محتاج الكلام مكتوب: بيبدأ يتكتب لوحده
        with closing(db()) as conn, conn:
            conn.execute("UPDATE audio SET transcript = ? WHERE id = ?", (json.dumps({"status": "working", "words": []}), data["voice"]["id"]))
        threading.Thread(target=run_transcribe, args=(data["voice"]["id"],), daemon=True).start()
        status = "working"
    hook = None
    texts = data.get("texts") or []
    if not any(float(x.get("t0") or 0) < 3 for x in texts if isinstance(x, dict)):
        context = data.get("hook_text") or ""
        if not context:
            context = " ".join(w["w"] for w in words[:40]) or data.get("name") or ""
        if data.get("hook_text"):
            hook = data["hook_text"]
        elif context.strip():
            if atlas.mock_mode():
                hook = "غلطة تعملها\nكل يوم"
            else:
                try:
                    hook = str(az.parse_json(llm(algo.hook_text_messages(context), json_mode=True, temperature=0.5), "خطاف الشاشة").get("text") or "").strip()[:80] or None
                except (ValueError, HTTPException, atlas.AtlasError, httpx.HTTPError):
                    hook = None
    return {"marks": marks, "hook": hook, "caps": status if data.get("voice") else "no_voice"}


@app.post("/api/projects/{project_id}/fillers")
def project_fillers(project_id: str):
    """الحشو (أمم/نعم) والنص المتكرر في الفيديوهات التي بصوت: يكتب نص كل قطعة (يُحسب من رصيد Atlas) ويعلّمه بالأحمر."""
    if not (atlas.api_key() or atlas.mock_mode()):
        raise HTTPException(400, "يحتاج مفتاح Atlas لكي يسمع النص")
    with closing(db()) as conn:
        data = json.loads(get_project(conn, project_id)["data"])
        jobs = []
        for i, c in enumerate(data.get("clips") or []):
            if c.get("disabled") or float(c.get("volume", 1) or 0) <= 0 or c.get("kf"):
                continue
            path = clip_source(conn, c["gen_id"])
            if path and media_info(path).has_audio:
                a = float(c.get("start") or 0)
                b = float(c["end"] if c.get("end") is not None else media_info(path).duration)
                jobs.append((i, path, a, b))
    marks = []
    for i, path, a, b in jobs[:20]:
        wav = TMP_DIR / f"fill_{uuid.uuid4().hex[:8]}.wav"
        try:
            subprocess.run([ffmpeg_exe(), "-y", "-loglevel", "error", "-ss", f"{a:.3f}", "-to", f"{b:.3f}", "-i", str(path), "-vn", "-ac", "1", "-ar", "16000", str(wav)],
                           check=True, timeout=120)
            words = atlas.transcribe(wav, b - a)
        except (subprocess.SubprocessError, OSError, atlas.AtlasError, httpx.HTTPError):
            continue
        finally:
            wav.unlink(missing_ok=True)
        for m in algo.filler_marks(words, a):
            if a <= m["a"] < m["b"] <= b:
                marks.append({"id": f"{i}-f{m['a']}", "i": i, **m})
    return {"marks": marks}


BEATS_CACHE: dict[str, dict] = {}


@app.get("/api/projects/{project_id}/beats")
def project_beats(project_id: str):
    """🎵 دقات المزيكا على التايم لاين (لكي القطع يأتي على الإيقاع مثل ريلز الأعمال)."""
    with closing(db()) as conn:
        data = json.loads(get_project(conn, project_id)["data"])
        m = data.get("music")
        row = conn.execute("SELECT filename FROM audio WHERE id = ? AND kind = 'music'", (m["id"],)).fetchone() if m else None
    if not row or not (AUDIO_DIR / row["filename"]).exists():
        raise HTTPException(400, "ضع مزيكا في المشروع أولًا")
    path = AUDIO_DIR / row["filename"]
    key = f"{row['filename']}:{path.stat().st_mtime}"
    if key not in BEATS_CACHE:
        BEATS_CACHE[key] = lab.beat_grid(lab.onsets(lab.pcm(ffmpeg_exe(), path), 2000), media_info(path).duration)
    g = BEATS_CACHE[key]
    if not g["beats"]:
        raise HTTPException(400, "لم أجد إيقاع واضح في هذه المزيكا")
    part = track_parts(m)[0]
    delay, offset = max(0.0, float(part.get("delay") or 0)), max(0.0, float(part.get("offset") or 0))
    return {"period": g["period"], "beats": [round(delay + t - offset, 3) for t in g["beats"] if t >= offset]}


