def set_transcript(audio_id: str, data: dict) -> None:
    with closing(db()) as conn, conn:
        conn.execute("UPDATE audio SET transcript = ? WHERE id = ?", (json.dumps(data, ensure_ascii=False), audio_id))


def run_transcribe(audio_id: str) -> None:
    with closing(db()) as conn:
        row = conn.execute("SELECT filename, duration FROM audio WHERE id = ?", (audio_id,)).fetchone()
    if row is None:
        return
    try:
        words = atlas.transcribe(AUDIO_DIR / row["filename"], row["duration"])
        set_transcript(audio_id, {"status": "done", "words": words, "edited": False})
    except httpx.HTTPError as exc:
        set_transcript(audio_id, {"status": "failed", "error": f"تعذّر الوصول لـ Atlas: {exc}"[:400], "words": []})
    except Exception as exc:  # الخطأ يبان للمستخدم بدل ما يضيع
        set_transcript(audio_id, {"status": "failed", "error": str(exc)[:400], "words": []})


@app.post("/api/audio/{audio_id}/transcribe")
def start_transcribe(audio_id: str):
    if not (atlas.api_key() or atlas.mock_mode()):
        raise HTTPException(400, "يحتاج مفتاح Atlas لكي يكتب النص. ضعه من ⚙️ الإعدادات")
    with closing(db()) as conn:
        row = conn.execute("SELECT transcript FROM audio WHERE id = ?", (audio_id,)).fetchone()
    if row is None:
        raise HTTPException(404, "الملف غير موجود")
    if transcript_of(row).get("status") == "working":
        return {"ok": True}
    set_transcript(audio_id, {"status": "working", "words": []})
    threading.Thread(target=run_transcribe, args=(audio_id,), daemon=True).start()
    return {"ok": True}


# 🌍 لغة الكابشن: الكلام بيتقسم جمل (بتوقيتها)، كل جملة بتتترجم، وكلمات الترجمة بتتوزع على وقت الجملة نفسها
CAPTION_LANGS = {"ar": "العربية", "en": "English", "fr": "Français", "es": "Español", "de": "Deutsch", "tr": "Türkçe",
                 "pt": "Português", "it": "Italiano", "id": "Bahasa Indonesia", "ur": "اردو"}
CAPTION_LANG_NAMES = {"ar": "Arabic (natural, simple Modern Standard or the brand's dialect)", "en": "English", "fr": "French", "es": "Spanish",
                      "de": "German", "tr": "Turkish", "pt": "Portuguese", "it": "Italian", "id": "Indonesian", "ur": "Urdu"}


def caption_phrases(words: list[dict]) -> list[list[dict]]:
    out, cur = [], []
    for w in words:
        if cur and (len(cur) >= 9 or w["s"] - cur[-1]["e"] > 0.7 or re.search(r"[.!?؟،,…]$", cur[-1]["w"])):
            out.append(cur)
            cur = []
        cur.append(w)
    if cur:
        out.append(cur)
    return out


def translate_words(words: list[dict], lang: str) -> list[dict]:
    phrases = caption_phrases(words)
    texts = [" ".join(w["w"] for w in g) for g in phrases]
    if atlas.mock_mode():
        lines = [f"[{lang}] {t}" for t in texts]
    else:
        msgs = [{"role": "system", "content": "You translate video captions. Translate each line into " + CAPTION_LANG_NAMES[lang]
                 + " so it reads naturally on screen: same meaning and tone, short, no notes, keep names and brands as they are. "
                   'Return exactly the same number of lines in the same order as JSON: {"lines": ["..."]}'},
                {"role": "user", "content": json.dumps({"lines": texts}, ensure_ascii=False)}]
        raw = flow_llm(msgs, "ترجمة التعليق النصي")
        lines = [str(x or "").strip() for x in (raw.get("lines") or [])]
        if len(lines) != len(texts):
            raise HTTPException(400, "الترجمة رجعت بعدد جمل مختلف، جرّب مرة أخرى")
    out = []
    for g, line in zip(phrases, lines):
        parts = line.split() or [g[0]["w"]]
        s0, e0 = g[0]["s"], g[-1]["e"]
        step = (e0 - s0) / len(parts)
        out += [{"w": t, "s": round(s0 + i * step, 3), "e": round(s0 + (i + 1) * step, 3)} for i, t in enumerate(parts)]
    return out


def caption_words(audio_id: str, lang: str) -> list[dict]:
    """نص التعليق النصي باللغة المطلوبة (متخزن مع النص الأصلي، ويُعاد إذا النص عُدّل)."""
    with closing(db()) as conn:
        row = conn.execute("SELECT transcript FROM audio WHERE id = ?", (audio_id,)).fetchone()
    if row is None:
        raise HTTPException(404, "الملف غير موجود")
    tr = transcript_of(row)
    if tr.get("status") != "done" or not tr.get("words"):
        raise HTTPException(400, "ما زال النص الخاص بالتعليق الصوتي لم يكتب")
    if not lang:
        return tr["words"]
    if lang not in CAPTION_LANGS:
        raise HTTPException(400, "لغة غير متاحة")
    h = hashlib.sha1(json.dumps(tr["words"], ensure_ascii=False).encode()).hexdigest()[:16]
    cached = (tr.get("tx") or {}).get(lang) or {}
    if cached.get("h") == h:
        return cached["words"]
    words = translate_words(tr["words"], lang)
    tr.setdefault("tx", {})[lang] = {"h": h, "words": words}
    set_transcript(audio_id, tr)
    return words


@app.get("/api/captions/langs")
def caption_langs():
    return CAPTION_LANGS


@app.get("/api/audio/{audio_id}/transcript/{lang}")
def get_transcript_lang(audio_id: str, lang: str):
    return {"lang": lang, "words": caption_words(audio_id, lang)}


class WordIn(BaseModel):
    w: str
    s: float
    e: float


class TranscriptIn(BaseModel):
    words: list[WordIn]


@app.put("/api/audio/{audio_id}/transcript")
def save_transcript(audio_id: str, body: TranscriptIn):
    words = sorted(
        ({"w": w.w.strip(), "s": round(max(0.0, w.s), 3), "e": round(max(w.s, w.e), 3)} for w in body.words if w.w.strip()),
        key=lambda w: w["s"],
    )
    with closing(db()) as conn:
        if not conn.execute("SELECT 1 FROM audio WHERE id = ?", (audio_id,)).fetchone():
            raise HTTPException(404, "الملف غير موجود")
    set_transcript(audio_id, {"status": "done", "words": words, "edited": True})
    return {"status": "done", "words": words, "edited": True}


