ASSET_KINDS = {"template": "تيمبليت", "character": "شخصية", "coach": "شخصية", "style": "أسلوب رسم"}
ASSET_MAX_FILES = 12
# صيغ تانية بتتحول PNG لوحدها (صور الآيفون وصور المواقع)
CONVERT_EXTENSIONS = {".heic", ".heif", ".avif", ".gif", ".bmp", ".tif", ".tiff", ".jfif"}


