class ProviderMinIn(BaseModel):
    key: str
    min: float


@app.put("/api/admin/providers/min")
def admin_providers_min(body: ProviderMinIn):
    """حد التنبيه: إذا الرصيد قل عنه يوصلك جرس وبريد إلكتروني."""
    if body.key not in providers.PROVIDERS:
        raise HTTPException(404, "منصة غير معروفة")
    d = providers.load(PROVIDERS_FILE)
    d["min"][body.key] = max(0.0, float(body.min))
    d["alerted"].pop(body.key, None)
    providers.save(PROVIDERS_FILE, d)
    return providers_out()


@app.post("/api/admin/providers/{key}/clear")
def admin_providers_clear(key: str):
    """للمنصات التي ليس لها API رصيد (AudioShake وفصيح): «شحنت» تحذف آخر غلطة."""
    d = providers.load(PROVIDERS_FILE)
    cur = d["p"].get(key) or {}
    cur.pop("fail", None)
    cur.pop("balance", None) if not providers.PROVIDERS.get(key, {}).get("api") else None
    cur["ok"] = True
    d["p"][key] = cur
    d["alerted"].pop(key, None)
    providers.save(PROVIDERS_FILE, d)
    return providers_out()


@app.get("/api/atlas/money")
def atlas_money():
    """الرصيد الآن، وصُرف قدر ماذا اليوم هذا والأسبوع، وعدد الطلبات لكل نموذج في آخر يومين."""
    if atlas.mock_mode():
        return {"balance": 10.5, "currency": "usd", "spent_today": 0.42, "spent_week": 3.1, "tracked_since": now(),
                "models_recent": [{"name": "kwaivgi/kling-v2.6-pro/avatar", "type": "video", "requests": 2}]}
    if not atlas.api_key():
        raise HTTPException(400, "مفتاح Atlas غير مسجل")
    try:
        with httpx.Client(timeout=20) as client:
            b = client.get(f"{ATLAS_PUBLIC}/balance", headers=atlas._headers()).json()
            today = datetime.now(MONEY_TZ).date()
            u = client.get(f"{ATLAS_PUBLIC}/usage", headers=atlas._headers(),
                           params={"start_date": str(today - timedelta(days=1)), "end_date": str(today + timedelta(days=1)),
                                   "group_by[]": "model"}).json()
    except (httpx.HTTPError, ValueError) as exc:
        raise HTTPException(502, f"Atlas لا يرد: {exc}") from exc
    bal = float(((b or {}).get("available") or {}).get("value") or 0)
    log = money_log()
    if not log or abs(log[-1]["v"] - bal) > 1e-6:
        log.append({"t": datetime.now(MONEY_TZ).isoformat(timespec="seconds"), "v": bal})
        auth.set_setting("atlas_balance_log", json.dumps(log[-2000:]))
    midnight = datetime.now(MONEY_TZ).replace(hour=0, minute=0, second=0, microsecond=0)
    models: dict[str, dict] = {}
    for bucket in (u or {}).get("data") or []:  # إمبارح والنهارده (أيام Atlas بتوقيت UTC)
        for r in bucket.get("results") or []:
            m = r.get("model") or {}
            x = models.setdefault(m.get("name") or "?", {"name": m.get("name") or "?", "type": m.get("type", ""), "requests": 0})
            x["requests"] += int((r.get("usage") or {}).get("requests") or 0)
    return {"balance": bal, "currency": ((b or {}).get("available") or {}).get("currency", "usd"),
            "spent_today": spent_since(log, midnight), "spent_week": spent_since(log, midnight - timedelta(days=6)),
            "tracked_since": log[0]["t"], "models_recent": sorted(models.values(), key=lambda x: -x["requests"])}


def ad_dir(aid: str) -> Path:
    d = ADS_DIR / Path(aid).name
    (d / "frames").mkdir(parents=True, exist_ok=True)
    return d


def ad_row(conn: sqlite3.Connection, aid: str) -> tuple[sqlite3.Row, dict]:
    r = conn.execute("SELECT * FROM ads WHERE id = ?", (aid,)).fetchone()
    if r is None:
        raise HTTPException(404, "الإعلان غير موجود")
    return r, json.loads(r["data"])


def bump(d: dict, key: str) -> None:
    """رقم نسخة الخطوة: يزيد مع كل تغيير لكي الخطوة التي بعدها تعرف أنها بقت قديمة."""
    d[key] = int(d.get(key) or 0) + 1


def update_ad(aid: str, fn) -> None:
    with ADS_LOCK, closing(db()) as conn, conn:
        r, data = ad_row(conn, aid)
        fn(data)
        conn.execute("UPDATE ads SET data = ?, updated_at = ? WHERE id = ?", (json.dumps(data, ensure_ascii=False), now(), aid))


def ad_to_dict(r: sqlite3.Row, d: dict) -> dict:
    aid = r["id"]
    base = f"/media/ads/{aid}"
    analysis = d.get("analysis") or {}
    scenes = [{**s, "frame_url": f"{base}/frames/{s['frame']}" if s.get("frame") else None} for s in analysis.get("scenes") or []]
    return {
        "id": aid, "name": r["name"], "created_at": r["created_at"],
        "source": d.get("source"), "source_url": f"{base}/{d['source']['file']}" if d.get("source") else None,
        "original_url": f"{base}/{d['source'].get('original') or d['source']['file']}" if d.get("source") else None,
        "status": d.get("status", "idle"), "step": d.get("step"), "error": d.get("error"),
        "analysis": {**analysis, "scenes": scenes} if analysis else None,
        "audio": d.get("audio"), "audio_error": d.get("audio_error"), "audio_tech": d.get("audio_tech"),
        "audio_status": d.get("audio_status", "idle"), "has_audio": bool((d.get("source") or {}).get("has_audio")),
        "analysis_ver": d.get("analysis_ver", 0), "adapt_ver": d.get("adapt_ver", 0),
        "prod_history": [{"at": h.get("archived_at"), "shots": len(h.get("shots") or [])} for h in d.get("prod_history") or []],
        "settings": d.get("settings") or {},
        "adaptation": d.get("adaptation"), "adapt_status": d.get("adapt_status", "idle"), "adapt_error": d.get("adapt_error"),
        "directions": d.get("directions") or [], "directions_status": d.get("directions_status", "idle"),
        "directions_error": d.get("directions_error"),
        "scomp_status": d.get("scomp_status", "idle"),
        "chat": d.get("chat") or [],
        "thumb": scenes[0]["frame_url"] if scenes and scenes[0].get("frame_url") else None,
        "prod": with_ref_motion(prod_to_dict(aid, d.get("prod")), analysis),
        "chain_prod": bool(d.get("chain_prod")),
        "brain_db": ad_brain_db(d.get("settings")),
        "video_models": [{"key": k, "label": v["label"], "per_sec": (TRIAL_MODELS.get(k) or {}).get("per_sec")} for k, v in AD_VIDEO_MODELS.items()],
        "ar_voices": [{"id": k, "label": v} for k, v in AR_VOICES.items()],
    }


def ad_brain_db(settings: dict | None) -> list[dict]:
    """عناصر ملف العميل الذي ينفع يتعملها إشارة (الاسم والنوع والصورة) لكي تظهر في الواجهة."""
    brain = ad_brain(settings)
    return [{"name": a["name"], "kind": a["kind"], "url": f"/media/ads/brains/{brain['id']}/{a['file']}"} for a in brain_db(brain)]


def with_ref_motion(prod: dict | None, analysis: dict) -> dict | None:
    """الموشن جرافيك الخاص بالمشهد الأصلي المقابل لكل لقطة (من آخر تحليل)، لكي يظهر بجانب الموشن الخاص بالعلامة."""
    if not prod:
        return prod
    by_n = {s.get("n"): s for s in (analysis or {}).get("scenes") or []}
    for s in prod["shots"]:
        s["ref_motion"] = (by_n.get(s.get("ref_scene")) or {}).get("motion_graphics", "")
    return prod


def ad_response(aid: str) -> dict:
    with closing(db()) as conn:
        r, d = ad_row(conn, aid)
    return ad_to_dict(r, d)


def ad_progress(d: dict) -> dict:
    """ملخص مراحل المشروع للقايمة الجانبية: وصل لفين."""
    shots = (d.get("prod") or {}).get("shots") or []
    def chosen_ok(s):
        return any(t["id"] == s.get("chosen") and t.get("status") == "done" for t in s.get("takes") or [])
    return {"analysis": bool(d.get("analysis")), "adapt": bool(d.get("adaptation")), "shots": len(shots),
            "frames": sum(1 for s in shots if s.get("frame")), "videos": sum(1 for s in shots if chosen_ok(s)),
            "editor": bool((d.get("prod") or {}).get("project_id")),
            "mode": (d.get("settings") or {}).get("fidelity") or "copy"}


@app.get("/api/ads")
def list_ads():
    with closing(db()) as conn:
        rows = conn.execute("SELECT * FROM ads ORDER BY created_at DESC").fetchall()
    out = []
    for r in rows:
        d = json.loads(r["data"])
        if not owned((d.get("settings") or {}).get("brain_id") if (d.get("settings") or {}).get("brain_id") != "none" else None):
            continue  # إعلانات عميل تاني
        scenes = (d.get("analysis") or {}).get("scenes") or []
        out.append({"id": r["id"], "name": r["name"], "created_at": r["created_at"], "status": d.get("status", "idle"),
                    "step": d.get("step"), "adapt_status": d.get("adapt_status", "idle"), "progress": ad_progress(d),
                    "thumb": f"/media/ads/{r['id']}/frames/{scenes[0]['frame']}" if scenes and scenes[0].get("frame") else None})
    return out


def parse_ad_edit(start: float | None, end: float | None, crop: str) -> dict | None:
    """القص والكروب من المحرر الصغير: الكروب كسور من الصورة (x,y,w,h بين 0 و1)."""
    edit = {}
    if start is not None and start > 0.01:
        edit["start"] = round(float(start), 3)
    if end is not None and end > 0:
        edit["end"] = round(float(end), 3)
    if crop:
        try:
            x, y, w, h = (max(0.0, min(1.0, float(v))) for v in crop.split(","))
        except ValueError as exc:
            raise HTTPException(400, "الكروب غير مظبوط") from exc
        if w < 0.999 or h < 0.999:
            if w < 0.05 or h < 0.05:
                raise HTTPException(400, "الكروب صغير جدًا")
            edit["crop"] = [round(x, 4), round(y, 4), round(min(w, 1 - x), 4), round(min(h, 1 - y), 4)]
    return edit or None


def apply_ad_edit(original: Path, out: Path, edit: dict | None) -> None:
    """يُخرج نسخة مقصوصة ومعمولها كروب من الفيديو الأصلي (بجودة عالية)."""
    if not edit:
        shutil.copyfile(original, out)
        return
    args = [ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y"]
    if edit.get("start"):
        args += ["-ss", f"{edit['start']:.3f}"]
    if edit.get("end"):
        args += ["-to", f"{edit['end']:.3f}"]
    args += ["-i", str(original)]
    if edit.get("start") and edit.get("end"):
        # -to بعد -ss قبل الـ input بيتحسب من أول الملف، فبنحوّله لمدة
        i = args.index("-to")
        args[i], args[i + 1] = "-t", f"{edit['end'] - edit['start']:.3f}"
    vf = []
    if edit.get("crop"):
        x, y, w, h = edit["crop"]
        vf.append(f"crop=trunc(iw*{w}/2)*2:trunc(ih*{h}/2)*2:trunc(iw*{x}):trunc(ih*{y})")
    if vf:
        args += ["-vf", ",".join(vf)]
    args += ["-c:v", "libx264", "-preset", "veryfast", "-crf", "18", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "160k",
             "-movflags", "+faststart", str(out)]
    r = subprocess.run(args, capture_output=True, text=True, timeout=900)
    if r.returncode != 0 or not out.exists():
        raise HTTPException(400, f"تعذّر ذلك أقص الفيديو: {r.stderr[-300:]}")


def ad_source_from(folder: Path, original: str, edit: dict | None, display_name: str | None) -> dict:
    src_name = original if not edit else "source-edit.mp4"
    if edit:
        apply_ad_edit(folder / original, folder / src_name, edit)
    try:
        info = media_info(folder / src_name)
    except Exception as exc:  # noqa: BLE001
        raise HTTPException(400, f"تعذّرت قراءة الفيديو: {exc}") from exc
    return {"file": src_name, "original": original, "edit": edit, "name": display_name, "duration": round(info.duration, 2),
            "width": info.width, "height": info.height, "has_audio": info.has_audio}


@app.post("/api/ads")
def create_ad(file: UploadFile = File(...), name: str = Form(""), trim_start: float | None = Form(None),
              trim_end: float | None = Form(None), crop: str = Form("")):
    """ترفع إعلان مرجعي (وإذا تريد تقصه أو تعمله كروب قبلها) والتحليل يبدأ تلقائيًا، وبعده اقتراح للعميل."""
    aid = uuid.uuid4().hex[:12]
    folder = ad_dir(aid)
    fname = save_upload(file, VIDEO_EXTENSIONS, folder, "original")
    try:
        source = ad_source_from(folder, fname, parse_ad_edit(trim_start, trim_end, crop), file.filename)
    except HTTPException:
        shutil.rmtree(folder, ignore_errors=True)
        raise
    info = source
    data = {"source": source,
            "status": "queued", "settings": {"duration": min(60, max(10, round(info["duration"]))), "format": "9:16 ريلز وتيك توك",
                                             "language": brand_settings().get("language") or "", "brain_id": active_client_id()}}
    with closing(db()) as conn, conn:
        conn.execute("INSERT INTO ads (id, name, data, created_at, updated_at) VALUES (?, ?, ?, ?, ?)",
                     (aid, name.strip() or Path(file.filename or "إعلان").stem, json.dumps(data, ensure_ascii=False), now(), now()))
    threading.Thread(target=run_ad_analysis, args=(aid,), daemon=True).start()
    return ad_response(aid)


@app.get("/api/ads/{aid}")
def get_ad(aid: str):
    return ad_response(aid)


class AdPatchIn(BaseModel):
    name: str | None = None
    settings: dict | None = None
    analysis: dict | None = None
    audio: dict | None = None
    adaptation: dict | None = None


@app.patch("/api/ads/{aid}")
def patch_ad(aid: str, body: AdPatchIn):
    """مركز الإعدادات: تعديل الإعدادات أو أي شيء في التحليل أو الاقتراح بنفسك."""
    if body.name is not None and body.name.strip():
        with closing(db()) as conn, conn:
            conn.execute("UPDATE ads SET name = ? WHERE id = ?", (body.name.strip()[:120], aid))
    def fn(d):
        if body.settings is not None:
            d["settings"] = {**(d.get("settings") or {}), **{k: body.settings[k] for k in AD_SETTING_KEYS if k in body.settings}}
        if body.analysis is not None and d.get("analysis"):
            # الفريمات بتفضل زي ما هي
            frames = {s.get("n"): s.get("frame") for s in d["analysis"].get("scenes") or []}
            scenes = [{k: v for k, v in s.items() if k != "frame_url"} for s in body.analysis.get("scenes") or d["analysis"].get("scenes") or []]
            for s in scenes:
                s["frame"] = frames.get(s.get("n"))
            d["analysis"] = {**d["analysis"], **body.analysis, "scenes": scenes}
            bump(d, "analysis_ver")
        if body.audio is not None:
            d["audio"] = body.audio
        if body.adaptation is not None:
            # التعديل بإيدك بيفضل على نفس التحليل اللي الاقتراح اتكتب عليه
            based = (d.get("adaptation") or {}).get("based_on", d.get("analysis_ver", 0))
            d["adaptation"] = {**body.adaptation, "based_on": based}
            bump(d, "adapt_ver")
    update_ad(aid, fn)
    return ad_response(aid)


@app.delete("/api/ads/{aid}")
def delete_ad(aid: str):
    with closing(db()) as conn, conn:
        conn.execute("DELETE FROM ads WHERE id = ?", (aid,))
    shutil.rmtree(ADS_DIR / Path(aid).name, ignore_errors=True)
    return {"ok": True}


class AdEditIn(BaseModel):
    start: float | None = None
    end: float | None = None
    crop: str = ""


@app.post("/api/ads/{aid}/edit")
def edit_ad(aid: str, body: AdEditIn):
    """قص وكروب جديد من الفيديو الأصلي، وبعدها التحليل والاقتراح يُنشأ من أولًا."""
    with closing(db()) as conn:
        _, d = ad_row(conn, aid)
    if d.get("status") in ("queued", "working"):
        raise HTTPException(400, "انتظر عندما التحليل الذي يعمل ينتهي")
    folder = ad_dir(aid)
    original = d["source"].get("original") or d["source"]["file"]
    source = ad_source_from(folder, original, parse_ad_edit(body.start, body.end, body.crop), d["source"].get("name"))
    for f in (folder / "frames").glob("*.jpg"):
        f.unlink(missing_ok=True)
    update_ad(aid, lambda d: d.update(source=source, status="queued", error=None, analysis=None, audio=None, audio_error=None,
                                     audio_tech=None, audio_status="idle"))
    threading.Thread(target=run_ad_analysis, args=(aid,), daemon=True).start()
    return ad_response(aid)


def run_scene_components(aid: str) -> None:
    try:
        with closing(db()) as conn:
            _, d = ad_row(conn, aid)
        scenes = d["analysis"]["scenes"]
        if atlas.mock_mode():
            sc = az.mock_scene_components(scenes)
        else:
            proxy = ad_dir(aid) / "proxy.mp4"
            if not proxy.exists():
                raise HTTPException(400, "نسخة الفيديو الصغيرة غير موجودة. اضغط «حلّل مرة أخرى»")
            sc = ad_json(ad_media_chat(az.with_media(az.scene_components_messages(scenes), data_url(proxy, "video/mp4"), "ad.mp4")),
                         "مكونات المشاهد")
        def fn(d):
            az.merge_scene_components(d["analysis"]["scenes"], sc)
            d["analysis"]["components_error"] = None
            d["scomp_status"] = "done"
            bump(d, "analysis_ver")
        update_ad(aid, fn)
    except Exception as exc:  # noqa: BLE001
        msg = str(getattr(exc, "detail", None) or exc)[:300]
        def fail(d):
            d["scomp_status"] = "failed"
            if d.get("analysis"):
                d["analysis"]["components_error"] = msg
        update_ad(aid, fail)


@app.post("/api/ads/{aid}/scene-components")
def scene_components(aid: str):
    """تفصيص مكونات مشاهد الإعلان الأصلي (للإعلانات التي حُلّلت قبل هذه الخطوة، أو إذا تريد تعيده)."""
    with closing(db()) as conn:
        _, d = ad_row(conn, aid)
    if not d.get("analysis"):
        raise HTTPException(400, "انتظر عندما التحليل ينتهي")
    if d.get("scomp_status") == "working":
        raise HTTPException(400, "التفصيص يعمل بالفعل")
    update_ad(aid, lambda d: d.update(scomp_status="working"))
    threading.Thread(target=run_scene_components, args=(aid,), daemon=True).start()
    return ad_response(aid)


@app.post("/api/ads/{aid}/analyze")
def reanalyze_ad(aid: str):
    with closing(db()) as conn:
        _, d = ad_row(conn, aid)
    if d.get("status") in ("queued", "working"):
        raise HTTPException(400, "التحليل يعمل بالفعل")
    update_ad(aid, lambda d: d.update(status="queued", error=None))
    threading.Thread(target=run_ad_analysis, args=(aid,), daemon=True).start()
    return ad_response(aid)


class AdAdaptIn(BaseModel):
    message: str = ""
    then_prod: bool = False  # بعد ما الاقتراح يتكتب، التنفيذ يبدأ منه على طول


@app.post("/api/ads/{aid}/adapt")
def adapt_ad(aid: str, body: AdAdaptIn):
    """الاقتراح من جديد (بالإعدادات والأسلوب الحاليين)، أو تعديله برسالة منك."""
    with closing(db()) as conn:
        _, d = ad_row(conn, aid)
    if not d.get("analysis"):
        raise HTTPException(400, "انتظر عندما التحليل ينتهي")
    if d.get("adapt_status") == "working":
        raise HTTPException(400, "الاقتراح يكتب بالفعل")
    msg = body.message.strip()[:3000]
    def fn(d):
        d["adapt_status"], d["adapt_error"] = "working", None
        d["chain_prod"] = body.then_prod
        if msg:
            d.setdefault("chat", []).append({"role": "user", "content": msg})
        else:
            d["chat"] = []
    update_ad(aid, fn)
    threading.Thread(target=run_ad_adapt, args=(aid,), daemon=True).start()
    return ad_response(aid)


# سعر التوكن بالدولار (من قايمة موديلات Atlas): (الداخل، الطالع). الموديل اللي مش هنا بيتحسب بسعر Pro عشان نبقى في الأمان
MEDIA_PRICES = {"google/gemini-2.5-pro": (1.25e-6, 10e-6), "google/gemini-2.5-flash": (.3e-6, 2.5e-6),
                "google/gemini-2.5-flash-lite": (.1e-6, .4e-6), "google/gemini-3.1-flash-lite": (.25e-6, 1.5e-6)}


def media_cost(model: str, usage: dict) -> float:
    pin, pout = MEDIA_PRICES.get(model, MEDIA_PRICES["google/gemini-2.5-pro"])
    i, o = int(usage.get("prompt_tokens") or 0), int(usage.get("completion_tokens") or 0)
    o = max(o, int(usage.get("total_tokens") or 0) - i)  # تفكير الموديل بيتحسب طالع حتى لو مش مكتوب في completion
    return i * pin + o * pout


def ad_media_chat(messages: list[dict], max_tokens: int = 32000, models: list[str] | None = None, meter: dict | None = None) -> str:
    """نموذج يفهم الفيديو والصوت (Gemini). يجرب المختار، وإذا غير متاح الذي بعده.
    models: نماذج بعينها للشغل الكتير الرخيص. meter: يتجمع فيه الصرف التقريبي بالدولار."""
    if atlas.mock_mode():
        return "{}"
    errors = []
    for model in models or atlas.model_candidates(ads_settings()["video_model"], ("gemini-2.5-pro", "gemini-2.5-flash"), AD_VIDEO_FALLBACKS)[:4]:
        try:
            body = {"model": model, "messages": messages, "temperature": 0.3, "max_tokens": max_tokens,
                    "response_format": {"type": "json_object"}}
            with httpx.Client(timeout=600) as client:
                resp = client.post(f"{atlas.LLM_URL}/chat/completions", headers=atlas._headers(), json=body)
                if resp.status_code in (400, 422):  # موديل مش بيقبل JSON mode
                    body.pop("response_format")
                    resp = client.post(f"{atlas.LLM_URL}/chat/completions", headers=atlas._headers(), json=body)
            data = atlas._check(resp, f"نموذج الفيديو ({model})")
            if meter is not None:
                meter["usd"] = meter.get("usd", 0.0) + media_cost(model, data.get("usage") or {})
            text = str(data["choices"][0]["message"]["content"] or "").strip()
            if text:
                return text
            errors.append(f"{model}: رد فارغ")
        except (atlas.AtlasError, httpx.HTTPError, KeyError, IndexError) as exc:
            errors.append(f"{model}: {str(exc)[:150]}")
    raise atlas.AtlasError("نموذج الفيديو لا يعمل: " + " | ".join(errors[:3]))


def ad_json(text: str, what: str) -> dict:
    """JSON من رد نموذج الفيديو. إذا بايظ ومعرفناش نصلّحه، نموذج النص يصلّحه (أرخص بكتير من إعادة التحليل)."""
    try:
        return az.parse_json(text, what)
    except ValueError as first:
        try:
            fixed = series_chat([
                {"role": "system", "content": "استعد نفس هذه البيانات كـ JSON صحيح بالضبط بدون أي تغيير في المحتوى ومن غير أي نص آخر. "
                                              "إذا الرد مقطوع في الآخر أغلقه بشكل صحيح."},
                {"role": "user", "content": text[:60000]},
            ], json_mode=True)
            return az.parse_json(fixed, what)
        except (HTTPException, ValueError):
            raise first from None


def data_url(path: Path, mime: str) -> str:
    import base64
    return f"data:{mime};base64," + base64.b64encode(path.read_bytes()).decode()


def ad_loudness(path: Path) -> dict:
    """قياس الصوت محليًا (بدون نموذج): الارتفاع (LUFS) وأعلى نقطة."""
    out = subprocess.run([ffmpeg_exe(), "-hide_banner", "-i", str(path), "-af", "ebur128=peak=true", "-f", "null", "-"],
                         capture_output=True, text=True, timeout=300).stderr
    tail = out[out.rfind("Summary:"):] if "Summary:" in out else out
    lufs = re.search(r"I:\s*(-?[\d.]+) LUFS", tail)
    peak = re.search(r"Peak:\s*(-?[\d.]+) dBFS", tail)
    lra = re.search(r"LRA:\s*(-?[\d.]+) LU", tail)
    return {"lufs": float(lufs.group(1)) if lufs else None, "true_peak": float(peak.group(1)) if peak else None,
            "range_lu": float(lra.group(1)) if lra else None}


def run_ad_audio(aid: str) -> None:
    """خطوة جانبية: تفصيص الصوت (نص، مزيكا، مؤثرات) + قياس الارتفاع."""
    try:
        with closing(db()) as conn:
            _, d = ad_row(conn, aid)
        folder = ad_dir(aid)
        src = folder / d["source"]["file"]
        dur = min(d["source"]["duration"], AD_MAX_SECONDS)
        audio = folder / "audio.mp3"
        subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", str(src), "-t", f"{dur:.2f}",
                        "-vn", "-ac", "1", "-b:a", "96k", str(audio)], check=True, capture_output=True, timeout=300)
        tech = ad_loudness(src)
        data = az.mock_audio() if atlas.mock_mode() else ad_json(
            ad_media_chat(az.with_media(az.audio_messages(dur), data_url(audio, "audio/mpeg"), "ad.mp3")), "تحليل الصوت")
        update_ad(aid, lambda d: d.update(audio=data, audio_tech=tech, audio_error=None, audio_status="done"))
    except Exception as exc:  # noqa: BLE001
        msg = str(getattr(exc, "detail", None) or exc)[:400]
        update_ad(aid, lambda d: d.update(audio_status="failed", audio_error=msg))


@app.post("/api/ads/{aid}/audio-analyze")
def audio_analyze(aid: str):
    with closing(db()) as conn:
        _, d = ad_row(conn, aid)
    if not (d.get("source") or {}).get("has_audio"):
        raise HTTPException(400, "هذا الفيديو لا يحتوي صوت")
    if d.get("audio_status") == "working":
        raise HTTPException(400, "الصوت يتحلل بالفعل")
    update_ad(aid, lambda d: d.update(audio_status="working", audio_error=None))
    threading.Thread(target=run_ad_audio, args=(aid,), daemon=True).start()
    return ad_response(aid)


def run_ad_analysis(aid: str) -> None:
    def step(label: str):
        update_ad(aid, lambda d: d.update(status="working", step=label))
    try:
        with closing(db()) as conn:
            _, d = ad_row(conn, aid)
        folder = ad_dir(aid)
        src = folder / d["source"]["file"]
        dur = min(d["source"]["duration"], AD_MAX_SECONDS)
        step("يُجهّز الفيديو")
        proxy = folder / "proxy.mp4"
        # نسخة صغيرة للموديل: الصورة والصوت كفاية للتحليل وحجمها صغير
        subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", str(src), "-t", f"{dur:.2f}",
                        "-vf", "scale='if(gt(iw,ih),min(640,iw),-2)':'if(gt(iw,ih),-2,min(640,ih))',fps=12",
                        "-c:v", "libx264", "-preset", "veryfast", "-crf", "31", "-pix_fmt", "yuv420p",
                        "-c:a", "aac", "-ac", "1", "-b:a", "64k", str(proxy)], check=True, capture_output=True, timeout=600)
        step("يشاهد الإعلان (الصورة والصوت)")
        if atlas.mock_mode():
            analysis = az.mock_analysis(dur)
        else:
            analysis = ad_json(ad_media_chat(az.with_media(az.video_messages(dur, d.get("settings", {}).get("notes", "")),
                                                           data_url(proxy, "video/mp4"), "ad.mp4")), "تحليل الإعلان")
        analysis["scenes"] = az.clean_scenes(analysis.get("scenes"), dur)
        step("يُخرج صورة من كل مشهد")
        for s in analysis["scenes"]:
            fr = f"scene-{s['n']:02d}.jpg"
            t = (s["start"] + s["end"]) / 2
            subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-ss", f"{t:.2f}", "-i", str(src),
                            "-frames:v", "1", "-vf", "scale=-2:480", "-q:v", "4", str(folder / "frames" / fr)],
                           capture_output=True, timeout=60)
            if (folder / "frames" / fr).exists():
                s["frame"] = fr
        step("يفصّص مكونات كل مشهد والموشن جرافيك")
        try:
            sc = az.mock_scene_components(analysis["scenes"]) if atlas.mock_mode() else ad_json(
                ad_media_chat(az.with_media(az.scene_components_messages(analysis["scenes"]), data_url(proxy, "video/mp4"), "ad.mp4")),
                "مكونات المشاهد")
            az.merge_scene_components(analysis["scenes"], sc)
            analysis["components_error"] = None
        except (atlas.AtlasError, ValueError, HTTPException) as exc:
            analysis["components_error"] = str(getattr(exc, "detail", None) or exc)[:300]
        if not analysis.get("title"):
            analysis["title"] = ""
        chain = []
        def done(d):
            d.update(analysis=analysis, status="done", step=None, error=None)
            bump(d, "analysis_ver")
            # أول مرة بس الاقتراح بيتكتب لوحده. بعد كده بزرار «التالي» عشان ميمسحش اقتراح اتعدل
            if not d.get("adaptation") and d.get("adapt_status") != "working":
                d.update(adapt_status="working", adapt_error=None, chat=[])
                chain.append(True)
        update_ad(aid, done)
    except Exception as exc:  # noqa: BLE001
        msg = str(getattr(exc, "detail", None) or exc)[:500]
        if isinstance(exc, subprocess.CalledProcessError):
            msg = f"FFmpeg: {(exc.stderr or b'').decode(errors='ignore')[-300:] if isinstance(exc.stderr, bytes) else exc.stderr}"
        update_ad(aid, lambda d: d.update(status="failed", step=None, error=msg))
        return
    if chain:
        run_ad_adapt(aid)


def ad_style(style_id: str | None) -> dict | None:
    if not style_id:
        return None
    with closing(db()) as conn:
        r = conn.execute("SELECT * FROM ad_styles WHERE id = ?", (style_id,)).fetchone()
    return {"name": r["name"], **json.loads(r["data"])} if r else None


def other_ads(aid: str, limit: int = 8) -> list[dict]:
    """ملخص الإعلانات الأخرى (الأحدث أولًا) لكي الاقتراح الجديد ميطلعش شبههم."""
    out = []
    with closing(db()) as conn:
        rows = conn.execute("SELECT id, data FROM ads WHERE id != ? ORDER BY created_at DESC", (aid,)).fetchall()
    for r in rows:
        a = (json.loads(r["data"]).get("adaptation") or {})
        if a.get("title"):
            out.append({**{k: str(a.get(k) or "")[:200] for k in ("title", "hook", "tone", "palette", "locations")},
                        "angle": str(a.get("angle") or a.get("kochi_angle") or "")[:200]})
        if len(out) >= limit:
            break
    return out


def run_ad_directions(aid: str) -> None:
    try:
        with closing(db()) as conn:
            _, d = ad_row(conn, aid)
        settings = d.get("settings") or {}
        if atlas.mock_mode():
            result = az.mock_directions()
        else:
            result = ad_json(series_chat(az.directions_messages(brand_settings(), d.get("analysis") or {}, settings,
                                                                ad_brain(settings), other_ads(aid))), "الاتجاهات")
        dirs = [x for x in result.get("directions") or [] if isinstance(x, dict)][:4]
        if not dirs:
            raise RuntimeError("النموذج ما رجعش اتجاهات")
        update_ad(aid, lambda d: d.update(directions=dirs, directions_status="done", directions_error=None))
    except Exception as exc:  # noqa: BLE001
        msg = str(getattr(exc, "detail", None) or exc)[:400]
        update_ad(aid, lambda d: d.update(directions_status="failed", directions_error=msg))


@app.post("/api/ads/{aid}/directions")
def ad_directions(aid: str):
    """🎲 3 اتجاهات مختلفة للتطبيق على العلامة تختار منهم قبل ما الاقتراح يُكتب."""
    with closing(db()) as conn:
        _, d = ad_row(conn, aid)
    if not d.get("analysis"):
        raise HTTPException(400, "انتظر عندما التحليل ينتهي")
    if d.get("directions_status") == "working":
        raise HTTPException(400, "يفكر في الاتجاهات بالفعل")
    update_ad(aid, lambda d: d.update(directions_status="working", directions_error=None))
    threading.Thread(target=run_ad_directions, args=(aid,), daemon=True).start()
    return ad_response(aid)


def run_ad_adapt(aid: str) -> None:
    try:
        with closing(db()) as conn:
            _, d = ad_row(conn, aid)
        settings = d.get("settings") or {}
        if atlas.mock_mode():
            result = az.mock_adaptation(int(settings.get("duration") or 30))
        else:
            msgs = az.adapt_messages(brand_settings(), d.get("analysis") or {}, d.get("audio") or {}, settings,
                                     ad_style(settings.get("style_id")), d.get("chat") or [], ad_brain(settings), other_ads(aid))
            result = ad_json(series_chat(msgs), "اقتراح الإعلان")
        def fn(d):
            d["adaptation"] = {**result, "based_on": d.get("analysis_ver", 0)}
            d["adapt_status"], d["adapt_error"] = "done", None
            bump(d, "adapt_ver")
            if d.get("chat"):
                d["chat"].append({"role": "assistant", "content": json.dumps(result, ensure_ascii=False)[:6000]})
        update_ad(aid, fn)
    except Exception as exc:  # noqa: BLE001
        msg = str(getattr(exc, "detail", None) or exc)[:500]
        update_ad(aid, lambda d: d.update(adapt_status="failed", adapt_error=msg, chain_prod=False))
        return
    chain = []
    update_ad(aid, lambda d: chain.append(d.pop("chain_prod", False)))
    if chain and chain[0]:
        try:
            prod_start(aid)
        except HTTPException as exc:
            update_ad(aid, lambda d: d.update(adapt_error=f"الاقتراح كُتب فقط التنفيذ مبدأش: {exc.detail}"))


# ---------- ملف العميل: المنتج (تطبيق / منتج ملموس / خدمة)، أصوله الحقيقية (شاشات، لوجو، صور منتج) وهويته

BRAIN_KINDS = ("screens", "logos", "products", "characters", "sets", "props")
BRAIN_FIELDS = ("type", "domain", "about", "audience", "rules", "palette", "theme", "typography", "ui_style", "logo_description",
                "style", "market", "language", "logo_rule", "modest",
                # 🧠 عقل العلامة: الستايلات (أول واحد هو الديفولت) والتسليم (اللوجو، الإنترو والأوترو، الـ CTA، الكابشن الثابت واللينك)
                "styles", "logo_on", "intro_on", "outro_on", "cta", "caption", "link",
                "niche")   # النيتش: من تحليل حساب السوشيال (وتقدر تكتبه بإيدك)
BRAND_VIDEOS = ("intro", "outro")
BRAIN_LOCK = threading.Lock()


def brain_dir(bid: str) -> Path:
    d = ADS_DIR / "brains" / Path(bid).name
    d.mkdir(parents=True, exist_ok=True)
    return d


def brain_row(bid: str) -> dict | None:
    with closing(db()) as conn:
        r = conn.execute("SELECT * FROM ad_brains WHERE id = ?", (bid,)).fetchone()
    return {"id": r["id"], "name": r["name"], "created_at": r["created_at"], **json.loads(r["data"])} if r else None


def update_brain(bid: str, fn) -> None:
    with BRAIN_LOCK, closing(db()) as conn, conn:
        r = conn.execute("SELECT * FROM ad_brains WHERE id = ?", (bid,)).fetchone()
        if r is None:
            raise HTTPException(404, "هذا العميل غير موجود")
        d = json.loads(r["data"])
        name = fn(d)
        conn.execute("UPDATE ad_brains SET data = ?" + (", name = ?" if name else "") + " WHERE id = ?",
                     (json.dumps(d, ensure_ascii=False), *([name] if name else []), bid))


def brain_to_dict(b: dict) -> dict:
    base = f"/media/ads/brains/{b['id']}"
    out = {k: b.get(k, "") for k in ("id", "name", "created_at", *BRAIN_FIELDS)}
    out.update(status=b.get("status", "idle"), error=b.get("error"), type_set=bool(b.get("type_set")))
    for kind in BRAND_VIDEOS:   # إنترو وأوترو البراند (فيديو)
        f = b.get(f"{kind}_file")
        out[f"{kind}_url"] = f"{base}/{f}" if f and (brain_dir(b["id"]) / f).exists() else None
    for kind in BRAIN_KINDS:
        out[kind] = [{**a, "url": f"{base}/{a['file']}"} for a in b.get(kind) or []]
    # المصادر اللي اتقرت، والاقتراحات اللي مستنية موافقتك، والمعرفة اللي اتوافق عليها
    out["sources"] = [{k: s.get(k) for k in ("id", "kind", "name", "status", "error", "count", "credits", "step", "created_at")} for s in b.get("sources") or []]
    # 📱 من تحليل الحساب: نقاط لازم تتشتغل، والنيتش · 🧩 الكويز: الأسئلة اللي اتجاوبت
    out["todos"] = b.get("todos") or []
    out["niche"] = b.get("niche") or ""
    out["quiz_done"] = b.get("quiz_done") or []
    out.update(field=b.get("field") or "", goal=b.get("goal") or "", onboarded=bool(b.get("onboarded")), first_at=b.get("first_at"))
    out["credits"] = wallet.balance()
    out["pending"] = b.get("pending") or []
    out["notes"] = b.get("notes") or []
    out["knowledge"] = fz.knowledge(b)
    out["rivals"] = [{k: i.get(k) for k in ("id", "platform", "handle", "median_views")} for i in rivals.approved(b.get("competitors") or {})]
    out["rivals_pending"] = sum(1 for i in (b.get("competitors") or {}).get("items") or [] if not rivals.is_ok(i))
    out["custom_styles"] = [{**c, "cover_url": f"{base}/{c['cover']}" if c.get("cover") else None} for c in b.get("custom_styles") or []]
    out["audiences"] = b.get("audiences") or []
    out["audiences_busy"] = AUD_BUSY.get(b["id"]) is not None
    return out


# ---------- 💬 مساعد الدعم (تحت على اليمين): بيشرح الصفحة اللي العميل فيها وبيرد على أسئلة البرنامج
import help as helpdesk  # noqa: E402

HELP_MODELS = ["google/gemini-2.5-flash", "openai/gpt-5.4-mini", "google/gemini-2.5-flash-lite", "deepseek-ai/deepseek-v4-flash"]   # الأول الأذكى، والباقي احتياطي
HELP_DAY: dict[str, int] = {}
HELP_LIMIT = 120   # رسالة في اليوم لكل حساب (ببلاش للعميل، وعلى حسابنا)
HELP_TICKETS = DATA_DIR / "help_tickets.json"


class HelpIn(BaseModel):
    page: str = "home"
    q: str
    history: list = []


@app.get("/api/help/pages")
def help_pages():
    return {k: {"name": v["name"]} for k, v in helpdesk.PAGES.items()}


@app.post("/api/help/chat")
def help_chat(body: HelpIn):
    q = body.q.strip()
    if not q:
        raise HTTPException(400, "اكتب سؤالك")
    day = datetime.now(timezone.utc).date().isoformat()
    if HELP_DAY.get(day, 0) >= HELP_LIMIT:
        raise HTTPException(429, "وصلت حتى أسئلة اليوم. جرّب غدًا، أو أرسل المشكلة للدعم")
    if day not in HELP_DAY:   # يوم جديد: العدّاد بيبدأ من الأول
        HELP_DAY.clear()
    HELP_DAY[day] = HELP_DAY.get(day, 0) + 1
    key = body.page if body.page in helpdesk.PAGES else "home"
    if atlas.mock_mode():
        return {"text": helpdesk.mock_reply(key, q), "page": key}
    if not atlas.api_key():   # من غير مفتاح الموديلات المساعد بيبقى شرح ثابت بس، فبنقول ده صراحة بدل ما يبان إنه رد ذكي
        return {"text": helpdesk.mock_reply(key, q) + "\n\n(المساعد الذكي غير مفعّل الآن، وهذا شرح ثابت للصفحة.)", "page": key}
    b = brain_row(active_client_id()) or {}
    msgs = helpdesk.messages(key, body.history, q, " · ".join(str(b.get(k) or "") for k in ("name", "domain", "about") if b.get(k)))
    for model in HELP_MODELS:
        try:
            return {"text": atlas.chat(msgs, model, temperature=0.3, max_tokens=700, timeout=45).strip(), "page": key}
        except (atlas.AtlasError, httpx.HTTPError) as exc:
            print(f"[help] {model}: {str(exc)[:160]}", flush=True)
            continue
    raise HTTPException(502, "المساعد غير متاح الآن. جرّب بعد قليل، أو أرسل المشكلة للدعم")


class TicketIn(BaseModel):
    page: str = ""
    text: str
    history: list = []


@app.post("/api/help/ticket")
def help_ticket(body: TicketIn):
    """«أرسلها للدعم»: المشكلة تُحفظ ومعها آخر نص الشات والصفحة، ويوصل إشعار."""
    text = body.text.strip()[:2000]
    if not text:
        raise HTTPException(400, "اكتب المشكلة")
    try:
        items = json.loads(HELP_TICKETS.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        items = []
    t = {"id": uuid.uuid4().hex[:8], "at": now(), "page": body.page[:40], "text": text, "status": "open",
         "history": [{"role": str(h.get("role"))[:10], "text": str(h.get("text") or "")[:800]} for h in body.history[-10:] if isinstance(h, dict)]}
    HELP_TICKETS.write_text(json.dumps([t, *items][:500], ensure_ascii=False), encoding="utf-8")
    notify("help", "info", "🛟 تذكرة دعم جديدة", text[:200], "settings", t["id"])
    return {"ok": True, "id": t["id"]}


@app.get("/api/help/tickets")
def help_tickets():
    try:
        return json.loads(HELP_TICKETS.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return []


# ---------- 👥 أكتر من جمهور: العقل بيستخلص الجماهير لوحده من وصف البراند، وتقدر تعدّلها
AUD_BUSY: dict[str, float] = {}
AUD_KEYS = ("name", "who", "pain", "want")


def audiences_clean(raw) -> list[dict]:
    out = []
    for a in (raw if isinstance(raw, list) else [])[:6]:
        if not isinstance(a, dict) or not str(a.get("name") or "").strip():
            continue
        x = {k: re.sub(r"\s+", " ", str(a.get(k) or "")).strip()[:300] for k in AUD_KEYS}
        x["name"] = x["name"][:60]
        try:
            x["share"] = max(0, min(100, int(float(a.get("share") or 0))))
        except (TypeError, ValueError):
            x["share"] = 0
        x["id"] = str(a.get("id") or uuid.uuid4().hex[:8])[:12]
        out.append(x)
    return out


def audiences_messages(b: dict) -> list[dict]:
    info = "\n".join(f"{t}: {b[k]}" for k, t in (("name", "الاسم"), ("domain", "المجال"), ("about", "عن البراند"), ("audience", "الجمهور كما كتبه العميل"),
                                                 ("market", "السوق"), ("niche", "النيتش")) if b.get(k))
    return [{"role": "system", "content": "أنت خبير تسويق. استخرج الجماهير المستهدفة لعلامة تجارية من وصفها. اكتب بالعربية الفصحى البسيطة. Return JSON only."},
            {"role": "user", "content": info + '\n\nاستخرج من ١ إلى ٤ جماهير مختلفة فعلًا تستهدفها هذه العلامة (إذا الوصف يذكر جمهورًا واحدًا فقط فاكتفِ به). '
             'لكل جمهور: اسم قصير مميز، ومن هو (عمر واهتمام في جملة)، وما يزعجه، وما يريده، ونسبته التقريبية من الجمهور (المجموع ١٠٠).\n'
             'JSON: {"audiences": [{"name": "...", "who": "...", "pain": "...", "want": "...", "share": 50}]}'}]


def audiences_mock(b: dict) -> list[dict]:
    parts = [p.strip() for p in re.split(r"[،,\n]|\sو(?=[^\s])", b.get("audience") or "") if len(p.strip()) > 3][:3] or ["الجمهور الأساسي"]
    return audiences_clean([{"name": p[:40], "who": p, "pain": "", "want": "", "share": round(100 / len(parts))} for p in parts])


def audiences_extract(bid: str) -> list[dict]:
    b = brain_row(bid) or {}
    if atlas.mock_mode() or not atlas.api_key():
        items = audiences_mock(b)
    else:
        items = audiences_clean(flow_llm(audiences_messages(b), "استخلاص الجماهير").get("audiences"))   # flow_llm بيخصم من الرصيد
    if not items:
        raise HTTPException(400, "تعذّر استخلاص جمهور من الوصف. اكتب عن العلامة وجمهوره في العقل أولًا")
    update_brain(bid, lambda d: d.update(audiences=items, audiences_auto=True))
    return items


def audiences_auto(bid: str, old: dict, new: dict) -> None:
    """عندما وصف العلامة أو الجمهور يتغيّر: الجماهير تتستخلص مرة أخرى في الخلفية، إلا إذا العميل عدّلها بإيده."""
    keys = ("domain", "about", "audience", "market")
    if new.get("audiences_edited") or all(old.get(k) == new.get(k) for k in keys) or AUD_BUSY.get(bid):
        return
    if len(" ".join(str(new.get(k) or "") for k in keys)) < 40:
        return
    AUD_BUSY[bid] = time.time()
    def run():
        try:
            audiences_extract(bid)
        except Exception:  # noqa: BLE001 — المرة الجاية لما الوصف يتغيّر
            pass
        finally:
            AUD_BUSY.pop(bid, None)
    threading.Thread(target=run, daemon=True).start()


@app.post("/api/ad-brains/{bid}/audiences/extract")
def brain_audiences_extract(bid: str):
    update_brain(bid, lambda d: d.pop("audiences_edited", None))
    audiences_extract(bid)
    return brain_to_dict(brain_row(bid))


class AudiencesIn(BaseModel):
    items: list = []


@app.put("/api/ad-brains/{bid}/audiences")
def brain_audiences_set(bid: str, body: AudiencesIn):
    items = audiences_clean(body.items)
    update_brain(bid, lambda d: d.update(audiences=items, audiences_edited=True))
    return brain_to_dict(brain_row(bid))


def seed_brain() -> None:
    """👤 العملاء: أول مرة يُنشأ عميل. إذا البرنامج كان يعمل لكوتشي من قبل، هويتها ولوجوها وجملها تُنقل لملف عميل كوتشي."""
    if auth.get_setting("clients_v1"):
        return
    with CLIENTS_LOCK:
        if auth.get_setting("clients_v1"):
            return
        with closing(db()) as conn:
            first = conn.execute("SELECT id FROM ad_brains ORDER BY created_at LIMIT 1").fetchone()
            used = any(conn.execute(f"SELECT 1 FROM {t} LIMIT 1").fetchone() for t in ("ads", "carousels", "series", "coaches"))
        legacy = used or bool(first) or bool(auth.get_setting("brand")) or bool(legacy_logo_path())
        lb = legacy_brand() if legacy else {}
        fields = {"about": lb.get("about", ""), "audience": lb.get("audience", ""), "palette": lb.get("colors", ""),
                  "typography": lb.get("font", ""), "style": lb.get("style", ""), "logo_rule": lb.get("logo_rule", ""),
                  "market": lb.get("market", ""), "language": lb.get("language", ""), "modest": lb.get("modest", ""),
                  "domain": "لياقة وتغذية وتدريب أونلاين" if legacy else "",
                  "rules": ("اللبس محتشم دائمًا: البنات لبس واسع طويل مع حجاب، والرجالة تيشيرت ونطلون أو شورت أسفل الركبة. "
                            + lb.get("rules", "")) if legacy else ""}
        if first:
            bid = first["id"]
            update_brain(bid, lambda d: d.update({k: v for k, v in fields.items() if v and not d.get(k)}))
        else:
            bid = uuid.uuid4().hex[:12]
            data = {"type": "app", **{k: "" for k in BRAIN_FIELDS if k != "type"}, **fields, "theme": "", "ui_style": "",
                    "logo_description": "", "screens": [], "logos": [], "products": [], "status": "idle"}
            with closing(db()) as conn, conn:
                conn.execute("INSERT INTO ad_brains (id, name, data, created_at) VALUES (?, ?, ?, ?)",
                             (bid, (lb.get("name") or "KOCHI") if legacy else "عميلي", json.dumps(data, ensure_ascii=False), now()))
        if legacy:
            try:
                ctas = json.loads(auth.get_setting("carousel_ctas") or "null")
            except ValueError:
                ctas = None
            logo = legacy_logo_path()
            def move(d):
                d.setdefault("ctas", ctas if isinstance(ctas, list) and ctas else cz.LEGACY_CTAS)
                if logo and not d.get("logos"):
                    f = f"logo-{uuid.uuid4().hex[:6]}{logo.suffix.lower()}"
                    shutil.copyfile(logo, brain_dir(bid) / f)
                    d["logos"] = [{"file": f, "name": "الشعار", "description": ""}]
            update_brain(bid, move)
        auth.set_setting("active_client", auth.get_setting("active_client") or bid)
        auth.set_setting("clients_v1", "1")


CLIENTS_LOCK = threading.Lock()


def first_client_id() -> str | None:
    """أقدم عميل: الأشياء التي أُنشئت قبل العملاء (بدون عميل) الخاصة به."""
    seed_brain()
    with closing(db()) as conn:
        r = conn.execute("SELECT id FROM ad_brains ORDER BY created_at LIMIT 1").fetchone()
    return r["id"] if r else None


import fieldpacks  # noqa: E402


def onboard_load() -> dict | None:
    f = DATA_DIR / "onboard.json"
    try:
        return json.loads(f.read_text(encoding="utf-8")) if f.exists() else None
    except ValueError:
        return None


def field_pack_apply(bid: str, ob: dict) -> None:
    """🧭 إجابات أول استخدام (البلد، اللهجة، المجال، الهدف) تملأ العقل: اللهجة والسوق، وبروفايل المجال (الجمهور والنبرة والكلمات
    والقواعد والدعوة)، و٣٠ فكرة جاهزة بهوكاتها في مجلد الأفكار، وخطة شهر جاهزة (مسودة توافق عليها). الخانات المكتوبة لا تُمسح."""
    field, goal = ob.get("field") or "", ob.get("goal") or ""

    def fn(d):
        for k, v in (("language", ob.get("dialect_label") or ""), ("market", ob.get("country") or "")):
            if v and not str(d.get(k) or "").strip():
                d[k] = v
        fieldpacks.brain_fill(field, goal, d)
        d["onboarded"] = now()
    update_brain(bid, fn)
    row = brain_row(bid) or {}
    brand = str(ob.get("brand") or "").strip()
    if brand and row.get("name") in ("عميلي", "", None):
        with closing(db()) as conn, conn:
            conn.execute("UPDATE ad_brains SET name = ? WHERE id = ?", (brand[:80], bid))
    pack = fieldpacks.FIELDS.get(field)
    if not pack:
        return
    # 💡 أفكار المجال في «مجلد الأفكار» (لا تتكرر إذا طُبّقت مرة ثانية)
    cid = SHARED_LIB if "ideas" in share_keys() else bid

    def add(m):
        saved = m.get("saved") or []
        if any(x.get("origin") == f"field:{field}" for x in saved):
            return
        items = [{"id": uuid.uuid4().hex[:10], "kind": "idea", "mine": True, "at": now(), "status": "ready", "origin": f"field:{field}",
                  "item": {"title": it["title"], "idea": it["idea"], "hook": it["hook"], "url": "", "audio": ""}} for it in pack["ideas"]]
        m["saved"] = ([*saved, *items])[-ideamem.SAVED_MAX:]
    mem_update(cid, add)
    # 🗓️ خطة شهر جاهزة للمجال: مسودة، والعميل يوافق عليها لكي تنزل على الأوتوبايلوت
    if not (row.get("month") or {}).get("items"):
        start = (datetime.now(timezone.utc) + timedelta(days=1)).date()
        ok = lambda t: (MOTION_DIR / "r" / t / "reel.html").exists()  # noqa: E731
        items = fieldpacks.month_items(field, start, MONTH_DAYS, "19:00", str(row.get("cta") or ""), ok)
        if items:
            month = {"status": "draft", "start": start.isoformat(), "days": MONTH_DAYS, "per_day": 1, "times": ["19:00"], "items": items,
                     "made_at": now(), "from_field": field}
            update_brain(bid, lambda d: d.update(month=month))


def onboard_apply() -> None:
    """🗣️ إجابات التسجيل (onboard.json من البوابة) تدخل عقل العلامة مرة واحدة، فالأفكار والهوك والنص والصوت تأخذ اللهجة
    نفسها من أول يوم، والعقل يبدأ من بروفايل المجال بدل الصفر."""
    if auth.get_setting("onboard_v1"):
        return
    ob = onboard_load()
    bid = first_client_id()
    if not ob or not bid:
        auth.set_setting("onboard_v1", "1")
        return
    try:   # كل خطوة لا تتكرر إذا اكتملت، فإذا توقف في النص (مثلًا وقت تشغيل السيرفر) يُكمل في الطلب التالي
        field_pack_apply(bid, ob)
    except Exception as exc:  # noqa: BLE001
        print("onboard_apply:", exc)
        return
    auth.set_setting("onboard_v1", "1")


class OnboardIn(BaseModel):
    country: str = ""
    dialect: str = ""
    field: str = ""
    goal: str = ""


class FirstIn(BaseModel):
    about: str = ""
    audience: str = ""


@app.get("/api/onboard")
def onboard_state():
    """🧭 مسار أول استخدام: هل نسأل الأسئلة الأربعة (لمن دخل بجوجل ولم يمر بالتسجيل)، وأول قالب مقترح، وسؤالا أول فيديو."""
    bid = active_client_id()
    b = (brain_row(bid) or {}) if bid else {}
    field = b.get("field") or ""
    pack = fieldpacks.FIELDS.get(field) or {}
    need = bool(b) and not b.get("onboarded") and not str(b.get("domain") or "").strip() and brain_score(b) < 30
    j = b.get("first_job") or {}
    if j.get("status") == "done" and bid:   # 🎁 الهدية لسه ماتسجلتش (أو اتصرف حاجة بعد الحساب): تتسجل دلوقتي
        try:
            if first_gift(bid):
                j = (brain_row(bid) or {}).get("first_job") or j
        except Exception as exc:  # noqa: BLE001
            print(f"[first-gift] {bid}: {exc}", flush=True)
    job = {k: j.get(k) for k in ("status", "step", "done", "progress", "video_url", "export_id", "title", "error", "tpl", "cost", "qa")} if j else None
    if job and job["status"] == "run" and time.time() - (j.get("at") or 0) > 3600:   # السيرفر اتقفل في النص
        job.update(status="failed", error="التشغيل توقف، جرّب مرة أخرى")
    steps = [{"key": k, "label": (f"{v} {dialect_phrase(b)}" if k == "script" else v)} for k, v in FIRST_STEPS]
    return {"need": need, "field": field, "first": fieldpacks.first_video(field), "about": b.get("about") or "", "audience": b.get("audience") or "",
            "reels": fieldpacks.field_reels(field), "field_media": [r for r in fieldpacks.field_reels(field) if field and (FRONTEND_DIR / "gallery" / "f" / Path(field).name / f"{r}.jpg").exists()],
            "logo": bool(logo_path(bid)) if bid else False, "logo_asked": bool(b.get("logo_asked")),
            "job": job, "steps": steps, "first_done": bool(j.get("status") == "done"), "brand": first_brand_name(b),
            "briefs": {r: tplbrief.brief(r, field, first_brand_name(b)) for r in fieldpacks.field_reels(field) if tplbrief.brief(r, field)},
            "briefs_en": {r: tplbrief.brief_en(r, field, first_brand_name(b)) for r in fieldpacks.field_reels(field) if tplbrief.brief(r, field)},
            "about_ph": pack.get("about_ph") or "مثلًا: ماذا تبيع أو تقدم، وأين، وما الذي يميزك عن غيرك",
            "audience_ph": "العمر، والاهتمامات، وما الذي يبحث عنه", "score": brain_score(b), **fieldpacks.signup_options()}


@app.post("/api/onboard")
def onboard_save(body: OnboardIn):
    bid = active_client_id()
    if not bid:
        raise HTTPException(404, "لا توجد علامة")
    ob = fieldpacks.onboard_dict(body.country.strip().upper()[:2], body.dialect.strip()[:20], body.field.strip()[:20], body.goal.strip()[:20])
    if not ob:
        raise HTTPException(400, "اختر بلدك أو لهجة المحتوى")
    field_pack_apply(bid, ob)
    return onboard_state()


@app.post("/api/onboard/first")
def onboard_first(body: FirstIn):
    """سؤالا أول فيديو فقط: ما الذي تقدمه، ومن عميلك المثالي. الباقي يُسأل تدريجيًا بعد كل مشروع."""
    bid = active_client_id()
    if not bid:
        raise HTTPException(404, "لا توجد علامة")
    about, aud = body.about.strip()[:3000], body.audience.strip()[:2000]
    if not about:
        raise HTTPException(400, "اكتب ما الذي تقدمه في جملة أو جملتين")

    def fn(d):
        d["about"] = about
        if aud:
            d["audience"] = aud
        d.setdefault("quiz_done", [])
        for q in ("about", *(("audience",) if aud else ())):
            if q not in d["quiz_done"]:
                d["quiz_done"].append(q)
        d["first_at"] = now()
    old = brain_row(bid) or {}
    update_brain(bid, fn)
    seasons_if_changed(bid, old, brain_row(bid) or {})
    return onboard_state()


# ---------------------------------------------------------------- 🎬 أول فيديو: اللوجو ← الألوان ← الأوترو ← فيديو كامل مجانًا
# اللوجو اختياري: بنشيل خلفيته على الجهاز (من غير نقاط) والعميل بيختار الأصلي أو اللي من غير خلفية.
# ألوانه بتروح لفرع «الشكل» في العقل، والأوترو بيتعمل منه (أو من اسم العلامة). وأول فيديو بيتعمل كله لوحده بخطوات ظاهرة،
# واللوجو في ركنه والأوترو في آخره، ونقاطه بترجع للعميل هدية.
import firstvid  # noqa: E402

FIRST_STEPS = (("script", "نكتب النص"), ("voice", "نسجّل الصوت"), ("draw", "نرسم الفيديو"), ("brand", "نضع اللوجو والأوترو"))
FIRST_FONT = FONTS_DIR / "SM-Tajawal.ttf"


def dialect_phrase(b: dict) -> str:
    return fieldpacks.dialect_phrase(dialect.code(b or {}, brand_settings().get("language") or ""))


def first_brand_name(b: dict) -> str:
    n = str(b.get("name") or "").strip()
    return "" if n in ("", "علامتي", "علامتك", "عميلي", "عميل جديد", "علامة جديدة") else n[:40]


def first_colors_apply(bid: str, path: Path) -> list[str]:
    """ألوان اللوجو ← فرع «الشكل» في العقل (لو العميل ماكتبش ألوانه بنفسه)."""
    cols = firstvid.palette(path)
    if not cols:
        return []
    names = ("الأساسي", "الثانوي", "المساعد")
    txt = "، ".join(f"{c} ({names[i]})" for i, c in enumerate(cols))
    def fn(d):
        if not str(d.get("palette") or "").strip() or "palette" not in (d.get("edited") or []):
            d["palette"] = txt
    update_brain(bid, fn)
    return cols


def first_outro(bid: str, force: bool = False) -> Path | None:
    """أوترو العلامة من اللوجو (أو اسمها). مابيلمسش أوترو رفعه العميل بنفسه."""
    b = brain_row(bid) or {}
    if b.get("outro_file") and not b.get("outro_auto") and not force:
        return brand_video("outro", bid)
    logo = logo_path(bid)
    name = first_brand_name(b)
    if not logo and not name:
        return None
    cols = re.findall(r"#[0-9a-fA-F]{6}\b", str(b.get("palette") or ""))
    dest = brain_dir(bid) / f"brand-outro-auto-{uuid.uuid4().hex[:6]}.mp4"
    firstvid.outro(ffmpeg_exe(), dest, logo, name, cols, FIRST_FONT)
    def fn(d):
        old = d.get("outro_file")
        if old and d.get("outro_auto"):
            (brain_dir(bid) / old).unlink(missing_ok=True)
        d.update(outro_file=dest.name, outro_on="1", outro_auto=True)
    update_brain(bid, fn)
    return dest


@app.post("/api/onboard/logo")
def onboard_logo(file: UploadFile = File(...)):
    """🖼️ اللوجو: الأصلي + نسخة من غير خلفية، والعميل يختار."""
    bid = active_client_id()
    if not bid:
        raise HTTPException(404, "لا توجد علامة")
    folder, tag = brain_dir(bid), uuid.uuid4().hex[:6]
    src = save_upload(file, IMAGE_EXTENSIONS, folder, f"logo-src-{tag}")
    cut = f"logo-cut-{tag}.png"
    try:
        r = firstvid.cutout(folder / src, folder / cut)
    except Exception:  # noqa: BLE001
        (folder / src).unlink(missing_ok=True)
        raise HTTPException(400, "هذا الملف ليس صورة سليمة، جرّب PNG أو JPG")
    def fn(d):
        for k in ("src", "cut"):
            old = (d.get("logo_try") or {}).get(k)
            if old:
                (folder / old).unlink(missing_ok=True)
        d["logo_try"] = {"src": src, "cut": cut, "already": r["already"]}
    update_brain(bid, fn)
    base = f"/media/ads/brains/{bid}"
    return {"src_url": f"{base}/{src}", "cut_url": f"{base}/{cut}", "already": r["already"]}


class LogoPickIn(BaseModel):
    pick: str = "cut"   # cut = من غير خلفية، src = الأصلي، skip = بدون لوجو دلوقتي


@app.post("/api/onboard/logo/pick")
def onboard_logo_pick(body: LogoPickIn):
    bid = active_client_id()
    if not bid:
        raise HTTPException(404, "لا توجد علامة")
    b = brain_row(bid) or {}
    t = b.get("logo_try") or {}
    folder = brain_dir(bid)
    if body.pick in ("cut", "src") and t.get(body.pick) and (folder / t[body.pick]).exists():
        keep = t[body.pick]
        name = f"logo-{uuid.uuid4().hex[:6]}{Path(keep).suffix}"
        (folder / keep).rename(folder / name)
        def fn(d):
            other = (d.get("logo_try") or {}).get("src" if body.pick == "cut" else "cut")
            if other:
                (folder / other).unlink(missing_ok=True)
            d.pop("logo_try", None)
            d["logos"] = [{"file": name, "name": "الشعار", "description": ""}] + [a for a in d.get("logos") or [] if a.get("name") != "الشعار"]
            d.update(logo_on="1", logo_asked=True)
        update_brain(bid, fn)
        cols = first_colors_apply(bid, folder / name)
    else:
        update_brain(bid, lambda d: d.update(logo_asked=True))
        cols = []
    try:
        first_outro(bid)
    except Exception:  # noqa: BLE001  الأوترو إضافة: لو ماتعملش، أول فيديو بيتعمل من غيره
        pass
    return {**onboard_state(), "colors": cols}


