def first_job_set(bid: str, jid: str, **kw) -> None:
    def fn(d):
        j = d.get("first_job") or {}
        if j.get("id") == jid:
            j.update(kw)
            d["first_job"] = j
    update_brain(bid, fn)


def first_wait(fid: str, ok, what: str, retry=None, limit: float = 900) -> dict:
    """يستنى خطوة المسار لحد ما تخلص (ومحاولة تانية لو وقفت)."""
    t0, tried = time.time(), False
    while time.time() - t0 < limit:
        d = flow_load(fid)
        if ok(d):
            return d
        if d.get("error") or flow_stale(d):
            if tried or not retry:
                raise HTTPException(400, d.get("error") or f"{what} توقف")
            tried = True
            flow_update(fid, lambda x: x.update(error=None, busy=None))
            retry()
        time.sleep(2)
    raise HTTPException(400, f"{what} أخذ وقتًا أطول من اللازم")


FIRST_GIFT_MAX = 300   # سقف هدية أول فيديو (أكبر من تكلفته بكتير، عشان أي توليد تاني في نفس الوقت مايبقاش مجاني)


def first_gift(bid: str) -> int:
    """🎁 أول فيديو مجاني فعلًا: كل اللي اتصرف من فتح الحساب لحد ما أول فيديو خلص (قراءة العلامة، الترند، الأفكار، النص، الصوت…)
    بيرجع في سطر واحد «أول فيديو مجانًا». بتتنادى لما الفيديو يخلص، وتاني مع كل فتحة للبرنامج لو الهدية لسه ماتسجلتش (من غير تكرار)."""
    j = (brain_row(bid) or {}).get("first_job") or {}
    if j.get("status") != "done" or wallet.free():
        return 0
    ref = f"first:{j.get('id')}"
    fin = j.get("finished_ts")
    if not fin and j.get("finished_at"):   # أول فيديو خلص قبل التحديث ده: وقت الاكتمال مكتوب كنص
        try:
            fin = datetime.fromisoformat(j["finished_at"]).timestamp()
        except ValueError:
            fin = None
    end = float(fin or j.get("at") or time.time()) + 20   # الخصم اللي بيتسجل بعد الاكتمال بثواني (تسوية التقدير)
    start = min(x for x in (wallet.first_at(), j.get("t0"), j.get("at")) if x)
    due = min(wallet.spent_between(start, end), FIRST_GIFT_MAX) - wallet.gifted(ref) - wallet.gifted(str(j.get("id") or "-"))   # (النسخة القديمة كانت بتسجلها بالـ id بس)
    if due <= 0:
        return 0
    n = wallet.gift(due, "🎁 أول فيديو مجانًا", ref)
    first_job_set(bid, j["id"], cost=(j.get("cost") or 0) + n)
    return n


def run_first(bid: str, jid: str, tpl: str, name: str, t0: float, facts: dict | None = None) -> None:
    put = lambda **kw: first_job_set(bid, jid, **kw)  # noqa: E731
    done: list[str] = []
    step = lambda k: put(step=k, done=list(done))  # noqa: E731
    try:
        step("script")
        f = flow_new(FlowNewIn(template=tpl, name=name, skip_ideas=bool(facts)))
        fid = f["id"]
        put(fid=fid)
        if facts:   # 🧾 الفكرة جاية من معطيات العميل: الأفكار والنص بيتبنوا عليها، والخانات دي مقفولة
            flow_set_facts(fid, tpl, facts)
            flow_job(fid, "ideas", lambda: flow_gen_ideas(fid, tplbrief.prompt_text(tplbrief.apply(tpl, facts)[1])))
        d = first_wait(fid, lambda x: bool(x.get("ideas")), "اقتراح الفكرة", lambda: flow_job(fid, "ideas", lambda: flow_gen_ideas(fid)))
        flow_pick_idea(fid, FlowPickIn(id=d["ideas"][0]["id"]))
        d = first_wait(fid, lambda x: bool(x.get("scenarios")), "كتابة النص", lambda: flow_job(fid, "scenarios", lambda: flow_gen_scenarios(fid)))
        flow_pick_scenario(fid, FlowPickIn(id=d["scenarios"][0]["id"]))
        done.append("script")
        step("voice")
        d = flow_load(fid)
        lang = d.get("lang") if d.get("lang") in dub.DIALECTS else flow_lang_guess(d)
        voice = FlowVoiceIn(speaker="narrator", lang=lang, voice=dub.DIALECTS[lang]["voices"][0])
        flow_voice(fid, voice)
        first_wait(fid, lambda x: bool((x.get("vo_track") or {}).get("file")), "تسجيل الصوت", lambda: flow_voice(fid, voice))
        done.append("voice")
        step("draw")
        flow_export(fid, FlowExportIn())
        t0 = time.time()
        while True:
            o = flow_to_dict(fid, flow_load(fid)).get("output") or {}
            if o.get("status") == "failed":
                raise HTTPException(400, o.get("error") or "رسم الفيديو توقف")
            if o.get("status") == "done" and o.get("asset"):
                break
            if time.time() - t0 > 1500:
                raise HTTPException(400, "رسم الفيديو أخذ وقتًا أطول من اللازم")
            put(progress=round((o.get("progress") or 0) * 100))
            time.sleep(3)
        done.append("draw")
        step("brand")
        src = ASSETS_DIR / Path(o["asset"]).name / "clip.mp4"
        outro_p = brand_video("outro", bid)
        if not outro_p:
            try:
                outro_p = first_outro(bid)
            except Exception:  # noqa: BLE001
                outro_p = None
        final = FLOWS_DIR / Path(fid).name / "first_final.mp4"
        firstvid.brand_finish(ffmpeg_exe(), src, final, logo_path(bid) if (brain_row(bid) or {}).get("logo_on") != "0" else None, outro_p)
        title = ((flow_load(fid).get("idea") or {}).get("title") or name)[:80]
        ex = pilot_export_file(final, f"🎬 أول فيديو: {title}")
        done.append("brand")
        with closing(db()) as conn:
            r = conn.execute("SELECT filename FROM exports WHERE id = ?", (ex,)).fetchone()
        put(status="done", step=None, done=list(done), export_id=ex, video_url=f"/media/exports/{r['filename']}" if r else None,
            title=title, cost=0, finished_at=now(), finished_ts=time.time(), qa=flow_load(fid).get("qa"))
        # 🎁 كل اللي اتخصم لحد هنا بيرجع في سطر واحد «هدية» في سجل النقاط (ولو فشل هنا، بيتسجل مع أول فتحة جاية)
        try:
            first_gift(bid)
        except Exception as exc:  # noqa: BLE001
            print(f"[first-gift] {bid}: {exc}", flush=True)
        notify("first", "ok", "🎬 أول فيديو جاهز", title, "", ex)
    except Exception as exc:  # noqa: BLE001
        msg = str(getattr(exc, "detail", None) or exc)[:300]
        put(status="failed", error=msg)


@app.post("/api/onboard/first/go")
def onboard_first_go(body: FirstGoIn):
    """🎬 بعد السؤالين: أول فيديو بيتعمل كله لوحده (النص ← الصوت ← الرسم ← اللوجو والأوترو)."""
    bid = active_client_id()
    if not bid:
        raise HTTPException(404, "لا توجد علامة")
    t0 = time.time() - 1
    if body.about.strip():
        onboard_first(FirstIn(about=body.about, audience=body.audience))
    j = (brain_row(bid) or {}).get("first_job") or {}
    if j.get("status") == "run" and time.time() - (j.get("at") or 0) < 3600:
        return onboard_state()
    reels = fieldpacks.field_reels((brain_row(bid) or {}).get("field") or "")
    tpl = body.template if body.template in reels or body.template.startswith("t-") else reels[0]
    facts, errs = tplbrief.validate(tpl, body.facts or {})
    if errs:
        raise HTTPException(400, " · ".join(errs))
    jid = uuid.uuid4().hex[:8]
    update_brain(bid, lambda d: d.update(first_job={"id": jid, "tpl": tpl, "status": "run", "step": "script", "done": [], "at": time.time(), "t0": t0, "facts": facts}))
    threading.Thread(target=run_first, args=(bid, jid, tpl, body.name.strip()[:80] or tpl, t0, facts), daemon=True).start()
    return onboard_state()


def active_client_id() -> str | None:
    seed_brain()
    onboard_apply()
    migrate_rules()
    cid = auth.get_setting("active_client")
    if cid and brain_row(cid):
        return cid
    return first_client_id()


def active_client() -> dict | None:
    cid = active_client_id()
    return brain_row(cid) if cid else None


def owned(client_id: str | None) -> bool:
    """هذه الشيء الخاصة بالعميل المختار؟ (ما ليس لها عميل، أو عميلها حُذف، الخاصة بـ أقدم عميل)"""
    if client_id and brain_row(client_id):
        return client_id == active_client_id()
    return first_client_id() == active_client_id()


def ad_brain(settings: dict | None) -> dict | None:
    """ملف العميل المختار هذا للإعلان (وإذا غير مختار: العميل الحالي)."""
    bid = (settings or {}).get("brain_id")
    if bid == "none":
        return None
    return (brain_row(bid) if bid else None) or active_client()


atlas.modesty_on = lambda: bool((active_client() or {}).get("modest"))  # اللبس المحتشم حسب ملف العميل (قديم: بقى جوه قواعد المحتوى)
atlas.brand_rules = lambda: str((active_client() or {}).get("rules") or "").strip()[:1500]   # قواعد المحتوى في كل برومبت
atlas.brand_cta = lambda: str((active_client() or {}).get("cta") or "").strip()[:300]


def migrate_rules() -> None:
    """«لبس محتشم» كان اختيار تلقائيًا: بقى جملة داخل «قواعد المحتوى» (مربع النص الحر) لكي المستخدم يكتب الذي يناسبه."""
    if auth.get_setting("rules_v2"):
        return
    with closing(db()) as conn:
        ids = [r["id"] for r in conn.execute("SELECT id FROM ad_brains")]
    for bid in ids:
        def fn(d):
            if d.get("modest"):
                line = "اللبس محتشم دائمًا: البنات لبس واسع طويل مع حجاب، والرجالة تيشيرت ونطلون أو شورت أسفل الركبة."
                if "محتشم" not in (d.get("rules") or ""):
                    d["rules"] = (line + " " + (d.get("rules") or "")).strip()
                d["modest"] = ""
        update_brain(bid, fn)
    auth.set_setting("rules_v2", "1")


@app.post("/api/ad-brains/{bid}/brand-video")
def upload_brand_video(bid: str, kind: str = Form("outro"), file: UploadFile = File(...)):
    """🎬 إنترو / أوترو العلامة: ينزل تلقائيًا في أول/آخر كل مونتاج إذا متفعّل."""
    if kind not in BRAND_VIDEOS:
        raise HTTPException(400, "النوع يجب intro أو outro")
    if not brain_row(bid):
        raise HTTPException(404, "هذا العميل غير موجود")
    ext = Path(file.filename or "").suffix.lower()
    if ext not in (".mp4", ".mov", ".webm", ".m4v"):
        raise HTTPException(400, "ارفع فيديو (MP4 / MOV / WEBM)")
    name = f"brand-{kind}-{uuid.uuid4().hex[:6]}{ext}"
    dest = brain_dir(bid) / name
    with dest.open("wb") as f:
        shutil.copyfileobj(file.file, f)
    try:
        media_info(dest)
    except Exception:
        dest.unlink(missing_ok=True)
        raise HTTPException(400, "هذا الملف غير فيديو سليم")
    def fn(d):
        old = d.get(f"{kind}_file")
        if old:
            (brain_dir(bid) / old).unlink(missing_ok=True)
        d[f"{kind}_file"] = name
        d[f"{kind}_on"] = "1"
    update_brain(bid, fn)
    return brain_to_dict(brain_row(bid))


@app.delete("/api/ad-brains/{bid}/brand-video/{kind}")
def delete_brand_video(bid: str, kind: str):
    if kind not in BRAND_VIDEOS:
        raise HTTPException(400, "النوع يجب intro أو outro")
    def fn(d):
        old = d.pop(f"{kind}_file", None)
        if old:
            (brain_dir(bid) / old).unlink(missing_ok=True)
        d[f"{kind}_on"] = ""
    update_brain(bid, fn)
    return brain_to_dict(brain_row(bid))


# 🎬 صانع الإنترو والأوترو: قالب بالكود (library/motion/r/b-intro و b-outro) بلوجو العميل وألوانه واسمه، بيترسم فيديو
# وبيتحط مكان إنترو/أوترو العلامة على طول (ومتفعّل). مفيش توليد، فمفيش نقط.
BRAND_REEL = {"intro": "b-intro", "outro": "b-outro"}
BRAND_JOBS: dict[str, dict] = {}   # "<bid>:<kind>" → {status, progress, error}


class BrandMakeIn(BaseModel):
    kind: str = "intro"
    style: str = ""
    bgk: str = "dark"
    ratio: str = "9:16"
    textk: str = "name"
    cta: str = ""
    tag: str = ""
    handle: str = ""
    link: str = ""


def brand_reel_params(b: dict, body: BrandMakeIn) -> dict:
    """القيم من العقل (الاسم، الشعار، الألوان، الدعوة، الحساب)، وما كتبه العميل في الصانع فوقها."""
    d = brain_to_dict(b)
    hexes = re.findall(r"#[0-9a-fA-F]{6}\b", str(d.get("palette") or ""))
    handle = re.search(r"instagram\.com/([A-Za-z0-9_.]+)", str(d.get("link") or ""))
    about = re.split(r"[.\n،,]", str(d.get("about") or ""))[0].strip()[:40]
    out = {"brand": str(d.get("name") or "")[:18], "logo": ((d.get("logos") or [{}])[0]).get("url") or "",
           "c1": hexes[0] if hexes else "", "c2": hexes[1] if len(hexes) > 1 else (hexes[0] if hexes else ""),
           "tag": body.tag.strip()[:40] or about, "cta": body.cta.strip()[:24] or str(d.get("cta") or "")[:24],
           "handle": body.handle.strip()[:30] or (f"@{handle.group(1)}" if handle else ""),
           "link": body.link.strip()[:40] or re.sub(r"^https?://(www\.)?", "", str(d.get("link") or ""))[:40],
           "style": body.style, "bgk": body.bgk, "ratio": body.ratio, "textk": body.textk}
    return {k: v for k, v in out.items() if v}


def run_brand_make(bid: str, body: BrandMakeIn, params: dict) -> None:
    key = f"{bid}:{body.kind}"
    job = BRAND_JOBS[key]
    tmp = brain_dir(bid) / f"make-{uuid.uuid4().hex[:6]}"
    try:
        tmp.mkdir(parents=True, exist_ok=True)
        name = f"brand-{body.kind}-{uuid.uuid4().hex[:6]}.mp4"
        motion_to_mp4(BRAND_REEL[body.kind], params, tmp, brain_dir(bid) / name, lambda k: job.update(progress=k))
        def fn(d):
            old = d.get(f"{body.kind}_file")
            if old:
                (brain_dir(bid) / old).unlink(missing_ok=True)
            d[f"{body.kind}_file"] = name
            d[f"{body.kind}_on"] = "1"
            d[f"{body.kind}_made"] = {k: v for k, v in body.model_dump().items() if k != "kind"}
        update_brain(bid, fn)
        BRAND_JOBS.pop(key, None)
    except Exception as e:  # noqa: BLE001
        job.update(status="error", error=str(e)[:300])
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


@app.get("/api/brand-reel-params/{bid}")
def brand_reel_preview_params(bid: str, kind: str = "intro"):
    """القيم للمعاينة الحية في الصانع (نفس اللي هيترسم)، وحالة الرسم لو شغال."""
    b = brain_row(bid)
    if b is None or kind not in BRAND_REEL:
        raise HTTPException(404, "هذا العميل غير موجود")
    return {"reel": f"/media/motion/r/{BRAND_REEL[kind]}/reel.html", "params": brand_reel_params(b, BrandMakeIn(kind=kind)),
            "made": b.get(f"{kind}_made") or {}, "job": BRAND_JOBS.get(f"{bid}:{kind}")}


@app.post("/api/ad-brains/{bid}/brand-video/make")
def make_brand_video(bid: str, body: BrandMakeIn):
    b = brain_row(bid)
    if b is None:
        raise HTTPException(404, "هذا العميل غير موجود")
    if body.kind not in BRAND_REEL:
        raise HTTPException(400, "النوع يجب intro أو outro")
    key = f"{bid}:{body.kind}"
    if (BRAND_JOBS.get(key) or {}).get("status") == "working":
        raise HTTPException(400, "يُرسم الآن، انتظر حتى ينتهي")
    BRAND_JOBS[key] = {"status": "working", "progress": 0.0, "error": ""}
    threading.Thread(target=run_brand_make, args=(bid, body, brand_reel_params(b, body)), daemon=True).start()
    return {"ok": True, "job": BRAND_JOBS[key]}


def coach_intro(data: dict) -> Path | None:
    """إنترو الشخصية الخاصة بالمشروع إذا لها."""
    if not data.get("coach_id"):
        return None
    with closing(db()) as conn:
        r = conn.execute("SELECT intro_filename FROM coaches WHERE id = ?", (data["coach_id"],)).fetchone()
    p = COACHES_DIR / r["intro_filename"] if r and r["intro_filename"] else None
    return p if p and p.exists() else None


def brand_video(kind: str, client_id: str | None = None) -> Path | None:
    """إنترو/أوترو العلامة المختار (أو عميل معيّن)، إذا متفعّل وموجود."""
    c = (brain_row(client_id) if client_id else None) or active_client() or {}
    f = c.get(f"{kind}_file")
    if not f or not c.get(f"{kind}_on"):
        return None
    p = brain_dir(c["id"]) / f
    return p if p.exists() else None


@app.get("/api/clients")
def list_clients():
    """👤 العملاء (للاختيار من أعلى) والعميل المختار."""
    active = active_client_id()
    out = []
    for b in list_brains():
        out.append({"id": b["id"], "name": b["name"], "domain": b.get("domain", ""),
                    "logo": (b.get("logos") or [{}])[0].get("url"), "active": b["id"] == active,
                    **{f"{k}_url": b.get(f"{k}_url") if b.get(f"{k}_on") else None for k in BRAND_VIDEOS},
                    "caption": b.get("caption", ""), "cta": b.get("cta", ""), "link": b.get("link", "")})
    return {"clients": out, "active": active}


