class BrainIn(BaseModel):
    name: str | None = None
    fields: dict = {}


@app.post("/api/ad-brains")
def create_brain(body: BrainIn):
    bid = uuid.uuid4().hex[:12]
    data = {"type": "app", **{k: str(body.fields.get(k) or "") for k in BRAIN_FIELDS if k != "type"},
            "screens": [], "logos": [], "products": [], "status": "idle"}
    if body.fields.get("type") in az.BRAIN_TYPES:
        data["type"] = body.fields["type"]
    with closing(db()) as conn, conn:
        conn.execute("INSERT INTO ad_brains (id, name, data, created_at) VALUES (?, ?, ?, ?)",
                     (bid, (body.name or "").strip()[:80] or "عميل جديد", json.dumps(data, ensure_ascii=False), now()))
    return brain_to_dict(brain_row(bid))


# ✨ «اقترح» جوه كارت الخانة نفسها (زي «اقترح خطوط»): المخ بيقترح قيمة، والاقتراح بيظهر جوه الكارت تقبله أو تتجاهله
SUGGEST_FIELDS = {"typography": ("fonts for this brand: one font for headlines and one for body text, both free Google Fonts that support Arabic "
                                 "(and Latin if the brand writes English). Write it as one short Egyptian-Arabic line like «Cairo للعناوين و IBM Plex Sans Arabic للكلام» "
                                 "and why in one sentence.", "Cairo للعناوين (عريض) و IBM Plex Sans Arabic للكلام")}


@app.post("/api/ad-brains/{bid}/suggest/{field}")
def brain_suggest_field(bid: str, field: str):
    b = brain_row(bid)
    if not b:
        raise HTTPException(404, "هذا العلامة غير موجود")
    if field not in SUGGEST_FIELDS:
        raise HTTPException(400, "لا يوجد اقتراح هذه للخانة")
    ask, mock = SUGGEST_FIELDS[field]
    if atlas.mock_mode():
        out = {"value": mock, "why": "خطوط واضحة وتدعم العربية، وشكلها مناسب للسوشيال"}
    else:
        wallet.need(1, "اقتراح")
        msgs = [{"role": "system", "content": "You are a brand designer. Return JSON only."},
                {"role": "user", "content": f"Brand:\n{az.brain_text(b)[:4000]}\n\nSuggest {ask}\n"
                                            f"Current value (improve on it or keep its spirit): {b.get(field) or '-'}\n"
                                            'Return JSON: {"value": "...", "why": "one short Egyptian-Arabic sentence"}'}]
        out = az.parse_json(series_chat(msgs), "الاقتراح")
        wallet.charge(wallet.credits(wallet.est(chars=6000)), f"عقل العلامة: اقتراح {field}", bid)
    val = str(out.get("value") or "").strip()[:600]
    if not val:
        raise HTTPException(502, "العقل مااقترحش شيء، جرّب مرة أخرى")
    item = {"id": uuid.uuid4().hex[:10], "kind": "field", "field": field, "value": val, "why": str(out.get("why") or "").strip()[:300], "source": "suggest"}

    def fn(d):
        d["pending"] = [p for p in d.get("pending") or [] if not (p.get("kind") == "field" and p.get("field") == field)] + [item]
    update_brain(bid, fn)
    return brain_to_dict(brain_row(bid))


def quiz_rule(line: str) -> str:
    line = re.sub(r"^[\-•*\d.)\s]+", "", line.strip())
    return line if re.match(r"^(ممنوع|لا |لازم|دايمًا|دايما|دائمًا|من غير|بدون|never|always|don'?t|no )", line, re.I) else f"ممنوع في المحتوى: {line}"


@app.patch("/api/ad-brains/{bid}")
def patch_brain(bid: str, body: BrainIn):
    def fn(d):
        for k in BRAIN_FIELDS:
            if k in body.fields:
                v = str(body.fields[k] or "")
                if k == "type" and v not in az.BRAIN_TYPES:
                    continue
                if k == "type":
                    d["type_set"] = True   # النوع اتختار بإيد العميل (مش الافتراضي)
                d[k] = v[:8000]
                if k in ("palette", "theme", "typography", "ui_style", "logo_description") and k not in d.setdefault("edited", []):
                    d["edited"].append(k)  # الاستنباط بعد كده ميغيّرش اللي كتبته بإيدك
        if "styles" in body.fields:   # الستايل الافتراضي بيكتب «ستايل الرسم» لو انت مكتبتهوش بإيدك
            mine = {c["id"]: c for c in d.get("custom_styles") or [] if c.get("prompt")}   # ستايلاتك اللي المخ استنبطها
            d["styles"] = ",".join(x for x in d.get("styles", "").split(",") if x in STYLE_CAT_IDS or x in mine)
            first = next((c for c in [*STYLE_CATS, *mine.values()] if c["id"] == d["styles"].split(",")[0]), None)
            if first and "style" not in d.get("edited", []):
                d["style"] = first["prompt"]
        if "style" in body.fields and "styles" not in body.fields and "style" not in d.setdefault("edited", []):
            d["edited"].append("style")
        return (body.name or "").strip()[:80] or None
    old = brain_row(bid) or {}
    update_brain(bid, fn)
    new = brain_row(bid) or {}
    seasons_if_changed(bid, old, new)   # 🗓️ المواسم بتتجاب من جديد لوحدها
    audiences_auto(bid, old, new)       # 👥 والجماهير بتتستخلص من الوصف الجديد
    return brain_to_dict(new)


@app.delete("/api/ad-brains/{bid}")
def delete_brain(bid: str):
    with closing(db()) as conn:
        if conn.execute("SELECT COUNT(*) FROM ad_brains").fetchone()[0] <= 1:
            raise HTTPException(400, "هذا آخر عميل. أنشئ عميل آخر أولًا")
    with closing(db()) as conn, conn:
        conn.execute("DELETE FROM ad_brains WHERE id = ?", (bid,))
    shutil.rmtree(ADS_DIR / "brains" / Path(bid).name, ignore_errors=True)
    return {"ok": True}


@app.post("/api/ad-brains/{bid}/assets")
def upload_brain_assets(bid: str, kind: str = Form("screens"), files: list[UploadFile] = File(...)):
    """رفع شاشات التطبيق (مجلد كامل) أو الشعار أو صور المنتج. بعدها البرنامج يوصّفهم ويستنبط الهوية تلقائيًا."""
    if kind not in BRAIN_KINDS:
        raise HTTPException(400, "نوع غير معروف")
    if brain_row(bid) is None:
        raise HTTPException(404, "هذا العميل غير موجود")
    folder = brain_dir(bid)
    added = []
    for f in files[:120]:
        if Path(f.filename or "").suffix.lower() not in IMAGE_EXTENSIONS:
            continue  # الفولدر ممكن يكون فيه ملفات تانية
        name = save_upload(f, IMAGE_EXTENSIONS, folder, kind[:-1])
        added.append({"file": name, "name": Path(f.filename or name).stem[:60], "description": ""})
    if not added:
        raise HTTPException(400, "لا يوجد صور في هذه الملفات (PNG / JPG / WEBP)")
    update_brain(bid, lambda d: d.setdefault(kind, []).extend(added) or d.update(status="working", error=None))
    threading.Thread(target=run_brain_analyze, args=(bid,), daemon=True).start()
    return brain_to_dict(brain_row(bid))


class BrainAssetIn(BaseModel):
    name: str | None = None
    description: str | None = None


def find_brain_asset(d: dict, file: str) -> tuple[str, dict]:
    for kind in BRAIN_KINDS:
        for a in d.get(kind) or []:
            if a["file"] == file:
                return kind, a
    raise HTTPException(404, "هذه الصورة غير موجودة")


@app.patch("/api/ad-brains/{bid}/assets/{file}")
def patch_brain_asset(bid: str, file: str, body: BrainAssetIn):
    def fn(d):
        _, a = find_brain_asset(d, file)
        if body.name is not None:
            a["name"], a["named"] = body.name.strip()[:80], True
        if body.description is not None:
            a["description"] = body.description.strip()[:2000]
    update_brain(bid, fn)
    return brain_to_dict(brain_row(bid))


@app.delete("/api/ad-brains/{bid}/assets/{file}")
def delete_brain_asset(bid: str, file: str):
    def fn(d):
        kind, a = find_brain_asset(d, file)
        d[kind] = [x for x in d[kind] if x is not a]
    update_brain(bid, fn)
    (brain_dir(bid) / Path(file).name).unlink(missing_ok=True)
    return brain_to_dict(brain_row(bid))


@app.post("/api/ad-brains/{bid}/analyze")
def analyze_brain(bid: str):
    b = brain_row(bid)
    if b is None:
        raise HTTPException(404, "هذا العميل غير موجود")
    if not any(b.get(k) for k in BRAIN_KINDS):
        raise HTTPException(400, "ارفع الشعار أو شاشات التطبيق أولًا")
    update_brain(bid, lambda d: d.update(status="working", error=None))
    threading.Thread(target=run_brain_analyze, args=(bid,), daemon=True).start()
    return brain_to_dict(b)


# ---------- 🧠 مصادر العقل: ملف / لينك / كلام ← اقتراحات بتستنى موافقتك ----------
@app.post("/api/ad-brains/{bid}/sources")
def add_brain_source(bid: str, url: str = Form(""), text: str = Form(""), note: str = Form(""), social: str = Form(""), files: list[UploadFile] | None = File(None)):
    if brain_row(bid) is None:
        raise HTTPException(404, "هذا العميل غير موجود")
    folder = brain_dir(bid) / "src"
    folder.mkdir(exist_ok=True)
    new = []
    for f in (files or [])[:10]:
        ext = Path(f.filename or "").suffix.lower()
        if ext not in brainsrc.SOURCE_EXT:
            raise HTTPException(400, f"نوع هذا الملف ما زال غير مدعوم: {ext or 'بدون امتداد'} (PDF، Word، صور، نص، صوت، فيديو)")
        name = save_upload(f, brainsrc.SOURCE_EXT, folder, "src")
        new.append({"kind": "file", "name": (f.filename or name)[:120], "file": name})
    if url.strip():
        try:
            u = brainsrc.safe_url(url)
        except ValueError as exc:
            raise HTTPException(400, str(exc)) from exc
        new.append({"kind": "url", "name": urlparse(u).hostname + urlparse(u).path.rstrip("/"), "url": u})
    if text.strip():
        new.append({"kind": "text", "name": text.strip().split("\n")[0][:60], "text": text.strip()[:60000]})
    if social.strip():
        plat, handle = brainsocial.parse(social)
        if not handle:
            raise HTTPException(400, "اكتب يوزر الحساب أو لينكه")
        if not atlas.mock_mode() and not rivals.live():   # من غير المفتاح: نقول على طول بدل ما يتسجل مصدر فاشل
            raise HTTPException(503, rivals.missing_msg() if os.environ.get("TENANT_ROLE") != "customer"
                                else "تحليل الحسابات غير متاح الآن. جرّب مرة أخرى بعد قليل")
        new.append({"kind": "social", "name": f"@{handle} · {'تيك توك' if plat == 'tiktok' else 'إنستجرام'}", "platform": plat, "handle": handle})
    if not new:
        raise HTTPException(400, "ارمي ملف أو ضع رابط أو اكتب شيء")
    # 💳 قبل ما نبدأ: الرصيد لازم يكفي التقدير (تحليل الحساب أغلى من قراية ملف)
    try:
        wallet.need(sum(wallet.credits(wallet.est(scrape=3, chars=40000, images=20, stt_min=3)) if x["kind"] == "social" else 3 for x in new), "قراءة المصادر")
    except wallet.NoCredits as e:
        raise HTTPException(402, str(e)) from e
    for s in new:
        s.update(id=uuid.uuid4().hex[:10], status="working", error=None, count=0, note=note.strip()[:300], created_at=now())
    update_brain(bid, lambda d: d.setdefault("sources", []).extend(new))
    for s in new:
        threading.Thread(target=run_brain_source, args=(bid, s["id"]), daemon=True).start()
    return brain_to_dict(brain_row(bid))


def brain_av_text(p: Path, folder: Path) -> tuple[str, list[Path]]:
    """ملف صوت أو فيديو (أو تسجيل من الميكروفون): النص يتفرّغ نص، وإذا فيه صورة نأخذ ٣ لقطات منه."""
    wav = folder / f"{p.stem}-stt.wav"
    ff = [ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y"]
    subprocess.run(ff + ["-i", str(p), "-vn", "-ac", "1", "-ar", "16000", str(wav)], check=True, capture_output=True, timeout=600)
    dur = probe_duration(wav)
    if dur < .5:
        raise ValueError("الملف لا يحتوي صوت مسموع")
    try:
        words = atlas.transcribe(wav, dur)
    finally:
        wav.unlink(missing_ok=True)
    text = " ".join(str(w.get("w") or "").strip() for w in words).strip()
    imgs = []
    # تسجيل المايك بيتحفظ webm صوت بس ومن غير طول في الملف: اللقطات بس لو فيه صورة فعلًا، والطول من الصوت
    info = subprocess.run([ffmpeg_exe(), "-hide_banner", "-i", str(p)], capture_output=True, text=True).stderr
    if p.suffix.lower() in brainsrc.VIDEO_EXT and re.search(r"Stream #.*Video:", info):
        m = re.search(r"Duration:\s*(\d+):(\d+):(\d+(?:\.\d+)?)", info)
        vdur = int(m[1]) * 3600 + int(m[2]) * 60 + float(m[3]) if m else dur
        for i, f in enumerate((.2, .5, .8)):
            out = folder / f"{p.stem}-frame{i}.jpg"
            r = subprocess.run(ff + ["-ss", f"{vdur * f:.2f}", "-i", str(p), "-frames:v", "1", "-vf", "scale=768:-2", "-q:v", "4", str(out)], capture_output=True, timeout=60)
            if r.returncode == 0 and out.exists() and out.stat().st_size:
                imgs.append(out)
    if not text and not imgs:
        raise ValueError("تعذّر ذلك أسمع نص في هذا الملف")
    return (f"(تفريغ نص من {'فيديو' if imgs else 'تسجيل صوتي'}: {p.name})\n{text}" if text else ""), imgs, dur


def brain_src_step(bid: str, sid: str, step: str) -> None:
    def fn(d):
        for x in d.get("sources") or []:
            if x["id"] == sid:
                x["step"] = step
    update_brain(bid, fn)


def brain_fetch(url: str, dest: Path, limit: int = 40 * 1024 * 1024) -> bool:
    """تنزيل صورة أو فيديو من السوشيال (بحد أقصى للحجم)."""
    try:
        with httpx.stream("GET", url, timeout=60, follow_redirects=True, headers={"User-Agent": "Mozilla/5.0"}) as r:
            if r.status_code != 200:
                return False
            n = 0
            with dest.open("wb") as out:
                for chunk in r.iter_bytes(1 << 16):
                    n += len(chunk)
                    if n > limit:
                        break
                    out.write(chunk)
        return dest.stat().st_size > 1000
    except (httpx.HTTPError, OSError):
        dest.unlink(missing_ok=True)
        return False


def run_brain_social(bid: str, sid: str) -> None:
    """📱 حساب السوشيال ← العقل: السيرة والمعلومات والنيتش (اقتراحات توافق عليها)، الصور كل واحدة في مكانها (اقتراحات)،
    وتحليل المنشورات والمشاهدات وأحسن وأضعف الفيديوهات ← «نقاط يجب تتشتغل». كل هذا يُخصم من الرصيد على قدر الذي صُرف."""
    b = brain_row(bid)
    s = next(x for x in b.get("sources") or [] if x["id"] == sid)
    folder = brain_dir(bid) / "src"
    plat, handle = s["platform"], s["handle"]
    meter, calls, stt = {"usd": 0.0}, 0, 0.0
    brain_src_step(bid, sid, "يجلب الحساب والمنشورات")
    if atlas.mock_mode() or not rivals.live():
        if not atlas.mock_mode():
            raise ValueError(rivals.missing_msg() if os.environ.get("TENANT_ROLE") != "customer"
                             else "تحليل الحسابات غير متاح الآن. جرّب مرة أخرى بعد قليل")
        prof, items = brainsocial.mock_posts(plat, handle)
    else:
        prof, items = brainsocial.profile(plat, handle), brainsocial.posts(plat, handle)
        calls = 2
    if not items and not prof.get("bio"):
        raise ValueError("هذا الحساب فارغ أو خاص (private)")
    st = brainsocial.stats(items)
    by = {p["id"]: p for p in items}
    # 🎬 أحسن فيديوهين وأضعف واحد: الكلام اللي اتقال + ٤ لقطات من كل فيديو
    videos, frames = [], []
    for pid in [*st.get("best", [])[:2], *st.get("worst", [])[:1]]:
        p = by.get(pid)
        if not p or not p.get("video"):
            continue
        brain_src_step(bid, sid, f"يحلل فيديو ({len(videos) + 1}/3)")
        mp4 = folder / f"{sid}-v{len(videos)}.mp4"
        if not brain_fetch(p["video"], mp4):
            continue
        try:
            words = rivals.transcript(plat, p["url"]) if rivals.live() else ""
            calls += 1
            if not words:
                wav = folder / f"{sid}-v.wav"
                subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", str(mp4), "-vn", "-ac", "1", "-ar", "16000", str(wav)],
                               check=True, capture_output=True, timeout=300)
                d_ = probe_duration(wav)
                words = " ".join(str(w.get("w") or "") for w in atlas.transcribe(wav, d_)) if d_ > .5 else ""
                stt += d_
                wav.unlink(missing_ok=True)
            vd = probe_duration(mp4)
            for k, f in enumerate((.04, .3, .6, .9)):
                out = folder / f"{sid}-v{len(videos)}-{k}.jpg"
                r = subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-ss", f"{vd * f:.2f}", "-i", str(mp4), "-frames:v", "1",
                                    "-vf", "scale=512:-2", "-q:v", "5", str(out)], capture_output=True, timeout=60)
                if r.returncode == 0 and out.exists():
                    frames.append(out)
            videos.append({"id": pid, "rank": "best" if pid in st.get("best", []) else "worst", "views": p["views"], "seconds": round(vd, 1),
                           "transcript": words[:1500]})
        finally:
            mp4.unlink(missing_ok=True)
    # 🖼️ صور الأغلفة وصورة البروفايل: المخ هيقول كل واحدة مكانها فين في العقل
    brain_src_step(bid, sid, "ينزّل الصور")
    covers = []
    for i, url in enumerate([prof.get("avatar")] + [p.get("cover") for p in items[:8]]):
        if url:
            f = folder / f"{sid}-c{i}.jpg"
            if brain_fetch(url, f, 8 * 1024 * 1024):
                covers.append(f)
    brain_src_step(bid, sid, "يحلل الحساب")
    imgs = frames[:12] + covers[:9]
    prompt = brainsocial.analyze_prompt(prof, st, items, videos, len(imgs), az.brain_text(b), brainsrc.FIELDS)
    if atlas.mock_mode():
        out = brainsocial.mock_out()
    else:
        parts = [{"type": "text", "text": prompt + f"\nimages_from (أول صورة غلاف/بروفايل في الترتيب): {len(frames[:12])}"}]
        for im in imgs:
            parts.append({"type": "image_url", "image_url": {"url": data_url(model_image(im), "image/jpeg")}})
        out = ad_json(ad_media_chat([{"role": "user", "content": parts}], 16000, meter=meter), "تحليل الحساب")
    for f in frames:
        f.unlink(missing_ok=True)
    out = brainsocial.deid(out, items)
    fields = dict(out.get("fields") or {})
    items_p = brainsrc.to_pending({"fields": fields, "rules": [], "notes": out.get("notes") or [], "questions": []}, b, sid)
    # الصور: كل صورة ليها مكان (أو بتتشال لو مش مفيدة)
    keep = set()
    for im in out.get("images") or []:
        try:
            f = covers[int(im.get("i"))]
        except (TypeError, ValueError, IndexError):
            continue
        if im.get("kind") in brainsocial.KINDS:
            keep.add(f.name)
            items_p.append({"id": uuid.uuid4().hex[:10], "kind": "image", "target": im["kind"], "file": f.name, "title": brainsocial.KINDS[im["kind"]],
                            "summary": str(im.get("description") or "")[:300], "source": sid})
    for f in covers:
        if f.name not in keep:
            f.unlink(missing_ok=True)
    todos = brainsocial.clean_todos(out.get("todos"), sid)
    niche = str(out.get("niche") or "").strip()[:300]
    usd = meter["usd"] or wallet.est(chars=len(prompt) + 6000, images=len(imgs))
    cost = 0 if atlas.mock_mode() else wallet.charge(wallet.credits(usd + wallet.est(scrape=calls, stt_min=stt / 60)), f"العقل: تحليل حساب @{handle}", sid)

    def fn(d):
        d.setdefault("pending", []).extend(items_p)
        have = {t["title"] for t in d.get("todos") or []}
        d.setdefault("todos", []).extend(t for t in todos if t["title"] not in have)
        if niche and not str(d.get("niche") or "").strip():
            d["niche"] = niche
        d["social"] = {"platform": plat, "handle": handle, "followers": prof.get("followers"), "stats": st, "at": now()}
        for x in d.get("sources") or []:
            if x["id"] == sid:
                x.update(status="done", error=None, step=None, count=len(items_p) + len(todos), credits=cost)
    update_brain(bid, fn)


def run_brain_source(bid: str, sid: str) -> None:
    """يقرأ المصدر ويُخرج منه اقتراحات (خانات، قواعد، معرفة، أسئلة)."""
    try:
        b = brain_row(bid)
        s = next(x for x in b.get("sources") or [] if x["id"] == sid)
        folder = brain_dir(bid) / "src"
        if s["kind"] == "social":
            return run_brain_social(bid, sid)
        text, imgs, stt = "", [], 0.0
        if s["kind"] == "url":
            text = brainsrc.read_site(s["url"])
        elif s["kind"] == "text":
            text = s["text"]
        else:
            p = folder / s["file"]
            ext = p.suffix.lower()
            if ext == ".pdf":
                text, imgs = brainsrc.read_pdf(p, folder)
            elif ext == ".docx":
                text = brainsrc.read_docx(p)
            elif ext in brainsrc.IMG_EXT:
                imgs = [p]
            elif ext in brainsrc.AUDIO_EXT | brainsrc.VIDEO_EXT:
                text, imgs, stt = brain_av_text(p, folder)
            else:
                raw = p.read_text(encoding="utf-8", errors="ignore")
                text = brainsrc.html_text(raw)[0] if ext in (".html", ".htm") else raw
        if not text.strip() and not imgs:
            raise ValueError("هذا المصدر فارغ أو غير مقروء")
        if atlas.mock_mode():
            out = brainsrc.mock_out(s["name"])
        else:
            parts = [{"type": "text", "text": brainsrc.extract_prompt(az.brain_text(b), s["name"], s.get("note", ""), text, len(imgs))}]
            for im in imgs[:8]:
                parts.append({"type": "image_url", "image_url": {"url": data_url(model_image(im), "image/jpeg")}})
            out = ad_json(ad_media_chat([{"role": "user", "content": parts}], 16000), "قراءة المصدر")
        items = brainsrc.to_pending(out, b, sid)
        # 💳 الخصم بعد ما القراية تنجح: الكلام اللي دخل الموديل والصور ودقايق التفريغ
        cost = 0 if atlas.mock_mode() else wallet.charge(wallet.credits(wallet.est(chars=len(text) + 6000, images=min(8, len(imgs)), stt_min=stt / 60)), f"العقل: قراءة «{s['name']}»", sid)
        def fn(d):
            d.setdefault("pending", []).extend(items)
            for x in d.get("sources") or []:
                if x["id"] == sid:
                    x.update(status="done", error=None, count=len(items), credits=cost)
        update_brain(bid, fn)
    except Exception as exc:  # noqa: BLE001
        msg = str(getattr(exc, "detail", None) or exc)[:300]
        def fail(d):
            for x in d.get("sources") or []:
                if x["id"] == sid:
                    x.update(status="failed", error=msg)
        try:
            update_brain(bid, fail)
        except HTTPException:
            pass


@app.delete("/api/ad-brains/{bid}/sources/{sid}")
def delete_brain_source(bid: str, sid: str):
    def fn(d):
        s = next((x for x in d.get("sources") or [] if x["id"] == sid), None)
        if s and s.get("file"):
            (brain_dir(bid) / "src" / Path(s["file"]).name).unlink(missing_ok=True)
        d["sources"] = [x for x in d.get("sources") or [] if x["id"] != sid]
        d["pending"] = [x for x in d.get("pending") or [] if x.get("source") != sid]
    update_brain(bid, fn)
    return brain_to_dict(brain_row(bid))


class PendingIn(BaseModel):
    value: str | None = None
    title: str | None = None
    target: str | None = None   # الصور: تتحط في أنهي خانة (لو غيّرتها)


@app.post("/api/ad-brains/{bid}/pending/{pid}/approve")
def approve_brain_pending(bid: str, pid: str, body: PendingIn):
    """موافقة على اقتراح (بعد تعديله إذا حبيت): الخانة تُكتب، والقاعدة تُضاف، والمعرفة تدخل العقل."""
    def fn(d):
        it = next((x for x in d.get("pending") or [] if x["id"] == pid), None)
        if it is None:
            raise HTTPException(404, "هذا الاقتراح غير موجود")
        val = (body.value if body.value is not None else it.get("value") or "").strip()
        if it["kind"] == "image":   # صورة من الحساب ← مكانها في صور البراند
            src, tgt = brain_dir(bid) / "src" / Path(it["file"]).name, body.target or it.get("target")
            if src.exists() and tgt in BRAIN_KINDS:
                name = f"{tgt[:-1]}_{uuid.uuid4().hex[:8]}{src.suffix}"
                shutil.move(str(src), brain_dir(bid) / name)
                d.setdefault(tgt, []).append({"file": name, "name": (body.title or it.get("title") or "")[:60], "description": val or it.get("summary", "")})
        elif it["kind"] == "field":
            d[it["field"]] = val[:8000]
            if it["field"] in ("palette", "typography") and it["field"] not in d.setdefault("edited", []):
                d["edited"].append(it["field"])
        elif it["kind"] == "rule":
            rules = [r for r in str(d.get("rules") or "").split("\n") if r.strip()]
            d["rules"] = "\n".join([*rules, val])[:8000]
        else:   # معلومة، أو إجابة على سؤال
            if it["kind"] == "question" and not val:
                raise HTTPException(400, "اكتب الإجابة أولًا")
            d.setdefault("notes", []).append({"id": it["id"], "section": it.get("section") or "other",
                                              "title": (body.title or it.get("title") or "").strip()[:120],
                                              "summary": it.get("summary", "") if it["kind"] == "note" else val[:300],
                                              "body": val[:6000] if it["kind"] == "note" else "", "source": it.get("source")})
        d["pending"] = [x for x in d["pending"] if x["id"] != pid]
    old = brain_row(bid) or {}
    update_brain(bid, fn)
    new = brain_row(bid) or {}
    seasons_if_changed(bid, old, new)
    return brain_to_dict(new)


@app.delete("/api/ad-brains/{bid}/pending/{pid}")
def reject_brain_pending(bid: str, pid: str):
    def fn(d):
        for x in d.get("pending") or []:
            if x["id"] == pid and x.get("kind") == "image":
                (brain_dir(bid) / "src" / Path(x["file"]).name).unlink(missing_ok=True)
        d["pending"] = [x for x in d.get("pending") or [] if x["id"] != pid]
    update_brain(bid, fn)
    return brain_to_dict(brain_row(bid))


