# 🎙️ خطوة الصوت: مين اللي بيتكلم (معلّق أو بطل من الأبطال أو من غير صوت)، وبأي لهجة، وبأي صوت
LANG_HINTS = (("نجد|رياض|القصيم", "ar-sa-najdi"), ("حجاز|جدة|جده|مكة|مكه|المدينة", "ar-sa-hijazi"), ("سعود", "ar-sa-najdi"),
              ("إمارات|امارات|دبي|أبوظبي|ابوظبي", "ar-ae"), ("كويت", "ar-kw"), ("قطر", "ar-qa"), ("بحرين", "ar-bh"), ("عمان|عُمان|مسقط", "ar-om"),
              ("خليج", "ar-gulf"), ("مصر|مصري|القاهرة", "ar-eg-cairo"), ("شام|سوري|لبنان|أردن|اردن|فلسطين", "ar-levant"), ("عراق", "ar-iq"),
              ("سودان", "ar-sd"), ("مغرب|دارجة", "ar-ma"), ("جزائر", "ar-dz"), ("تونس", "ar-tn"), ("فصحى|فصحي", "ar-msa"),
              (r"english|إنجليز|انجليز", "en"))


def flow_lang_guess(d: dict) -> str:
    """لهجة العلامة من عقلها (اللغة ثم السوق)، وإلا الفصحى."""
    return dialect.code(flow_brain(d) or {}, brand_settings().get("language") or "")


@app.get("/api/flows/{fid}/voice-options")
def flow_voice_options(fid: str):
    d = flow_load(fid)
    fasih_sync()
    speakers = [{"id": "narrator", "name": "معلّق من خارج الكادر", "about": "صوت يحكي على الصور"}]
    speakers += [{"id": c["id"], "name": c["name"], "about": "البطل نفسه هو ما يتكلم", "image_url": c.get("image_url")} for c in d.get("cast") or []]
    speakers.append({"id": "none", "name": "بدون صوت", "about": "موسيقى ونص مكتوب فقط"})
    dialects = [{"id": k, "label": v["label"], "group": v["group"]} for k, v in dub.DIALECTS.items()]
    rows = (d.get("scenario") or {}).get("scenes") or []
    say = "\n".join(str(r.get("say") or "").strip() for r in rows if str(r.get("say") or "").strip())
    say = say or "ا" * 420   # النص لسه مش جاهز: تقدير لفيديو ٣٠ ثانية، عشان الرقم يظهر على الزرار دايمًا
    voices = {k: [{"id": x, "label": dub.VOICES[x]["label"], "gender": dub.VOICES[x].get("gender") or "", "pts": wallet.credits(voice_usd(x, say)),
                   "sample": dub.VOICES[x].get("sample") or (f"/media/vsamples/{x}.mp3" if (VSAMPLE_DIR / f"{x}.mp3").exists() else "")}
                  for x in v["voices"]] for k, v in dub.DIALECTS.items()}
    vo = d.get("vo") or {}
    lang = d.get("lang") if d.get("lang") in dub.DIALECTS else vo.get("lang") if vo.get("lang") in dub.DIALECTS else flow_lang_guess(d)
    voice = vo.get("voice") if vo.get("voice") in dub.DIALECTS[lang]["voices"] else dub.DIALECTS[lang]["voices"][0]
    return {"speakers": speakers, "dialects": dialects, "voices": voices, "fasih": bool(fasih.api_key() or atlas.mock_mode()), "balance": wallet.balance(),
            "pick": {"speaker": vo.get("speaker") or "narrator", "lang": lang, "voice": voice}}


class FlowVoiceIn(BaseModel):
    speaker: str = "narrator"
    lang: str = "ar-eg-cairo"
    voice: str = ""


def flow_guide(tpl: dict) -> dict | None:
    """🧭 لوحة قالب الذكاء الاصطناعي: نصايح الفكرة والسيناريو، الصور المرجعية، والشكل والطول والمقاس الذي ينفعون."""
    kind = tpl.get("kind")
    if kind not in ("scene", "lab", "ad", "still"):
        return None
    g = tplguide.guide(tpl["id"], kind) or {"idea": "", "scen": "", "refs": [], "lens": [20, 30, 40, 60], "len": 30, "ratios": list(tplguide.RATIOS)}
    if kind == "lab":
        g["ratios"] = list(tplguide.RATIOS)
    g["looks"] = []
    if kind in ("scene", "lab"):
        try:
            g["looks"] = [{"id": v[0], "label": v[1]} for v in scene_cfg_for(tpl_load(tpl["id"])).get("variants") or []]
        except HTTPException:
            pass
    return g


class FlowTsetIn(BaseModel):
    length: int = 0
    ratio: str = ""
    look: str = ""


@app.post("/api/flows/{fid}/tset")
def flow_tset(fid: str, body: FlowTsetIn):
    """إعدادات القالب: الشكل (من أشكال الأسلوب)، والطول، والمقاس. ما غير متاح للقالب يترمي."""
    d = flow_load(fid)
    g = flow_guide(d["template"]) or {}
    ts = {"length": body.length if body.length in (g.get("lens") or []) else g.get("len") or 0,
          "ratio": body.ratio if body.ratio in (g.get("ratios") or []) else "",
          "look": body.look if body.look in [x["id"] for x in g.get("looks") or []] else ""}
    return flow_to_dict(fid, flow_update(fid, lambda x: x.update(tset=ts)))


@app.post("/api/flows/{fid}/voice")
def flow_voice(fid: str, body: FlowVoiceIn):
    d = flow_load(fid)
    names = {"narrator": "معلّق", "none": ""} | {c["id"]: c["name"] for c in d.get("cast") or []}
    if body.speaker not in names:
        raise HTTPException(400, "اختر من الذي يتكلم")
    if body.lang not in dub.DIALECTS:
        raise HTTPException(400, "هذه اللهجة غير موجودة")
    voice = body.voice if body.voice in dub.DIALECTS[body.lang]["voices"] else dub.DIALECTS[body.lang]["voices"][0]
    vo = {"speaker": body.speaker, "speaker_name": names[body.speaker], "lang": body.lang, "voice": voice, "on": body.speaker != "none"}
    if d["template"].get("kind") == "motion":
        flow_update(fid, lambda x: x.update(vo=vo, lang=body.lang, vo_track=None, stage="voice" if vo["on"] else "panel"))
        if vo["on"]:
            flow_job(fid, "vo", lambda: flow_make_vo(fid))
        return flow_to_dict(fid, flow_load(fid))
    return flow_to_dict(fid, flow_update(fid, lambda x: x.update(vo=vo, lang=body.lang, stage="assets")))


