def vlab_texts() -> dict:
    """قطعة كل لهجة: تعديل صاحب المنصة لو موجود، وإلا القطعة الأصلية."""
    try:
        saved = json.loads(VLAB_TEXT_FILE.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        saved = {}
    return {k: (saved.get(k) or VLAB_TEXT.get(k) or VSAMPLE_TEXT.get(k, VSAMPLE_GULF)) for k, v in dub.DIALECTS.items() if v["group"] == "ar"}


SILMA_DIALECTS = ("ar-msa", "ar-gulf")   # SILMA عنده فصحى وسعودي بس (والخليجي العام قريب من السعودي)


def vlab_support(dialect: str) -> dict:
    """المزوّد بيدعم اللهجة دي؟ فصيح ومنصت: لو عندهم أصوات فيها. SILMA: فصحى وسعودي وخليجي عام. الباقي متعدد اللغات وبيقرا أي نص."""
    dv = dub.DIALECTS[dialect]["voices"]
    def has(p):
        return any(dub.VOICES[v].get("provider") == p and dub.VOICES[v].get("dialect") == dialect for v in dub.VOICES) or any(dub.VOICES[v]["provider"] == p for v in dv)
    return {"fasih": has("fasih"), "munsit": has("munsit"), "eleven_atlas": True, "eleven": True, "minimax": True,
            "silma": dialect.startswith("ar-sa") or dialect in SILMA_DIALECTS}


def vlab_owner() -> None:
    if not wallet.free():
        raise HTTPException(403, "مختبر الأصوات لصاحب المنصة بس")


def vlab_ready() -> dict:
    mm_atlas = [m for m in auto_voice_models() if "minimax" in m["model"].lower() and m["mode"] == "tts" and m.get("voices")]
    return {"fasih": bool(fasih.api_key()), "munsit": bool(munsit.api_key()), "eleven_atlas": bool(atlas.api_key()),
            "eleven": bool(voicelab.eleven_key()), "minimax": bool(voicelab.minimax_key() or mm_atlas), "silma": bool(voicelab.silma_key())}


def vlab_jobs(dialect: str, provs: list[str]) -> list[dict]:
    """كل صوت هيتجرّب: {provider, voice, label} — صوتين لكل مزوّد (راجل وست لو موجودين)."""
    out = []
    dv = dub.DIALECTS[dialect]["voices"]
    for p in provs:
        if p in ("fasih", "munsit"):
            vs = [v for v in dub.VOICES if dub.VOICES[v].get("provider") == p and dub.VOICES[v].get("dialect") == dialect] or [v for v in dv if dub.VOICES[v]["provider"] == p]
            pick = [next((v for v in vs if dub.VOICES[v].get("gender") == g), None) for g in ("male", "female")]
            pick = [v for v in pick if v] or vs[:2]
            out += [{"provider": p, "voice": v, "label": dub.VOICES[v]["label"]} for v in pick] or [
                {"provider": p, "voice": "", "label": "—", "skip": f"{VLAB_PROV[p]} مالوش أصوات في اللهجة دي"}]
        elif p == "eleven_atlas":
            out += [{"provider": p, "voice": v, "label": dub.VOICES[v]["label"]} for v in list(dub.ELEVEN)[:2]]
        elif p == "eleven" and voicelab.eleven_key():
            vs = [v for v in voicelab.eleven_voices() if v["cat"] == "premade"] or voicelab.eleven_voices()
            pick = [next((v for v in vs if v["gender"] == g), None) for g in ("male", "female")]
            out += [{"provider": p, "voice": v["id"], "label": v["name"]} for v in pick if v]
        elif p == "minimax":
            if voicelab.minimax_key():
                out += [{"provider": p, "voice": v["id"], "label": v["name"]} for v in voicelab.minimax_voices()[:2]]
            else:
                m = next((m for m in auto_voice_models() if "minimax" in m["model"].lower() and m["mode"] == "tts" and m.get("voices")), None)
                if m:
                    vs = sorted(m["voices"], key=lambda v: "arab" not in v.lower())
                    out += [{"provider": p, "voice": v, "label": v, "atlas": m["model"], "vf": m.get("voice_field"), "tf": m.get("text_field")} for v in vs[:2]]
        elif p == "silma":
            model = voicelab.SILMA_MODELS["ksa"] if dialect.startswith("ar-sa") or dialect == "ar-gulf" else voicelab.SILMA_MODELS["msa"]
            note = "" if dialect.startswith("ar-sa") or dialect in ("ar-msa", "ar-gulf") else " · SILMA عنده فصحى وسعودي بس"
            out += [{"provider": p, "voice": v, "label": voicelab.SILMA_VOICES[v] + note, "model": model} for v in ("sultan", "sarah")]
    return out


def vlab_say(j: dict, text: str, dialect: str, dest: Path) -> Path:
    """صوت واحد ← mp3."""
    raw = dest.with_suffix(".src")
    p = j["provider"]
    if atlas.mock_mode():
        subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-f", "lavfi", "-i",
                        f"sine=frequency={300 + 40 * (hash(p) % 8)}:duration={max(1.5, len(text) / dub.CHARS_PER_SEC):.2f}", "-f", "wav", str(raw)],
                       check=True, capture_output=True, timeout=60)
    elif p in ("fasih", "munsit", "eleven_atlas"):
        vo_say(text, j["voice"], dialect, raw.with_suffix(".wav"))
        raw = raw.with_suffix(".wav")
    elif p == "eleven":
        voicelab.eleven_say(text, j["voice"], raw)
    elif p == "minimax" and j.get("atlas"):
        body = {"model": j["atlas"], j.get("tf") or "text": text}
        if j.get("vf"):
            body[j["vf"]] = j["voice"]
        atlas.download(atlas.run_model("Audio", body, "مختبر الأصوات", max_seconds=300, interval=2), raw)
    elif p == "minimax":
        voicelab.minimax_say(text, j["voice"], raw)
    elif p == "silma":
        voicelab.silma_say(text, j["voice"], j["model"], raw)
    else:
        raise voicelab.LabError("مزوّد مش معروف")
    subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", str(raw), "-c:a", "libmp3lame", "-b:a", "128k", str(dest)],
                   check=True, capture_output=True, timeout=120)
    raw.unlink(missing_ok=True)
    return dest


def vlab_save(rid: str, fn) -> dict:
    with VLAB_LOCK:
        f = VLAB_DIR / Path(rid).name / "run.json"
        d = json.loads(f.read_text(encoding="utf-8"))
        fn(d)
        f.write_text(json.dumps(d, ensure_ascii=False), encoding="utf-8")
    return d


# حد الطلبات في نفس الوقت لكل مزوّد (منصت و SILMA بيقبلوا طلب واحد بس في المرة، والباقي بيرجع 429)
VLAB_SLOTS = {"munsit": threading.Semaphore(1), "silma": threading.Semaphore(1)}
VLAB_SLOT_DEFAULT = 2


def vlab_slot(provider: str) -> threading.Semaphore:
    with VLAB_LOCK:
        return VLAB_SLOTS.setdefault(provider, threading.Semaphore(VLAB_SLOT_DEFAULT))


def vlab_busy(msg: str) -> bool:
    m = msg.lower()
    return "429" in m or "concurren" in m or "rate limit" in m or "too many" in m


def vlab_nice_error(msg: str, provider: str) -> str:
    m = msg.lower()
    if "insufficient balance" in m or "balance not enough" in m:
        return f"رصيد {VLAB_PROV.get(provider, provider)} نفد: اشحن الحساب من موقعهم ثم أعد المحاولة"
    if vlab_busy(msg):
        return f"{VLAB_PROV.get(provider, provider)} مشغول الآن (الحد الأقصى للطلبات المتزامنة). أعد المحاولة بعد قليل"
    return msg


def run_vlab(rid: str, only: set | None = None) -> None:
    d = vlab_save(rid, lambda d: None)
    folder = VLAB_DIR / rid

    def one(i: int, c: dict) -> None:
        t0 = time.time()
        if c.get("skip"):
            return vlab_save(rid, lambda x: x["clips"][i].update(status="failed", error=c["skip"]))
        try:
            if d["kind"] == "clone":
                sample = folder / d["sample"]
                if c["provider"] == "eleven":
                    vid = voicelab.eleven_clone(sample, f"lab-{rid}")
                    try:
                        voicelab.eleven_say(d["text"], vid, folder / f"{i}.src")
                    finally:
                        voicelab.eleven_delete(vid)
                else:
                    vid = voicelab.minimax_clone(sample)
                    voicelab.minimax_say(d["text"], vid, folder / f"{i}.src")
                subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", str(folder / f"{i}.src"), "-c:a", "libmp3lame", "-b:a", "128k",
                                str(folder / f"{i}.mp3")], check=True, capture_output=True, timeout=120)
                (folder / f"{i}.src").unlink(missing_ok=True)
            else:
                # طلب واحد في المرة للمزوّد اللي عنده حد، ولو رجع «مشغول» نستنى ونعيد (لحد ٣ مرات)
                for attempt in range(4):
                    try:
                        with vlab_slot(c["provider"]):
                            t0 = time.time()
                            vlab_say(c, d["text"], d["dialect"], folder / f"{i}.mp3")
                        break
                    except Exception as e:  # noqa: BLE001
                        if attempt == 3 or not vlab_busy(str(getattr(e, "detail", None) or e)):
                            raise
                        time.sleep(4 * (attempt + 1))
            upd = {"file": f"{i}.mp3", "status": "done", "sec": round(time.time() - t0, 1)}
        except Exception as e:  # noqa: BLE001
            upd = {"status": "failed", "error": vlab_nice_error(str(getattr(e, "detail", None) or e), c["provider"])[:240]}
        vlab_save(rid, lambda x: x["clips"][i].update(upd))

    threads = [threading.Thread(target=one, args=(i, c), daemon=True) for i, c in enumerate(d["clips"]) if only is None or i in only]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=600)
    vlab_save(rid, lambda x: x.update(status="done"))


def vlab_out(d: dict) -> dict:
    return {**d, "clips": [{**c, "url": f"/media/voicelab/{d['id']}/{c['file']}" if c.get("file") else None} for c in d["clips"]]}


def vlab_runs() -> list[dict]:
    out = []
    for f in VLAB_DIR.glob("*/run.json"):
        try:
            out.append(json.loads(f.read_text(encoding="utf-8")))
        except ValueError:
            continue
    return sorted(out, key=lambda d: d.get("at") or 0, reverse=True)


@app.get("/api/voicelab")
def voicelab_get():
    vlab_owner()
    runs = vlab_runs()
    score: dict = {}   # النتيجة: متوسط نجوم كل مزوّد في كل لهجة (والكلون لوحده)
    for d in runs:
        for c in d["clips"]:
            if c.get("score"):
                k = (d["dialect"] if d["kind"] == "tts" else d["kind"], c["provider"])
                score.setdefault(k, []).append(c["score"])
    table = [{"dialect": k[0], "provider": k[1], "avg": round(sum(v) / len(v), 2), "n": len(v)} for k, v in score.items()]
    return {"providers": VLAB_PROV, "labels": {**VLAB_PROV, **VLAB_OTHER}, "ready": vlab_ready(),
            "dialects": {k: v["label"] for k, v in dub.DIALECTS.items() if v["group"] == "ar"},
            "samples": vlab_texts(), "defaults": {k: VLAB_TEXT.get(k, "") for k in dub.DIALECTS if dub.DIALECTS[k]["group"] == "ar"},
            "support": {k: vlab_support(k) for k, v in dub.DIALECTS.items() if v["group"] == "ar"},
            "runs": [vlab_out(d) for d in runs[:30]], "table": sorted(table, key=lambda r: (r["dialect"], -r["avg"])), "approved": {k: v for k, v in dub.APPROVED.items()}}


class VLabIn(BaseModel):
    dialect: str = "ar-sa-najdi"
    text: str = ""
    providers: list[str] = []


@app.post("/api/voicelab/run")
def voicelab_run(body: VLabIn):
    vlab_owner()
    if body.dialect not in dub.DIALECTS:
        raise HTTPException(400, "هذه اللهجة غير موجودة")
    text = (body.text or "").strip()[:600] or vlab_texts()[body.dialect]
    ready, sup = vlab_ready(), vlab_support(body.dialect)
    provs = [p for p in body.providers if p in VLAB_PROV and (ready.get(p) or atlas.mock_mode())] or [p for p, ok in ready.items() if ok]
    provs = [p for p in provs if sup.get(p)]   # المزوّد اللي مبيدعمش اللهجة مقفول فيها
    if not provs:
        raise HTTPException(400, "لا يوجد مزوّد ممن اخترتهم يدعم هذه اللهجة")
    try:
        jobs = vlab_jobs(body.dialect, provs)
    except voicelab.LabError as e:
        raise HTTPException(400, str(e))
    if not jobs:
        raise HTTPException(400, "لا يوجد مزوّد جاهز: أضف مفاتيح المزوّدين في الإعدادات أولًا")
    rid = uuid.uuid4().hex[:10]
    (VLAB_DIR / rid).mkdir(parents=True, exist_ok=True)
    d = {"id": rid, "kind": "tts", "dialect": body.dialect, "text": text, "at": time.time(), "status": "working",
         "clips": [{**j, "provider_label": VLAB_PROV[j["provider"]], "status": "working", "score": 0} for j in jobs]}
    (VLAB_DIR / rid / "run.json").write_text(json.dumps(d, ensure_ascii=False), encoding="utf-8")
    threading.Thread(target=run_vlab, args=(rid,), daemon=True).start()
    return vlab_out(d)


@app.post("/api/voicelab/clone")
def voicelab_clone(text: str = Form(""), dialect: str = Form("ar-sa-najdi"), file: UploadFile = File(...)):
    """نفس عينة الصوت ← كلون بـ ElevenLabs و MiniMax ← نفس الجملة بالصوتين."""
    vlab_owner()
    provs = [p for p in ("eleven", "minimax") if (voicelab.eleven_key() if p == "eleven" else voicelab.minimax_key()) or atlas.mock_mode()]
    if not provs:
        raise HTTPException(400, "الكلون يحتاج مفتاح ElevenLabs أو MiniMax المباشر في الإعدادات")
    rid = uuid.uuid4().hex[:10]
    folder = VLAB_DIR / rid
    folder.mkdir(parents=True, exist_ok=True)
    src = folder / f"sample-src{Path(file.filename or 'a.mp3').suffix.lower()[:6] or '.mp3'}"
    with src.open("wb") as f:
        shutil.copyfileobj(file.file, f)
    try:   # mp3 أحادي، أقصى دقيقتين (الاتنين بيقبلوه)
        subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", str(src), "-t", "120", "-ac", "1", "-ar", "44100", "-c:a", "libmp3lame",
                        "-b:a", "160k", str(folder / "sample.mp3")], check=True, capture_output=True, timeout=120)
    except subprocess.SubprocessError:
        shutil.rmtree(folder, ignore_errors=True)
        raise HTTPException(400, "هذا الملف ليس صوتًا سليمًا")
    finally:
        src.unlink(missing_ok=True)
    if probe_duration(folder / "sample.mp3") < 8:
        shutil.rmtree(folder, ignore_errors=True)
        raise HTTPException(400, "يجب أن تكون العينة ١٠ ثوانٍ على الأقل (والأفضل من ٣٠ ثانية إلى دقيقة كلام واضح)")
    text = text.strip()[:600] or vlab_texts().get(dialect, VSAMPLE_GULF)
    d = {"id": rid, "kind": "clone", "dialect": dialect if dialect in dub.DIALECTS else "ar-msa", "text": text, "at": time.time(), "status": "working", "sample": "sample.mp3",
         "clips": [{"provider": p, "provider_label": VLAB_PROV[p], "voice": "clone", "label": "كلون من العينة", "status": "working", "score": 0} for p in provs]}
    (folder / "run.json").write_text(json.dumps(d, ensure_ascii=False), encoding="utf-8")
    if atlas.mock_mode():   # تجربة من غير مفاتيح: صوت تجريبي بدل الكلون
        for i, c in enumerate(d["clips"]):
            c.update(provider="eleven_atlas" if c["provider"] == "eleven" else c["provider"], voice="eleven_liam")
        d["kind"] = "tts"
        (folder / "run.json").write_text(json.dumps(d, ensure_ascii=False), encoding="utf-8")
    threading.Thread(target=run_vlab, args=(rid,), daemon=True).start()
    return vlab_out(d)


def run_vlab_dub(rid: str) -> None:
    """دبلجة ElevenLabs للفيديو: نبدأها ونستنى لحد ما تخلص (لحد ٢٥ دقيقة)، والنتيجة فيديو بنفس صوت المتكلم."""
    folder = VLAB_DIR / rid
    d = vlab_save(rid, lambda d: None)
    t0 = time.time()
    try:
        if atlas.mock_mode():
            shutil.copy(folder / d["source"], folder / "0.mp4")
        else:
            dub_id = voicelab.eleven_dub_start(folder / d["source"])
            while True:
                time.sleep(8)
                st = voicelab.eleven_dub_status(dub_id)
                if st.get("status") == "dubbed":
                    break
                if st.get("status") in ("failed", "error") or time.time() - t0 > 1500:
                    raise voicelab.LabError(f"ElevenLabs: {st.get('error') or 'لم تكتمل الدبلجة'}")
            voicelab.eleven_dub_get(dub_id, "ar", folder / "0.mp4")
        upd = {"file": "0.mp4", "status": "done", "sec": round(time.time() - t0, 1)}
    except Exception as e:  # noqa: BLE001
        upd = {"status": "failed", "error": str(getattr(e, "detail", None) or e)[:240]}
    vlab_save(rid, lambda x: (x["clips"][0].update(upd), x.update(status="done")))   # نسختنا بفصيح بيكمّلها العميل بإيده


@app.post("/api/voicelab/dub")
def voicelab_dub(file: UploadFile = File(...)):
    """🌍 نفس الفيديو: دبلجة ElevenLabs (صوت المتكلم نفسه) هنا، ونسخة دبلجتنا بفصيح بتتفتح في «الترجمة والدبلجة» تكمّلها وتقارن."""
    vlab_owner()
    if not (voicelab.eleven_key() or atlas.mock_mode()):
        raise HTTPException(400, "دبلجة ElevenLabs تحتاج مفتاح ElevenLabs المباشر (بصلاحية Dubbing) في الإعدادات")
    rid = uuid.uuid4().hex[:10]
    folder = VLAB_DIR / rid
    folder.mkdir(parents=True, exist_ok=True)
    name = save_upload(file, VIDEO_EXTENSIONS, folder, "src")
    if probe_duration(folder / name) > 300:
        shutil.rmtree(folder, ignore_errors=True)
        raise HTTPException(400, "للتجربة: فيديو حتى ٥ دقائق (ElevenLabs يحاسب بالدقيقة)")
    tmp = TMP_DIR / f"vlabdub_{rid}{Path(name).suffix}"
    shutil.copy(folder / name, tmp)
    ours = dub_create(tmp, f"🎧 مقارنة: {Path(file.filename or 'فيديو').stem}"[:80])
    d = {"id": rid, "kind": "dub", "dialect": "ar-msa", "text": f"دبلجة فيديو «{Path(file.filename or 'فيديو').stem}»", "at": time.time(), "status": "working",
         "source": name, "ours": ours.get("id"),
         "clips": [{"provider": "eleven_dub", "provider_label": "ElevenLabs (دبلجة بصوت المتكلم)", "voice": "", "label": "عربي (دون اختيار لهجة)", "status": "working", "score": 0},
                   {"provider": "fasih_dub", "provider_label": "دبلجتنا بالأصوات العربية", "voice": "", "status": "manual", "score": 0,
                    "label": f"أكملها في «الترجمة والدبلجة» (اسمها «🎧 مقارنة: {Path(file.filename or 'فيديو').stem[:40]}») واختر اللهجة، ثم قيّمها هنا"}]}
    (folder / "run.json").write_text(json.dumps(d, ensure_ascii=False), encoding="utf-8")
    threading.Thread(target=run_vlab_dub, args=(rid,), daemon=True).start()
    return vlab_out(d)


class VLabTextIn(BaseModel):
    dialect: str
    text: str = ""


@app.post("/api/voicelab/texts")
def voicelab_text(body: VLabTextIn):
    """حفظ قطعة لهجة بعد المراجعة (نص فاضي = يرجع للأصلي)."""
    vlab_owner()
    if body.dialect not in dub.DIALECTS:
        raise HTTPException(400, "هذه اللهجة غير موجودة")
    with VLAB_LOCK:
        try:
            saved = json.loads(VLAB_TEXT_FILE.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            saved = {}
        t = body.text.strip()[:600]
        if t and t != VLAB_TEXT.get(body.dialect):
            saved[body.dialect] = t
        else:
            saved.pop(body.dialect, None)
        VLAB_TEXT_FILE.write_text(json.dumps(saved, ensure_ascii=False), encoding="utf-8")
    return {"dialect": body.dialect, "text": vlab_texts()[body.dialect]}


class VLabRateIn(BaseModel):
    clip: int
    score: int = 0


@app.post("/api/voicelab/runs/{rid}/rate")
def voicelab_rate(rid: str, body: VLabRateIn):
    vlab_owner()
    if not (VLAB_DIR / Path(rid).name / "run.json").exists():
        raise HTTPException(404, "هذه التجربة غير موجودة")
    return vlab_out(vlab_save(rid, lambda d: d["clips"][body.clip].update(score=max(0, min(5, body.score))) if 0 <= body.clip < len(d["clips"]) else None))


class VLabNoteIn(BaseModel):
    clip: int
    note: str = ""


@app.post("/api/voicelab/runs/{rid}/note")
def voicelab_note(rid: str, body: VLabNoteIn):
    """📝 ملاحظة صاحب المنصة على صوت بعينه (بتطلع في تقرير النتايج جنب النجوم)."""
    vlab_owner()
    if not (VLAB_DIR / Path(rid).name / "run.json").exists():
        raise HTTPException(404, "هذه التجربة غير موجودة")
    note = body.note.strip()[:2000]
    return vlab_out(vlab_save(rid, lambda d: d["clips"][body.clip].update(note=note) if 0 <= body.clip < len(d["clips"]) else None))


VLAB_KINDS = {"clone": "كلون صوت", "dub": "دبلجة فيديو", "tts": "مقارنة لهجة"}


def vlab_code(rid: str, i: int) -> str:
    """رقم ثابت لكل صوت (بيطلع في التقرير وفي اسم الملف): المقيّم يكتب الرقم، وإحنا نعرف الصوت مين."""
    return f"{rid[:4].upper()}-{i + 1}"


def vlab_retryable(c: dict) -> bool:
    return c.get("status") == "failed" and not c.get("skip")


def vlab_report_text(dialect: str = "") -> str:
    dl = {k: v["label"] for k, v in dub.DIALECTS.items()}
    runs = [d for d in vlab_runs() if not dialect or d["dialect"] == dialect]
    clips = [c for d in runs for c in d["clips"]]
    failed = [(d, i, c) for d in runs for i, c in enumerate(d["clips"]) if c.get("status") == "failed"]
    lines = [f"# نتائج مختبر الأصوات ({time.strftime('%Y-%m-%d %H:%M')})", "",
             f"الأصوات: {len(clips)} · نجحت: {sum(c.get('status') == 'done' for c in clips)} · فشلت: {len(failed)} · مُقيّمة: {sum(bool(c.get('score')) for c in clips)}"
             + f" · عليها ملاحظات: {sum(bool((c.get('note') or '').strip()) for c in clips)}", ""]
    for d in runs:
        lines += [f"## {VLAB_KINDS.get(d['kind'], d['kind'])} · {dl.get(d['dialect'], d['dialect'])} · {time.strftime('%Y-%m-%d', time.localtime(d.get('at') or 0))}",
                  f"النص: {d.get('text', '')}"]
        for i, c in enumerate(d["clips"]):
            sc = int(c.get("score") or 0)
            state = (f"❌ لم يُنشأ: {c.get('error') or 'خطأ غير معروف'}" if c.get("status") == "failed"
                     else "⏳ جارٍ التوليد" if c.get("status") == "working" else ("★" * sc + "☆" * (5 - sc)) if sc else "بدون تقييم")
            lines.append(f"- [{vlab_code(d['id'], i)}] {c.get('provider_label', c.get('provider'))} · {c.get('label') or c.get('voice') or ''} · {state}")
            if (c.get("note") or "").strip():
                lines.append(f"  ملاحظة: {c['note'].strip()}")
        lines.append("")
    if failed:
        lines += ["## الأصوات التي لم تُنشأ (تُعاد من زر «أعد ما فشل»)"]
        lines += [f"- [{vlab_code(d['id'], i)}] {dl.get(d['dialect'], d['dialect'])} · {c.get('provider_label')} · {c.get('label') or ''}: {c.get('error') or ''}"
                  + (" (المزوّد لا يدعم اللهجة، فلن تُعاد)" if c.get("skip") else "") for d, i, c in failed]
    if not runs:
        lines.append("لا توجد تجارب بعد.")
    return "\n".join(lines)


@app.get("/api/voicelab/report")
def voicelab_report(dialect: str = ""):
    """📋 كل التجارب بالنجوم والملاحظات واللي فشل وسببه، في نص واحد يتنسخ ويتبعت."""
    vlab_owner()
    return {"text": vlab_report_text(dialect)}


@app.get("/api/voicelab/export")
def voicelab_export(dialect: str = "", blind: bool = False):
    """⬇️ كل الأصوات في ملف zip، مجلد لكل لهجة.
    عادي: اسم الملف فيه الرقم والمزوّد والصوت، ومعاه التقرير بنجومك وملاحظاتك واللي فشل.
    للمقيّمين (blind): اسم الملف الرقم بس (من غير أسامي المزودين، عشان التقييم يبقى منصف)، ومعاه ورقة تقييم يملاها أهل اللهجة."""
    vlab_owner()
    dl = {k: v["label"].split(" ", 1)[-1] for k, v in dub.DIALECTS.items()}
    safe = lambda t: re.sub(r'[\\/:*?"<>|]+', "-", str(t or "")).strip()[:60]
    runs = [d for d in vlab_runs() if not dialect or d["dialect"] == dialect]
    out = TMP_DIR / f"voicelab-{uuid.uuid4().hex[:8]}.zip"
    rows = [["الرقم", "اللهجة", "النص", "التقييم من 5", "ملاحظات"]]
    n = 0
    with zipfile.ZipFile(out, "w", zipfile.ZIP_STORED) as z:
        for d in runs:
            folder = safe(dl.get(d["dialect"], d["dialect"])) if d["kind"] == "tts" else safe(VLAB_KINDS.get(d["kind"], d["kind"]))
            for i, c in enumerate(d["clips"]):
                f = VLAB_DIR / d["id"] / str(c.get("file") or "")
                if c.get("status") != "done" or not c.get("file") or not f.exists():
                    continue
                code = vlab_code(d["id"], i)
                name = code if blind else f"{code} - {safe(c.get('provider_label'))} - {safe(c.get('label') or c.get('voice'))}"
                z.write(f, f"{folder}/{name}{f.suffix}")
                rows.append([code, dl.get(d["dialect"], d["dialect"]), d.get("text", ""), "", ""])
                n += 1
            if d.get("sample") and (VLAB_DIR / d["id"] / d["sample"]).exists() and not blind:
                z.write(VLAB_DIR / d["id"] / d["sample"], f"{folder}/{d['id'][:4].upper()}-العينة الأصلية.mp3")
        csv_text = "\n".join(",".join('"' + str(x).replace('"', '""') + '"' for x in r) for r in rows)
        if blind:
            z.writestr("ورقة التقييم.csv", "\ufeff" + csv_text)
            z.writestr("اقرأني.txt", "استمع إلى كل ملف واكتب في «ورقة التقييم» تقييمك من 1 إلى 5 وملاحظاتك: هل النطق صحيح؟ هل اللهجة دقيقة؟ هل الكلام طبيعي؟\n"
                                      "اسم كل ملف هو رقمه في الورقة.")
        else:
            z.writestr("التقرير.md", vlab_report_text(dialect))
    if not n:
        out.unlink(missing_ok=True)
        raise HTTPException(400, "لا توجد أصوات جاهزة بعد" + (" في هذه اللهجة" if dialect else ""))
    tag = f"{dialect}-" if dialect else "all-"   # اسم الملف بحروف إنجليزي (بعض المتصفحات بتشيل الاسم العربي)، والملفات جواه بالعربي
    return FileResponse(out, media_type="application/zip", filename=f"voicelab-{tag}{'raters' if blind else 'full'}-{time.strftime('%Y-%m-%d')}.zip",
                        background=BackgroundTask(lambda: out.unlink(missing_ok=True)))


def vlab_retry(rid: str) -> int:
    idx: set = set()

    def fn(d):
        for i, c in enumerate(d["clips"]):
            if vlab_retryable(c):
                c.update(status="working", error=None)
                idx.add(i)
        if idx:
            d["status"] = "working"
    d = vlab_save(rid, fn)
    if idx:
        if d["kind"] == "dub":
            threading.Thread(target=run_vlab_dub, args=(rid,), daemon=True).start()
        else:
            threading.Thread(target=run_vlab, args=(rid, idx), daemon=True).start()
    return len(idx)


@app.post("/api/voicelab/runs/{rid}/retry")
def voicelab_retry_one(rid: str):
    """🔁 الأصوات اللي فشلت في التجربة دي بس تتعاد (اللي طلعت بتفضل زي ما هي بنجومها وملاحظاتها)."""
    vlab_owner()
    if not (VLAB_DIR / Path(rid).name / "run.json").exists():
        raise HTTPException(404, "هذه التجربة غير موجودة")
    if not vlab_retry(Path(rid).name):
        raise HTTPException(400, "لا توجد أصوات فاشلة لإعادتها في هذه التجربة")
    return vlab_out(vlab_save(rid, lambda d: None))


@app.post("/api/voicelab/retry-failed")
def voicelab_retry_all():
    """🔁 كل الأصوات اللي فشلت في كل التجارب تتعاد مرة واحدة."""
    vlab_owner()
    n = sum(vlab_retry(d["id"]) for d in vlab_runs() if any(vlab_retryable(c) for c in d["clips"]))
    if not n:
        raise HTTPException(400, "لا توجد أصوات فاشلة لإعادتها")
    return {"retried": n}


