class FlowGoIn(BaseModel):
    prompt: str = ""
    stage: str = ""


@app.post("/api/flows/{fid}/stage")
def flow_stage(fid: str, body: FlowGoIn):
    """الرجوع لخطوة من قبل (أو التنقل للأمام إذا جاهزة)."""
    if body.stage not in fz.STAGES:
        raise HTTPException(400, "خطوة غير معروفة")
    # الرجوع لأي خطوة قبل النتيجة بيفتح صفحة جديدة (المشروع اللي اتعمل بيفضل في قسمه)
    return flow_to_dict(fid, flow_update(fid, lambda d: d.update(stage=body.stage, **({} if body.stage == "done" else {"output": None}))))


def flow_refs(d: dict) -> list[dict]:
    """صور العميل الذي أُنشئ لها إشارة في الوصف (أو كلها إذا لا يوجد إشارة): تُرسل كمرجع للتوليد."""
    prompt = d.get("prompt") or ""
    imgs = [a for a in d.get("assets") or [] if a.get("kind") == "صورة"]
    ment = [a for a in imgs if f"@{a['name']}" in prompt]
    use = ment or imgs
    folder = FLOWS_DIR / Path(d["_id"]).name
    return [{"path": str(folder / a["file"]), "name": a["name"]} for a in use[:4] if (folder / a["file"]).exists()]


def flow_brief(d: dict) -> str:
    idea, sc, fmt = d.get("idea") or {}, d.get("scenario") or {}, d.get("format") or "reel"
    parts = [f"الفكرة: {idea.get('title', '')} — {idea.get('idea', '')}", "السيناريو:\n" + fz.scenario_text(sc, fmt)]
    if d.get("cast"):
        parts.append("الأبطال: " + "، ".join(f"{c['name']} ({c.get('about', '')[:120]})" for c in d["cast"]))
    vo = d.get("vo") or {}
    if vo.get("speaker") == "none":
        parts.append("الصوت: بدون تعليق صوتي (موسيقى ونص مكتوب على الشاشة فقط)")
    elif vo.get("speaker") and vo["speaker"] != "narrator":
        parts.append(f"الصوت: {vo.get('speaker_name')} نفسه هو ما يتكلم للكاميرا، والنص على لسانه")
    elif vo:
        parts.append("الصوت: معلّق من خارج الكادر يحكي على الصور")
    if vo.get("lang") in dub.DIALECTS:
        parts.append(f"لغة الكلام: {dub.DIALECTS[vo['lang']]['label'].split(' ', 1)[-1]}")
    if d.get("assets"):
        parts.append("ملفات العميل: " + "، ".join(f"@{a['name']}" for a in d["assets"]))
    if (d.get("prompt") or "").strip():
        parts.append("توجيهات العميل للتوليد: " + d["prompt"].strip())
    return "\n".join(parts)


class FlowExportIn(BaseModel):
    params: dict = {}


@app.post("/api/flows/{fid}/export")
def flow_export(fid: str, body: FlowExportIn):
    """🎬 قالب الكود يُرسم فيديو: بخانات لوحة التحكم، والمشاهد على قدر التعليق الصوتي (إذا فيه)، والصوت متركّب على المزيكا."""
    d = flow_load(fid)
    flow_idle(d)
    if d["template"].get("kind") != "motion":
        raise HTTPException(400, "هذا التصدير لقوالب الكود فقط")
    mid = d["template"]["id"]
    if (MOTION_JOBS.get(mid) or {}).get("status") == "working":
        raise HTTPException(400, "هذا القالب يرسم لمشروع آخر الآن، انتظر عندما ينتهي")
    schema = fz.motion_schema(MOTION_DIR / "r" / mid / "reel.html")
    params = {**(d.get("params") or {}), **{k: v for k, v in (body.params or {}).items() if k in schema}}
    params.update({k: v for k, v in (d.get("locked") or {}).items() if k in schema and k not in (body.params or {})})   # 🧾 معطيات العميل
    params = brand_guard(schema, params, flow_brain(d))
    vt = d.get("vo_track") or {}
    vo_path = FLOWS_DIR / Path(fid).name / vt["file"] if vt.get("file") else None
    title = (d.get("scenario") or {}).get("title") or (d.get("idea") or {}).get("title") or d["template"]["name"]
    before = motion_assets().get(mid, [])
    MOTION_JOBS[mid] = {"status": "working", "progress": 0.0, "error": ""}
    flow_update(fid, lambda x: x.update(params=params, stage="generate", output={"kind": "motion", "mid": mid, "params": params, "before": before, "status": "working"}))
    def go():
        p = flow_draw_missing(fid, mid, params)   # 🎨 صورة منتج ناقصة: بتترسم بستايل القالب قبل الرسم
        p = flow_qa(fid, mid, p)                  # 🔎 الكلام المنطوق ↔ الخانات ↔ الصورة، والمخالف يتظبط قبل الرسم
        run_motion_import(mid, {"name": f"🧭 {title}"[:100], "category": "motion_graphics", "tags": ["مسار القالب"]}, p, f"🧭 {title}",
                          timing=vt.get("timing"), vo=vo_path if vo_path and vo_path.exists() else None)
    threading.Thread(target=go, daemon=True).start()
    return flow_to_dict(fid, flow_load(fid))


def flow_qa(fid: str, mid: str, params: dict) -> dict:
    """🔎 مراجعة القالب قبل الرسم: اللي اتقال فعلًا في التعليق الصوتي (من تفريغه) مقابل خانات القالب (الأسعار والدقايق والاسم)،
    وصورة المنتج مقابل اسمه. اللي ينفع يتصلح في الخانات بيتصلح، والباقي بيتكتب ملاحظة تظهر للعميل مع الفيديو."""
    d = flow_load(fid)
    vt = d.get("vo_track") or {}
    spoken = vt.get("heard_text") or vt.get("said_text") or " ".join(str(r.get("say") or "") for r in (d.get("scenario") or {}).get("scenes") or [])
    issues = videoqa.check(mid, params, spoken, d.get("facts") or {})
    params = videoqa.apply_fixes(params, issues)
    img_slot = next((s for s, n in (tplbrief.DRAW.get(mid) or {}).get("slots", []) if params.get(s)), None)
    name = params.get(dict((tplbrief.DRAW.get(mid) or {}).get("slots", [])).get(img_slot, ""), "") if img_slot else ""
    if img_slot and name and not atlas.mock_mode():
        try:
            path = next(((root() / params[img_slot][len(pre):]).resolve() for pre, root in MEDIA_ROOTS.items() if params[img_slot].startswith(pre)), None)
            if path and path.is_file():
                meter = {"usd": 0.0}
                raw = ad_json(ad_media_chat([{"role": "user", "content": [{"type": "text", "text": videoqa.image_prompt(name)},
                                                                         {"type": "image_url", "image_url": {"url": data_url(model_image(path, 512), "image/jpeg")}}]}],
                                            600, meter=meter), "فحص صورة المنتج")
                wallet.charge(wallet.credits((meter["usd"] or 0.002)), "مراجعة الفيديو: صورة المنتج", fid)
                if raw.get("match") is False:
                    issues.append({"what": "صورة المنتج", "detail": f"الصورة تُظهر «{raw.get('shows', '')}» وليس «{name}»", "fix": {}})
        except Exception as exc:  # noqa: BLE001
            print(f"[qa] image {fid}: {exc}", flush=True)
    report = {"at": now(), "issues": [{"what": i["what"], "detail": i["detail"], "fixed": bool(i.get("fix"))} for i in issues],
              "ok": not [i for i in issues if not i.get("fix")]}
    flow_update(fid, lambda x: x.update(qa=report))
    return params


def brand_guard(schema: dict, params: dict, brain: dict | None) -> dict:
    """🏷️ أمثلة القالب (اسم «بيت العطور» مثلًا) ماتطلعش في فيديو عميل: خانة اسم العلامة = اسمه أو فاضية."""
    name = str((brain or {}).get("name") or "").strip()
    name = "" if name in ("عميلي",) else name
    for k, f in schema.items():
        if f.get("role") == "brand" and (not params.get(k) or params.get(k) == f.get("def")):
            params[k] = name
    return params


def flow_draw_missing(fid: str, mid: str, params: dict) -> dict:
    """🎨 القالب فيه صورة منتج والعميل مارفعهاش: نرسم المنتج من اسمه بنفس ستايل القالب، وتتحفظ في صور منتجات العلامة."""
    jobs = tplbrief.draw_jobs(mid, params)
    if not jobs or atlas.mock_mode() or not atlas.api_key():
        return params
    d = flow_load(fid)
    bid = d.get("client_id") or active_client_id()
    folder = brain_dir(bid)
    for slot, what, prompt in jobs:
        try:
            url = atlas.generate_image("nano2", prompt, "1080x1350", "standard")
            raw, cut = folder / f"draw-src-{uuid.uuid4().hex[:6]}.png", f"draw-{uuid.uuid4().hex[:6]}.png"
            atlas.download(url, raw)
            firstvid.cutout(raw, folder / cut)
            raw.unlink(missing_ok=True)
            u = f"/media/ads/brains/{bid}/{cut}"
            update_brain(bid, lambda b: b.update(products=(b.get("products") or []) + [{"file": cut, "name": f"رسمة: {what}"[:60], "added_at": now()}]))
            params[slot] = u
            flow_update(fid, lambda x: x.update(locked={**(x.get("locked") or {}), slot: u}))
        except Exception as exc:  # noqa: BLE001
            print(f"[draw] {mid}/{slot}: {exc}", flush=True)   # الرسمة فشلت: القالب بيكمل من غير صورة (من غير منتج غلط)
    return params


@app.post("/api/flows/{fid}/generate")
def flow_generate(fid: str, body: FlowGoIn):
    """🚀 التوليد: كل ما فات (الفكرة والسيناريو والأبطال والملفات والوصف) يروح للقسم المناسب ويبدأ."""
    d = flow_load(fid)
    flow_idle(d)
    if not (d.get("idea") and d.get("scenario") and d.get("format")):
        raise HTTPException(400, "ما زال ناقص الفكرة أو السيناريو")
    d = flow_update(fid, lambda x: x.update(prompt=body.prompt.strip()[:3000], stage="generate", output=None))
    d["_id"] = fid
    tpl, fmt, sc = d["template"], d["format"], d["scenario"]
    brief = flow_brief(d)
    title = (d.get("idea") or {}).get("title") or tpl["name"]
    if fmt == "carousel":
        car = create_carousel(CarouselIn(name=f"🧭 {title}"[:80]))
        out = {"kind": "carousel", "id": car["id"], "status": "working"}
        flow_update(fid, lambda x: x.update(output=out))
        def run_car():
            carousel_chat(car["id"], ChatIn(message="أنشئ هذا الكاروسيل بالضبط على أسلوب قالب «" + tpl["name"] + "»:\n" + brief))
            flow_update(fid, lambda x: x.update(output={**out, "status": "done"}, stage="done"))
        flow_job(fid, "generate", run_car)
    elif fmt == "series":
        sid = uuid.uuid4().hex[:12]
        bible = f"{title}\n{sc.get('summary', '')}\nأسلوب القالب: {tpl['name']} — {tpl.get('desc', '')}\n" + brief
        character = "، ".join(c["name"] for c in d.get("cast") or [])
        with closing(db()) as conn, conn:
            conn.execute("INSERT INTO series (id, name, data, created_at, updated_at) VALUES (?, ?, ?, ?, ?)",
                         (sid, f"🧭 {title}"[:80], json.dumps({**new_series_data(), "bible": bible[:8000], "character": character, "client_id": d.get("client_id")}), now(), now()))
        eids = []
        for i, ep in enumerate(sc.get("episodes") or [], 1):
            e = create_episode(sid, EpisodeIn(name=str(ep.get("title") or f"الحلقة {i}")[:80], number=i))
            patch_episode(e["id"], EpisodePatch(script=fz.episode_script(ep)))
            eids.append(e["id"])
        flow_update(fid, lambda x: x.update(output={"kind": "series", "id": sid, "episodes": eids, "status": "done"}, stage="done"))
    elif tpl["kind"] == "motion":
        mid = tpl["id"]
        if (MOTION_JOBS.get(mid) or {}).get("status") == "working":
            raise HTTPException(400, "هذا القالب يرسم لمشروع آخر الآن، انتظر عندما ينتهي")
        schema = fz.motion_schema(MOTION_DIR / "r" / mid / "reel.html")
        brain = flow_brain(d)
        def run_motion():
            fill = motion_brand_fill(schema, brain)
            if atlas.mock_mode():
                params = fill
            else:
                raw = flow_llm(fz.params_messages(schema, {**sc, "brief": brief}, (brain or {}).get("name") or "", flow_assets_list(d)), "خانات القالب")
                # الكلام من السيناريو، والصور والألوان والاسم من عقل العلامة (الموديل مايعرفش يجيب صورة)
                params = {**fill, **{k: v for k, v in fz.clean_params(schema, raw).items() if schema[k].get("kind") != "image" and not (schema[k].get("kind") == "color" and k in fill)}}
            before = motion_assets().get(mid, [])
            MOTION_JOBS[mid] = {"status": "working", "progress": 0.0, "error": ""}
            flow_update(fid, lambda x: x.update(output={"kind": "motion", "mid": mid, "params": params, "before": before, "status": "working"}))
            run_motion_import(mid, {"name": f"🧭 {title}"[:100], "category": "motion_graphics", "tags": ["مسار القالب"]}, params, f"🧭 {title}")
        flow_job(fid, "generate", run_motion)
    elif tpl["kind"] == "typo":
        script = " ".join(str(b.get("say") or b.get("text") or "") for b in sc.get("beats") or []).strip() or sc.get("summary", "")
        r = typo_new(TypoNewIn(name=f"🧭 {title}"[:100], text=script))
        flow_update(fid, lambda x: x.update(output={"kind": "typo", "id": r["id"], "status": "done"}, stage="done"))
    else:
        script = fz.scenario_script(sc, fmt)
        vo, ts = d.get("vo") or {}, d.get("tset") or {}
        lang = vo.get("lang") if vo.get("lang") in dub.DIALECTS else flow_lang_guess(d)
        tv = tvideo_create(TvIn(template=tpl["id"], section="templates", script=script, script_mode="own" if script else "ai",
                                brief=brief[:3000], length=ts.get("length") or max(20, min(60, 10 * len(sc.get("beats") or [1, 2, 3]))),
                                ratio=ts.get("ratio") or "", lang=lang, voice=vo.get("voice") or "", voice_on=vo.get("on", True)))
        refs = flow_refs(d)
        # الشكل اللي اختاره في المسار بيبقى هو المختار في صفحة الفيديو (مفتاح الستايل بيترسم بيه)
        extra = {**({"flow_refs": refs} if refs else {}), **({"style_variant": ts["look"]} if ts.get("look") else {})}
        if extra:
            tv_update(tv["id"], lambda x: x.update(**extra))
        flow_update(fid, lambda x: x.update(output={"kind": "tvideo", "id": tv["id"], "status": "done"}, stage="done"))
    return flow_to_dict(fid, flow_load(fid))


# ---------------------------------------------------------------- 🧪 مولّدات من غير قوالب: صوت، صور، فيديو
# كل توليدة بتتحفظ في gens/<id>/ ومعاها item.json (حالتها وتكلفتها)، وبتظهر في تاريخ المولّدات.
# الصوت بيدخل مكتبة التعليق الصوتي، والفيديو بيدخل «الفيديوهات الجاهزة» (يتنشر أو يتدبلج أو يدخل المونتاج).
GEN_DIR = DATA_DIR / "gens"
GEN_DIR.mkdir(parents=True, exist_ok=True)
app.mount("/media/gens", StaticFiles(directory=GEN_DIR), name="gens")
GEN_LOCK = threading.Lock()
GEN_RATIOS = {"9:16": "1024x1536", "16:9": "1536x1024", "1:1": "1024x1024", "4:5": "1024x1280"}


def gen_save(gid: str, item: dict) -> None:
    f = GEN_DIR / gid / "item.json"
    f.parent.mkdir(parents=True, exist_ok=True)
    f.write_text(json.dumps(item, ensure_ascii=False), encoding="utf-8")


def gen_set(gid: str, **kw) -> None:
    with GEN_LOCK:
        f = GEN_DIR / gid / "item.json"
        item = json.loads(f.read_text(encoding="utf-8"))
        item.update(kw, updated_at=now())
        gen_save(gid, item)


def gen_dict(gid: str, item: dict) -> dict:
    base = f"/media/gens/{gid}"
    return {**item, "id": gid, "url": f"{base}/{item['file']}" if item.get("file") else None,
            "ref_url": f"{base}/{item['ref']}" if item.get("ref") else None}


@app.get("/api/gens")
def gens_list():
    out = []
    for f in sorted(GEN_DIR.glob("*/item.json"), key=lambda x: x.stat().st_mtime, reverse=True)[:120]:
        try:
            d = json.loads(f.read_text(encoding="utf-8"))
        except ValueError:
            continue
        if owned(d.get("client_id")):
            out.append(gen_dict(f.parent.name, d))
    return out


@app.get("/api/gens/info")
def gens_info():
    return {**dub_info(), "image_models": {k: {"label": v[2], "price": v[0]} for k, v in TV_IMAGE_MODELS.items()},
            "video_models": vm_list(), "ratios": list(GEN_RATIOS), "video_ratios": list(RATIO_VIDEO), "first_frame_cost": TV_IMAGE_MODELS["nano2"][0]}


def gen_new(kind: str, prompt: str, **extra) -> tuple[str, dict]:
    if not (atlas.api_key() or atlas.mock_mode()):
        raise HTTPException(400, "مفتاح Atlas غير مسجل. ضعه من ⚙️ الإعدادات")
    gid = uuid.uuid4().hex[:12]
    item = {"kind": kind, "prompt": prompt, "status": "working", "step": "في الطابور", "error": None, "file": None,
            "client_id": active_client_id(), "created_at": now(), "updated_at": now(), **extra}
    gen_save(gid, item)
    return gid, item


def gen_job(gid: str, fn) -> None:
    def run():
        try:
            fn()
        except Exception as exc:  # noqa: BLE001
            gen_set(gid, status="failed", step=None, error=str(getattr(exc, "detail", None) or exc)[:400])
    threading.Thread(target=run, daemon=True).start()


class GenVoiceIn(BaseModel):
    text: str
    lang: str
    voice: str
    name: str = ""


@app.post("/api/gens/voice")
def gen_voice(body: GenVoiceIn):
    """🎙️ مولد صوت: الكلام بلهجة وصوت تختارهم، وبيتحفظ كمان في مكتبة التعليق الصوتي."""
    text = body.text.strip()[:3000]
    if not text:
        raise HTTPException(400, "اكتب النص")
    if body.voice not in dub.VOICES or body.lang not in dub.DIALECTS:
        raise HTTPException(400, "اختر اللهجة والصوت")
    if dub.VOICES[body.voice]["provider"] == "fasih" and not (fasih.api_key() or atlas.mock_mode()):
        raise HTTPException(400, "اللهجات العربية تحتاج مفتاح فصيح (FASIH_API_KEY)")
    gid, item = gen_new("voice", text, lang=body.lang, voice=body.voice, name=body.name.strip()[:80])

    def run():
        gen_set(gid, step="🎙️ يعمل الصوت")
        wav = GEN_DIR / gid / "voice.wav"
        vo_say(text, body.voice, body.lang, wav)
        mp3 = GEN_DIR / gid / "voice.mp3"
        subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", str(wav), "-c:a", "libmp3lame", "-b:a", "160k", str(mp3)],
                       check=True, capture_output=True, timeout=120)
        wav.unlink(missing_ok=True)
        dur = probe_duration(mp3)
        aid = uuid.uuid4().hex[:12]
        fname = f"voice_{aid}.mp3"
        shutil.copy(mp3, AUDIO_DIR / fname)
        with closing(db()) as conn, conn:
            conn.execute("INSERT INTO audio (id, kind, name, filename, duration, created_at) VALUES (?, 'voice', ?, ?, ?, ?)",
                         (aid, (body.name.strip() or f"🎙️ {text[:40]}")[:80], fname, dur, now()))
        gen_set(gid, status="done", step=None, file=mp3.name, duration=round(dur, 2), audio_id=aid)
    gen_job(gid, run)
    return gen_dict(gid, item)



def billed(fn, hold, part: int | None = None):
    """المولد بيشتغل والنقاط محجوزة قبله (wallet.reserve)؛ لو فشل نصيبه من الحجز بيرجع، والتوليد جواه مايتخصمش تاني."""
    def run():
        try:
            with wallet.covered():
                fn()
        except BaseException:
            wallet.refund(hold, part, "التوليد فشل")
            raise
    return run

@app.post("/api/gens/image")
def gen_image(prompt: str = Form(...), model: str = Form("nano2"), ratio: str = Form("9:16"), count: int = Form(1),
              refs: list[UploadFile] | None = File(None)):
    """🖼️ مولد صور: وصف (ومرجع إذا تريد) ← صورة أو أكثر بالنموذج الذي تختاره."""
    prompt = prompt.strip()[:4000]
    if not prompt:
        raise HTTPException(400, "صِف الصورة")
    model = model if model in TV_IMAGE_MODELS else "nano2"
    ratio = ratio if ratio in GEN_RATIOS else "9:16"
    n = max(1, min(4, int(count or 1)))
    each = wallet.credits(TV_IMAGE_MODELS[model][0])
    hold = None if atlas.mock_mode() else wallet.reserve(each * n, f"مولد الصور ({n} × صورة)")
    ids = []
    ref_files = []
    for i in range(n):
        gid, item = gen_new("image", prompt, model=model, ratio=ratio, cost=TV_IMAGE_MODELS[model][0])
        if i == 0:
            for j, up in enumerate((refs or [])[:4]):
                if up and up.filename:
                    ref_files.append(save_upload(up, IMAGE_EXTENSIONS, GEN_DIR / gid, f"ref{j}"))
            if ref_files:
                gen_set(gid, ref=ref_files[0])
        ids.append((gid, item))
    first = GEN_DIR / ids[0][0]

    def make(gid):
        def run():
            gen_set(gid, step="🖼️ يرسم")
            dest = GEN_DIR / gid / "image.png"
            if atlas.mock_mode():
                subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-f", "lavfi", "-i",
                                f"color=c=0x{uuid.uuid4().hex[:6]}:s={GEN_RATIOS[ratio]}", "-frames:v", "1", str(dest)], check=True, capture_output=True, timeout=60)
            else:
                images = [atlas.reference_url(first / f) for f in ref_files] or None
                atlas.download(atlas.generate_image(model, prompt, GEN_RATIOS[ratio], "high", images), dest)
            gen_set(gid, status="done", step=None, file=dest.name)
        return billed(run, hold, each)
    for gid, _ in ids:
        gen_job(gid, make(gid))
    return [gen_dict(g, it) for g, it in ids]


@app.post("/api/gens/video")
def gen_video(prompt: str = Form(...), model: str = Form(VDEF), duration: int = Form(5), ratio: str = Form("9:16"),
              resolution: str = Form("480p"), audio: bool = Form(True), image: UploadFile | None = File(None)):
    """🎬 مولد فيديو: وصف + (صورة بداية اختيارية) ← فيديو بأي نموذج عند Atlas. بدون صورة، البرنامج يرسم أول فريم من الوصف أولًا."""
    prompt = prompt.strip()[:4000]
    if not prompt:
        raise HTTPException(400, "صِف الفيديو")
    vm = TRIAL_MODELS.get(model) or TRIAL_MODELS[VDEF]
    model = model if model in TRIAL_MODELS else VDEF
    ratio = ratio if ratio in RATIO_VIDEO else "9:16"
    secs = max(3, min(15, int(duration or 5)))
    resolution = "720p" if resolution == "720p" else "480p"
    cost = round(vm["per_sec"] * secs * (2 if resolution == "720p" else 1) + (0 if image and image.filename else TV_IMAGE_MODELS["nano2"][0]), 3)
    hold = None if atlas.mock_mode() else wallet.reserve(wallet.credits(cost), f"مولد الفيديو ({secs} ث)")
    gid, item = gen_new("video", prompt, model=model, model_label=vm["label"], duration=secs, ratio=ratio, resolution=resolution, cost=cost)
    folder = GEN_DIR / gid
    ref = save_upload(image, IMAGE_EXTENSIONS, folder, "start") if image and image.filename else None
    if ref:
        gen_set(gid, ref=ref)

    def run():
        start = folder / ref if ref else folder / "frame.png"
        if not ref:
            gen_set(gid, step="🖼️ يرسم أول فريم من الوصف")
            if atlas.mock_mode():
                subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-f", "lavfi", "-i", f"color=c=0x8A7F72:s={GEN_RATIOS[ratio]}",
                                "-frames:v", "1", str(start)], check=True, capture_output=True, timeout=60)
            else:
                atlas.download(atlas.generate_image("nano2", prompt + ". The first frame of a video, cinematic, no text.", GEN_RATIOS[ratio], "medium"), start)
            gen_set(gid, ref=start.name)
        gen_set(gid, step=f"🎬 يولّد الفيديو ({vm['label'].split(' · ')[0]}، {secs} ث)")
        dest = folder / "video.mp4"
        W, H = RATIO_VIDEO.get(ratio, RATIO_VIDEO["9:16"])
        if atlas.mock_mode():
            gen_motion("seedance-mini", resolution, ratio, prompt, start, start, secs, dest, W, H)
        else:
            body = {"model": vm["model"], "prompt": prompt, "image": atlas.reference_url(start), "duration": secs,
                    "resolution": resolution, "ratio": ratio, "generate_audio": bool(audio), "watermark": False}
            atlas.download(atlas.run_model("Video", body, "مولد الفيديو", max_seconds=1800, interval=6), dest)
        dur = probe_duration(dest)
        export_id = uuid.uuid4().hex[:12]
        filename = f"gen_{export_id}.mp4"
        shutil.copy(dest, EXPORTS_DIR / filename)
        with closing(db()) as conn, conn:
            conn.execute("INSERT INTO exports (id, name, filename, duration, source, project_id, created_at) VALUES (?, ?, ?, ?, 'gen', NULL, ?)",
                         (export_id, f"🎬 {prompt[:60]}", filename, dur, now()))
        gen_set(gid, status="done", step=None, file=dest.name, duration=round(dur, 2), export_id=export_id)
    gen_job(gid, billed(run, hold))
    return gen_dict(gid, item)


@app.delete("/api/gens/{gid}")
def gen_delete(gid: str):
    shutil.rmtree(GEN_DIR / Path(gid).name, ignore_errors=True)
    return {"ok": True}


# ---------------------------------------------------------------- 💳 الأسعار والنقط
import billing  # noqa: E402

# فصل الصوت (AudioShake): كلام ١.٥ + مؤثرات ١.٥ + موسيقى ~١ كريديت للدقيقة، والكريديت من $0.027 لـ $0.04 حسب الباقة عندهم،
# وكل ملف بيتقرّب لدقيقة كاملة. حاسبينها $0.25 للدقيقة (أعلى من المتوقع عشان الأمان) لحد ما نتأكد من الداشبورد.
AUDIOSHAKE_PER_MIN: float | None = 0.25


def pricing_examples() -> list[dict]:
    """أمثلة «كل شيء بكام نقطة» من أسعار النماذج الحقيقية الآن."""
    rows: list[tuple[str, str, float | None]] = []
    vm = TRIAL_MODELS
    for key, secs in (("seedance-mini", 5), ("seedance-mini", 10), ("seedance-fast", 10), ("seedance", 10)):
        if key in vm:
            rows.append(("🎬 فيديو", f"{vm[key]['label'].split(' (')[0]} · {secs} ثواني", vm[key]["per_sec"] * secs))
    kling = next((k for k in vm if "kling" in k.lower()), None)
    if kling:
        rows.append(("🎬 فيديو", f"{vm[kling]['label']} · 5 ثواني", vm[kling]["per_sec"] * 5))
    for key in ("nano2", "nanopro", "sunburst"):
        rows.append(("🖼️ صورة", TV_IMAGE_MODELS[key][2].split(" (")[0], TV_IMAGE_MODELS[key][0]))
    # الأفاتار والصوت والدبلجة: من غير أسماء الشركات (دي في لوحة الأدمن بس)، ورقم واحد يكفي أغلى مزوّد
    rows.append(("🗣️ أفاتار يتكلم", "جودة عادية · 10 ثواني", AVATAR_MODELS["std"]["per_sec"] * 10))
    rows.append(("🗣️ أفاتار يتكلم", "جودة عالية · 10 ثواني", AVATAR_MODELS["pro"]["per_sec"] * 10))
    voice_min = max(dub.FASIH_PER_MIN, 0.9 * 0.10)
    rows.append(("🎙️ صوت", "تعليق صوتي بأي لهجة أو لغة · دقيقة", voice_min))
    dub_min = voice_min + 0.01 + (AUDIOSHAKE_PER_MIN or 0)
    rows.append(("🌍 دبلجة", "دبلجة بدون ليب سينك · دقيقة", dub_min))
    rows.append(("🌍 دبلجة", "دبلجة بليب سينك · دقيقة", dub_min + dub.LIPSYNC["veed"]["per_sec"] * 60))
    rows.append(("🧠 العقل", "أفكار ونصوص وترجمة", None))
    return [{"group": g, "label": lab, "credits": billing.credits_for(c) if c is not None else 0, "free": c is None} for g, lab, c in rows]


