@app.get("/api/twins")
def twins_list():
    out = []
    for f in sorted(TWINS_DIR.glob("*/twin.json"), key=lambda x: x.stat().st_mtime, reverse=True):
        try:
            d = json.loads(f.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        if not owned(d.get("client_id")) and "chars" not in share_keys():   # 🔒 نسخة براند تاني (إلا لو «الشخصيات» متشاركة)
            continue
        out.append(twin_to_dict(f.parent.name, d))
    return out


