# ---------------------------------------------------------------- 📁 مكتبة العقل: فولدرات جوه فولدرات + المخ بيوصّف كل ملف
LIB_LOCK = threading.Lock()


def lib_dir(bid: str | None = None) -> Path:
    d = brain_dir(bid or active_client_id() or "default") / "library"
    d.mkdir(parents=True, exist_ok=True)
    return d


def lib_load(bid: str | None = None) -> dict:
    f = lib_dir(bid) / "library.json"
    try:
        return json.loads(f.read_text(encoding="utf-8")) if f.exists() else lib_.empty()
    except ValueError:
        return lib_.empty()


def lib_update(fn, bid: str | None = None) -> dict:
    with LIB_LOCK:
        d = lib_load(bid)
        fn(d)
        f = lib_dir(bid) / "library.json"
        f.with_suffix(".tmp").write_text(json.dumps(d, ensure_ascii=False), encoding="utf-8")
        f.with_suffix(".tmp").replace(f)
        return d


# 📚 مكتبة محتويات البراند: ٤ فولدرات أساسية (صور، فيديوهات، تعليقات صوتية، موسيقى)، وجوه كل واحد فولدرات زي ما تحب.
# التعليقات الصوتية والموسيقى مربوطة بمكتبة الصوت القديمة (اللي المونتاج بيختار منها): أي حاجة هنا بتظهر هناك والعكس.
LIB_ROOTS = {"images": ("صور", "image"), "videos": ("فيديوهات", "video"), "voice": ("تعليقات صوتية", "audio"), "music": ("موسيقى", "audio")}


def lib_root_for(f: dict) -> str:
    if f["kind"] == "image":
        return "images"
    if f["kind"] == "video":
        return "videos"
    return "music" if re.search(r"موسيق|مزيك|music|song|track|بيت", f.get("name") or "", re.I) else "voice"


def lib_prepare(d: dict) -> dict:
    """المجلدات الأساسية موجودة دائمًا، وأي ملف أو مجلد برّاها يُنقل داخل المناسب له. يعود {النوع: id المجلد}."""
    roots = {}
    for key, (name, _) in LIB_ROOTS.items():
        f = next((x for x in d["folders"] if x.get("sys") == key), None) \
            or next((x for x in d["folders"] if not x.get("parent") and not x.get("sys") and lib_.norm(x["name"]) == lib_.norm(name)), None)
        if not f:
            f = {"id": lib_.fid(), "name": name, "parent": None}
            d["folders"].append(f)
        f.update(sys=key, parent=None)
        roots[key] = f["id"]
    ids = set(roots.values())
    for f in d["files"]:
        if not f.get("folder") or f["folder"] not in {x["id"] for x in d["folders"]}:
            f["folder"] = roots[lib_root_for(f)]
    for x in d["folders"]:
        if x["id"] in ids or x.get("parent"):
            continue
        inside = lib_.descendants(d, x["id"]) | {x["id"]}
        kinds = [lib_root_for(f) for f in d["files"] if f.get("folder") in inside]
        x["parent"] = roots[max(set(kinds), key=kinds.count)] if kinds else roots["images"]
    return roots


def lib_root_of(d: dict, folder: str | None) -> str | None:
    for f in lib_.path_of(d, folder):
        if f.get("sys"):
            return f["sys"]
    return None


def lib_audio_link(bid: str, f: dict, kind: str) -> None:
    """ملف صوت وُضع في «تعليقات صوتية» أو «موسيقى»: يُسجّل في مكتبة الصوت أيضًا (المونتاج والقوالب يختارون منها)."""
    src = lib_path(f, bid)
    aid = uuid.uuid4().hex[:12]
    name = f"{kind}_{aid}{src.suffix.lower()}"
    try:
        shutil.copyfile(src, AUDIO_DIR / name)
        with closing(db()) as conn, conn:
            conn.execute("INSERT INTO audio (id, kind, name, filename, duration, created_at) VALUES (?, ?, ?, ?, ?, ?)",
                         (aid, kind, f["name"], name, float(f.get("dur") or probe_duration(AUDIO_DIR / name)), now()))
        f["audio_id"] = aid
    except (OSError, ValueError, sqlite3.Error):
        pass


def lib_ready(bid: str) -> dict:
    """قبل ما المكتبة تُعرض: المجلدات الأساسية، والتعليقات والموسيقى التي رُفعت من مكان آخر تتجاب هنا (مرة واحدة).
    المكتبة المشتركة (SHARED_LIB) تأخذ صوت كل العلامات للأنواع المتشاركة، ومكتبة العلامة تأخذ الخاص به للأنواع الذي غير متشاركة."""
    shared = bid == SHARED_LIB
    kinds = sorted((share_keys() & {"voice", "music"}) if shared else ({"voice", "music"} - share_keys()))
    with closing(db()) as conn:
        q = ",".join("?" * len(kinds))
        rows = [dict(r) for r in conn.execute(f"SELECT * FROM audio WHERE {'1' if shared else 'mine(client_id)'} AND kind IN ({q}) ORDER BY created_at", kinds)] if kinds else []
        others = set() if shared else {r["id"] for r in conn.execute("SELECT id FROM audio WHERE NOT mine(client_id)")}
    gone = []
    def fn(d):
        # 🔒 نسخ اتجابت قبل كده من براند تاني (لما المكتبة كانت مشتركة): بتتشال من هنا
        keep = []
        for f in d["files"]:
            (gone if f.get("audio_id") in others else keep).append(f)
        d["files"] = keep
        roots = lib_prepare(d)
        seen = set(d.get("audio_seen") or [])
        for r in rows:
            if r["id"] in seen or any(f.get("audio_id") == r["id"] for f in d["files"]):
                seen.add(r["id"])
                continue
            seen.add(r["id"])
            src = AUDIO_DIR / r["filename"]
            if not src.exists():
                continue
            name = f"audio_{uuid.uuid4().hex[:8]}{src.suffix.lower()}"
            try:
                shutil.copyfile(src, lib_dir(bid) / name)
            except OSError:
                continue
            d["files"].append({"id": lib_.fid(), "file": name, "name": lib_.clean_name(r["name"]), "kind": "audio", "folder": roots["music" if r["kind"] == "music" else "voice"],
                               "size": src.stat().st_size, "desc": "", "tags": [], "status": "ready", "at": r["created_at"], "dur": r["duration"], "audio_id": r["id"],
                               "imported": True, **({"origin": r.get("client_id") or first_client_id()} if shared else {})})
        d["audio_seen"] = sorted(seen)
    lib = lib_update(fn, bid)
    for f in gone:
        (lib_dir(bid) / Path(f["file"]).name).unlink(missing_ok=True)
    return lib


def lib_file_dict(lib: dict, f: dict, bid: str) -> dict:
    base = f"/media/ads/brains/{Path(f.get('_st') or bid).name}/library"
    return {**f, "url": f"{base}/{f['file']}", "thumb": f"{base}/{f['thumb']}" if f.get("thumb") else (f"{base}/{f['file']}" if f["kind"] == "image" else None),
            "path": lib_.path_text(lib, f.get("folder"))}


def lib_to_dict(lib: dict, bid: str) -> dict:
    counts = {}
    for f in lib["files"]:
        for a in [x["id"] for x in lib_.path_of(lib, f.get("folder"))]:   # الفولدر وكل اللي فوقه
            counts[a] = counts.get(a, 0) + 1
    return {"roots": {x["sys"]: x["id"] for x in lib["folders"] if x.get("sys")},
            "folders": [{**x, "count": counts.get(x["id"], 0), "path": lib_.path_text(lib, x["id"])} for x in lib["folders"]],
            "files": [lib_file_dict(lib, f, bid) for f in lib["files"]], "total": len(lib["files"]),
            "tagging": sum(1 for f in lib["files"] if f.get("status") == "tagging"), "kinds": lib_.KINDS}


# 🔗 مشاركة فولدر أساسي مع باقي البراندات اللي في نفس الأكاونت: محتوياته بتتنقل لمكتبة مشتركة واحدة (SHARED_LIB)
# وكل براند بيشوفها مكان الفولدر بتاعه، ولما المشاركة تتشال كل ملف بيرجع للبراند اللي جه منه (origin).
SHARED_LIB = "_shared"
SHARE_KEYS = ("ideas", "images", "videos", "voice", "music", "chars", "exports")
SHARE_LOCK = threading.Lock()


def lib_path(f: dict, bid: str | None = None) -> Path:
    """مكان الملف على الديسك (ملف المكتبة المشتركة عليه _st)."""
    return lib_dir(f.get("_st") or bid) / f["file"]


def lib_subtree(d: dict, keys: set[str]) -> set[str]:
    out = set()
    for x in d["folders"]:
        if x.get("sys") in keys:
            out |= {x["id"]} | lib_.descendants(d, x["id"])
    return out


def lib_merged(bid: str, ready: bool = True) -> dict:
    """المكتبة كما العلامة شايفها: فولدراته، ومكان كل مجلد أساسي متشارك يأتي ما في المكتبة المشتركة."""
    sh = share_keys() & set(LIB_ROOTS)
    own = lib_ready(bid) if ready else lib_load(bid)
    if not sh:
        return own
    shl = lib_ready(SHARED_LIB) if ready else lib_load(SHARED_LIB)
    if not ready:
        shl = json.loads(json.dumps(shl)); lib_prepare(shl)
    a, b = lib_subtree(own, sh), lib_subtree(shl, sh)
    return {**own, "folders": [x for x in own["folders"] if x["id"] not in a] + [x for x in shl["folders"] if x["id"] in b],
            "files": [x for x in own["files"] if x.get("folder") not in a] + [{**x, "_st": SHARED_LIB} for x in shl["files"] if x.get("folder") in b]}


def lib_store_of(xid: str | None, bid: str) -> str:
    """المجلد أو هذا الملف متخزن أين: مكتبة العلامة ولا المشتركة."""
    if xid and share_keys() & set(LIB_ROOTS):
        sh = lib_load(SHARED_LIB)
        if any(x["id"] == xid for x in sh["folders"]) or any(x["id"] == xid for x in sh["files"]):
            return SHARED_LIB
    return bid


def lib_view(bid: str) -> dict:
    return lib_to_dict(lib_merged(bid), bid)


def lib_move_root(src: str, key: str, dest_of) -> None:
    """ينقل كل ما داخل المجلد الأساسي key من مكتبة src للمكان الذي dest_of يقوله (بنفس أسامي المجلدات، والمجلدات التي بنفس الاسم تتدمج)."""
    d = json.loads(json.dumps(lib_load(src)))
    root = lib_prepare(d)[key]
    sub = lib_.descendants(d, root)
    rel = lambda fid: [x["name"] for x in lib_.path_of(d, fid)][1:]  # noqa: E731 — المسار من غير الفولدر الأساسي
    groups: dict[str, dict] = {}
    for x in d["folders"]:
        if x["id"] in sub:
            groups.setdefault(dest_of(x), {"folders": [], "files": []})["folders"].append(x)
    for f in d["files"]:
        if f.get("folder") in sub | {root}:
            groups.setdefault(dest_of(f), {"folders": [], "files": []})["files"].append(f)
    moved = set()
    for dst, g in groups.items():
        if dst == src:
            continue
        for f in g["files"]:
            for k in ("file", "thumb"):
                n = f.get(k)
                if not n:
                    continue
                a, b = lib_dir(src) / Path(n).name, lib_dir(dst) / Path(n).name
                if b.exists() and a.exists():
                    f[k] = f"{uuid.uuid4().hex[:6]}_{Path(n).name}"; b = lib_dir(dst) / f[k]
                if a.exists():
                    shutil.move(str(a), str(b))
        def fn(dd, g=g):
            r = lib_prepare(dd)[key]
            for x in g["folders"]:
                fid_ = lib_.ensure_path(dd, r, rel(x["id"]))
                hit = next((y for y in dd["folders"] if y["id"] == fid_), None)
                if hit and dst == SHARED_LIB:
                    hit.setdefault("origin", x.get("origin") or src)
            for f in g["files"]:
                nf = {k: v for k, v in f.items() if k != "_st"}
                if dst == SHARED_LIB:
                    nf.setdefault("origin", src)
                nf["folder"] = lib_.ensure_path(dd, r, rel(f["folder"])) or r
                dd["files"].append(nf)
            dd["audio_seen"] = sorted(set(dd.get("audio_seen") or []) | {f["audio_id"] for f in g["files"] if f.get("audio_id")})
        lib_update(fn, dst)
        moved |= {x["id"] for x in g["folders"]} | {f["id"] for f in g["files"]}
    if moved:
        lib_update(lambda dd: dd.update(files=[f for f in dd["files"] if f["id"] not in moved], folders=[x for x in dd["folders"] if x["id"] not in moved]), src)


def ideas_move(on: bool, brands: list[str], active: str | None) -> None:
    """💡 أفكارك (مجلد الأفكار) تُنقل للمشتركة وتعود بنفس الطريقة، ومعها الفويس نوت الخاص بها."""
    cids = {mem_cid({"client_id": b}): b for b in brands}
    srcs = list(cids) if on else [SHARED_LIB]
    for src in srcs:
        items = [x for x in mem_load(src).get("saved") or [] if x.get("kind") == "idea" and x.get("mine")]
        if not items:
            continue
        for x in items:
            dst = SHARED_LIB if on else (x.get("origin") if x.get("origin") in cids else mem_cid({"client_id": active}))
            if on:
                x.setdefault("origin", src)
            a = (x.get("item") or {}).get("audio")
            if a and (my_ideas_dir(src) / Path(a).name).exists():
                shutil.move(str(my_ideas_dir(src) / Path(a).name), str(my_ideas_dir(dst) / Path(a).name))
            mem_update(dst, lambda m, x=x: m.update(saved=([*(m.get("saved") or []), x])[-ideamem.SAVED_MAX:]))
        ids = {x["id"] for x in items}
        mem_update(src, lambda m: m.update(saved=[y for y in m.get("saved") or [] if y["id"] not in ids]))


def share_state() -> dict:
    with closing(db()) as conn:
        n = conn.execute("SELECT COUNT(*) FROM ad_brains").fetchone()[0]
    return {"keys": sorted(share_keys()), "brands": n}


class ShareIn(BaseModel):
    key: str
    on: bool


@app.get("/api/library/share")
def library_share_get():
    return share_state()


@app.put("/api/library/share")
def library_share_put(body: ShareIn):
    if body.key not in SHARE_KEYS:
        raise HTTPException(400, "هذا المجلد لا يصلح يتشارك")
    with SHARE_LOCK:
        keys = set(json.loads(auth.get_setting("lib_share") or "[]"))
        if body.on == (body.key in keys):
            return share_state()
        with closing(db()) as conn:
            brands = [r["id"] for r in conn.execute("SELECT id FROM ad_brains ORDER BY created_at")]
        active = active_client_id()
        if body.key in LIB_ROOTS:
            if body.on:
                for b in brands:
                    lib_move_root(b, body.key, lambda x: SHARED_LIB)
            else:
                lib_move_root(SHARED_LIB, body.key, lambda x: x.get("origin") if x.get("origin") in brands else active)
        elif body.key == "ideas":
            ideas_move(body.on, brands, active)
        keys = (keys | {body.key}) if body.on else (keys - {body.key})
        auth.set_setting("lib_share", json.dumps(sorted(keys)))
        _BRAND["t"] = 0.0
    return share_state()


@app.get("/api/library")
def library_get():
    return lib_view(active_client_id())


class LibFolderIn(BaseModel):
    name: str = ""
    parent: str | None = None


@app.post("/api/library/folders")
def library_folder_new(body: LibFolderIn):
    me = active_client_id()
    bid = lib_store_of(body.parent, me)
    def fn(d):
        if body.parent and not any(f["id"] == body.parent for f in d["folders"]):
            raise HTTPException(404, "هذا المجلد غير موجود")
        if not body.parent:
            raise HTTPException(400, "المجلد الجديد يُنشأ داخل صور أو فيديوهات أو تعليقات صوتية أو موسيقى")
        if len(lib_.path_of(d, body.parent)) >= lib_.MAX_DEPTH:
            raise HTTPException(400, "كفاية مجلدات داخل بعض هكذا")
        d["folders"].append({"id": lib_.fid(), "name": lib_.clean_name(body.name, "مجلد جديد"), "parent": body.parent or None,
                             **({"origin": me} if bid == SHARED_LIB else {})})
    lib_update(fn, bid)
    return lib_view(me)


class LibFolderPatch(BaseModel):
    name: str | None = None
    parent: str | None = None
    move: bool = False   # parent = None معناه الرئيسية لما move = true


@app.patch("/api/library/folders/{fid}")
def library_folder_patch(fid: str, body: LibFolderPatch):
    me = active_client_id()
    bid = lib_store_of(fid, me)
    if body.move and body.parent and lib_store_of(body.parent, me) != bid:
        raise HTTPException(400, "هذا المجلد في مكتبة متشاركة والآخر لا، لا يصلح تنقل بينهم")
    def fn(d):
        f = next((x for x in d["folders"] if x["id"] == fid), None)
        if not f:
            raise HTTPException(404, "هذا المجلد غير موجود")
        if f.get("sys"):
            raise HTTPException(400, "هذا مجلد أساسي في المكتبة، لا يصلح يتغيّر")
        if body.move and not body.parent:
            raise HTTPException(400, "المجلد يجب يظل داخل واحد من المجلدات الأساسية")
        if body.name is not None:
            f["name"] = lib_.clean_name(body.name, f["name"])
        if body.move:
            if body.parent and (body.parent == fid or body.parent in lib_.descendants(d, fid)):
                raise HTTPException(400, "لا يصلح تضع المجلد داخل نفسه")
            f["parent"] = body.parent or None
    lib_update(fn, bid)
    return lib_view(me)


@app.delete("/api/library/folders/{fid}")
def library_folder_delete(fid: str):
    """المجلد يُزال، واللي جواه (مجلدات وملفات) يظهر للفولدر الذي فوقه، لا يوجد ملف يُحذف."""
    me = active_client_id()
    bid = lib_store_of(fid, me)
    def fn(d):
        f = next((x for x in d["folders"] if x["id"] == fid), None)
        if not f:
            raise HTTPException(404, "هذا المجلد غير موجود")
        if f.get("sys"):
            raise HTTPException(400, "هذا مجلد أساسي في المكتبة، لا يصلح يُزال")
        for c in d["folders"]:
            if c.get("parent") == fid:
                c["parent"] = f.get("parent")
        for x in d["files"]:
            if x.get("folder") == fid:
                x["folder"] = f.get("parent")
        d["folders"] = [x for x in d["folders"] if x["id"] != fid]
    lib_update(fn, bid)
    return lib_view(me)


@app.post("/api/library/files")
def library_upload(folder: str = Form(""), paths: str = Form(""), files: list[UploadFile] = File(...)):
    """⬆ ملفات أو مجلد كامل بفولدراته (paths = المسار داخل المجلد لكل ملف، بنفس الترتيب).
    إذا نوع الملف له مجلد أساسي في مكتبة أخرى (متشاركة أو لا) يروح هناك."""
    me = active_client_id()
    bid = lib_store_of(folder or None, me)
    folder_dir = lib_dir(bid)
    rel = [x for x in paths.split("\n")] if paths else []
    added = []
    for i, up in enumerate(files[:200]):
        ext = Path(up.filename or "").suffix.lower()
        kind = lib_.kind_of(ext)
        if not kind:
            continue   # الفولدر ممكن يكون فيه ملفات تانية
        allowed = lib_.IMAGE_EXT if kind == "image" else lib_.VIDEO_EXT if kind == "video" else lib_.AUDIO_EXT
        name = save_upload(up, allowed, folder_dir, kind)
        meta = {}
        if kind != "image":
            try:
                info = media_info(folder_dir / name)
                meta = {"dur": round(info.duration, 2), **({"w": info.width, "h": info.height} if kind == "video" else {})}
            except Exception:  # noqa: BLE001
                (folder_dir / name).unlink(missing_ok=True)
                continue
        parts = [p for p in re.split(r"[/\\]+", rel[i])][:-1] if i < len(rel) and rel[i] else []
        added.append({"id": lib_.fid(), "file": name, "name": lib_.clean_name(Path(up.filename or name).stem), "kind": kind, "parts": parts,
                      "size": (folder_dir / name).stat().st_size, "desc": "", "tags": [], "status": "tagging", "at": now(), "origin": me, **meta})
    if not added:
        raise HTTPException(400, "لا يوجد صور أو فيديوهات أو أصوات في هذه الملفات")
    def fn(d):
        roots = lib_prepare(d)
        base = folder or None
        if base and not any(f["id"] == base for f in d["folders"]):
            base = None
        here = lib_root_of(d, base)
        for a in added:
            want = "voice" if a["kind"] == "audio" and here not in ("voice", "music") else lib_root_for(a) if a["kind"] != "audio" else here
            if (SHARED_LIB if want in share_keys() else me) != bid:   # فولدره الأساسي في المكتبة التانية
                a["_to"] = want
                continue
            start = base if here == want or (a["kind"] == "audio" and here in ("voice", "music")) else roots[want]
            a["folder"] = lib_.ensure_path(d, start, a.pop("parts"))
            d["files"].append(a)
            r = lib_root_of(d, a["folder"])
            if r in ("voice", "music"):
                lib_audio_link(bid, a, r)
        d["audio_seen"] = sorted(set(d.get("audio_seen") or []) | {a["audio_id"] for a in added if a.get("audio_id")})
    lib_update(fn, bid)
    threading.Thread(target=run_library_tag, args=(bid, [a["id"] for a in added if not a.get("_to")]), daemon=True).start()
    away = [a for a in added if a.get("_to")]
    if away:
        dst = me if bid == SHARED_LIB else SHARED_LIB
        for a in away:
            shutil.move(str(folder_dir / a["file"]), str(lib_dir(dst) / a["file"]))
        def fn2(d):
            roots = lib_prepare(d)
            for a in away:
                want = a.pop("_to")
                a["folder"] = lib_.ensure_path(d, roots[want], a.pop("parts")) or roots[want]
                d["files"].append(a)
                if want in ("voice", "music"):
                    lib_audio_link(dst, a, want)
            d["audio_seen"] = sorted(set(d.get("audio_seen") or []) | {a["audio_id"] for a in away if a.get("audio_id")})
        lib_update(fn2, dst)
        threading.Thread(target=run_library_tag, args=(dst, [a["id"] for a in away]), daemon=True).start()
    return lib_view(me)


def run_library_tag(bid: str, ids: list[str]) -> None:
    """🧠 العقل يشاهد كل ملف ويكتب وصف وتاجات (يُخصم على قدر الذي أُنشئ)."""
    folder = lib_dir(bid)
    for i in ids:
        lib = lib_load(bid)
        f = next((x for x in lib["files"] if x["id"] == i), None)
        if not f or f.get("status") != "tagging":
            continue
        path, where, upd = folder / f["file"], lib_.path_text(lib, f.get("folder")), {}
        try:
            if f["kind"] == "video":   # صورة صغيرة من النص (للمكتبة وللوصف)
                th = folder / f"th_{f['id']}.jpg"
                typo_frame(path, (f.get("dur") or 1) / 2, th, 480)
                upd["thumb"] = th.name
            if atlas.mock_mode() or not atlas.api_key():
                desc, tags = lib_.mock_tags(f["name"], where)
            else:
                wallet.need(1, "توصيف ملفات المكتبة")
                if f["kind"] == "audio":
                    words = atlas.transcribe(path, min(60.0, f.get("dur") or 60))
                    said = " ".join(w["w"] for w in words or [])[:1200]
                    raw = ad_json(series_chat(lib_.tag_messages("audio", f["name"], where, f"النص الذي فيه: «{said or 'لا يوجد نص'}» · مدته {f.get('dur') or 0} ثانية")), "توصيف ملف")
                    usd = wallet.est(chars=4000, stt_min=min(1.0, (f.get('dur') or 60) / 60))
                else:
                    img = folder / (upd.get("thumb") or f["file"])
                    small = TMP_DIR / f"libtag_{f['id']}.jpg"
                    typo_frame(img, 0, small, 640) if f["kind"] == "image" and img.suffix.lower() != ".gif" else shutil.copy(img, small)
                    extra = f"ده فريم من نص فيديو مدته {f.get('dur') or 0} ثانية." if f["kind"] == "video" else ""
                    try:
                        raw = ad_json(lab_media_chat(az.with_media(lib_.tag_messages(f["kind"], f["name"], where, extra), data_url(small, "image/jpeg"), "image.jpg")), "توصيف ملف")
                    finally:
                        small.unlink(missing_ok=True)
                    usd = wallet.est(chars=3000, images=1)
                desc, tags = lib_.clean_tags(raw)
                wallet.charge(wallet.credits(usd), "توصيف ملف في المكتبة", f["id"])
            upd.update(desc=desc, tags=tags, status="ready", error=None)
        except wallet.NoCredits as exc:
            upd.update(status="ready", error=str(exc)[:200])
        except Exception as exc:  # noqa: BLE001
            upd.update(status="ready", error=str(getattr(exc, "detail", None) or exc)[:200])
        lib_update(lambda d, i=i, upd=upd: next((x.update(upd) for x in d["files"] if x["id"] == i), None), bid)


class LibFilePatch(BaseModel):
    name: str | None = None
    desc: str | None = None
    tags: list[str] | None = None
    folder: str | None = None
    move: bool = False


@app.patch("/api/library/files/{fid}")
def library_file_patch(fid: str, body: LibFilePatch):
    me = active_client_id()
    bid = lib_store_of(fid, me)
    if body.move and body.folder and lib_store_of(body.folder, me) != bid:
        raise HTTPException(400, "هذا المجلد في مكتبة متشاركة والآخر لا، لا يصلح تنقل بينهم")
    def fn(d):
        f = next((x for x in d["files"] if x["id"] == fid), None)
        if not f:
            raise HTTPException(404, "هذا الملف غير موجود")
        if body.name is not None:
            f["name"] = lib_.clean_name(body.name, f["name"])
        if body.desc is not None:
            f["desc"] = body.desc.strip()[:300]
        if body.tags is not None:
            f["desc"], f["tags"] = lib_.clean_tags({"desc": f.get("desc"), "tags": body.tags})
        if body.move:
            if body.folder and not any(x["id"] == body.folder for x in d["folders"]):
                raise HTTPException(404, "هذا المجلد غير موجود")
            f["folder"] = body.folder or None
            lib_prepare(d)
        if f.get("audio_id"):   # مكتبة الصوت بتتحدّث معاه (الاسم، وتعليق ولا موسيقى)
            r = lib_root_of(d, f.get("folder"))
            with closing(db()) as conn, conn:
                conn.execute("UPDATE audio SET name = ?, kind = COALESCE(?, kind) WHERE id = ?", (f["name"], r if r in ("voice", "music") else None, f["audio_id"]))
    lib_update(fn, bid)
    return lib_view(me)


