@app.delete("/api/library/files/{fid}")
def library_file_delete(fid: str):
    me = active_client_id()
    bid = lib_store_of(fid, me)
    gone = []
    def fn(d):
        gone.extend(x for x in d["files"] if x["id"] == fid)
        d["files"] = [x for x in d["files"] if x["id"] != fid]
    lib = lib_update(fn, bid)
    for f in gone:
        for n in (f.get("file"), f.get("thumb")):
            if n:
                (lib_dir(bid) / Path(n).name).unlink(missing_ok=True)
        if f.get("audio_id"):
            try:
                delete_audio(f["audio_id"])
            except HTTPException:
                pass
    return lib_view(me)


@app.get("/api/library/search")
def library_search(q: str = "", kind: str = "", ref: str = ""):
    """🔎 بحث (بالاسم والوصف والتاجات)، أو إشارة: ref = «صور/أسنان/قبل» (مجلد) أو مسار ملف بعينه."""
    bid = active_client_id()
    lib = lib_merged(bid, ready=False)
    folder = None
    if ref:
        folder, f = lib_.resolve(lib, ref)
        if f:
            return {"ref": ref, "folder": folder, "files": [lib_file_dict(lib, f, bid)]}
        if folder is None:
            return {"ref": ref, "folder": None, "files": [], "error": "غير لاقي هذا المجلد"}
    hits = lib_.search(lib, q, kind if kind in lib_.KINDS else "", folder)
    return {"ref": ref, "folder": folder, "files": [lib_file_dict(lib, f, bid) for f in hits[:200]]}


# ---------------------------------------------------------------- 🤖 القالب المخصص: خطوات بأفعال ومنشن من المكتبة ← مشروع مونتاج
AUTO_LOCK = threading.Lock()
AUTO_CANVAS = {"9:16": (1080, 1920), "1:1": (1080, 1080), "4:5": (1080, 1350), "16:9": (1920, 1080)}


def auto_dir(bid: str | None = None) -> Path:
    d = brain_dir(bid or active_client_id() or "default") / "automations"
    d.mkdir(parents=True, exist_ok=True)
    return d


def auto_load(rid: str, bid: str | None = None) -> dict:
    f = auto_dir(bid) / f"{Path(rid).name}.json"
    if not f.exists():
        raise HTTPException(404, "هذا القالب غير موجود")
    return json.loads(f.read_text(encoding="utf-8"))


def auto_save(rid: str, d: dict, bid: str | None = None) -> None:
    d["updated_at"] = now()
    f = auto_dir(bid) / f"{Path(rid).name}.json"
    f.with_suffix(".tmp").write_text(json.dumps(d, ensure_ascii=False), encoding="utf-8")
    f.with_suffix(".tmp").replace(f)


def auto_update(rid: str, fn, bid: str | None = None) -> dict:
    with AUTO_LOCK:
        d = auto_load(rid, bid)
        fn(d)
        auto_save(rid, d, bid)
        return d


def auto_files(lib: dict, src: dict | None, kinds: tuple[str, ...]) -> list[dict]:
    """الملفات التي الإشارة يشاور عليها: مجلد (واللي جواه)، ملف بعينه، أو بحث بالمعنى."""
    if not src:
        return []
    if src["mode"] == "file":
        return [f for f in lib["files"] if f["id"] == src["id"] and f["kind"] in kinds]
    if src["mode"] == "search":
        return [f for f in lib_.search(lib, src["q"]) if f["kind"] in kinds]
    return [f for f in lib_.search(lib, "", "", src.get("id")) if f["kind"] in kinds]


def auto_kinds(s: dict) -> tuple[str, ...]:
    if s["verb"] != "pull":
        return automate.VERBS[s["verb"]]["accept"]
    t = s["opts"].get("type") or "image"
    return ("image", "video") if t == "any" else (t,)


def auto_src_files(lib: dict, s: dict, kinds: tuple[str, ...]) -> list[dict]:
    """ملفات الإشارة، وإذا فيه «قواعدي» تتفلتر بالمعنى (إذا لا يوجد أي ملف طابق يعود لكل الملفات، والتشغيل يقول هكذا)."""
    files = auto_files(lib, s.get("src"), kinds)
    rules = (s["opts"].get("rules") or "").strip()
    if rules and files:
        ids = {f["id"] for f in lib_.search(lib, rules)}
        hit = [f for f in files if f["id"] in ids]
        if hit:
            return hit
    return files


AUTO_STOCK_SUB = "🌐 من الستوك"
AUTO_STOCK_ROOT = {"image": "images", "video": "videos", "audio": "music"}


def auto_stock(bid: str, s: dict, kind: str, n: int, ratio: str, run_id: str, report: list[str]) -> list[dict]:
    """🌐 «ستوك»: صور وفيديوهات من Pexels، أو موسيقى مسموح استخدامها تجاريًا (Openverse). تتنزّل وتدخل المكتبة في «🌐 من الستوك»
    ومعها اسم صاحبها. ما اتاخد من قبل يُؤخذ من المكتبة مباشرة بدل ما يتنزّل مرة أخرى. كلمة البحث + «قواعدي» يتترجمون للإنجليزي."""
    o, n = s["opts"], max(1, min(12, int(n)))
    q = " ".join(x for x in ((s.get("src") or {}).get("q", ""), o.get("rules") or "") if x).strip()
    what = {"image": "صور", "video": "فيديوهات", "audio": "موسيقى"}[kind]
    lib = lib_merged(bid, ready=False)
    have = {f.get("stock_id"): f for f in lib["files"] if f.get("stock_id")}
    tmp = GENERATED_DIR / f"autostock_{run_id}_{s['id']}_{kind}"
    tmp.mkdir(parents=True, exist_ok=True)
    try:
        if atlas.mock_mode() and (kind == "audio" or not stock.live()):
            en, items = q, [{"id": f"mock{uuid.uuid4().hex[:6]}", "kind": kind, "file": "", "title": q, "author": "", "dur": 10 if kind == "audio" else 4} for _ in range(n)]
        else:
            if kind != "audio" and not stock.live():
                report.append("⚠️ مكتبة الصور والفيديوهات (Pexels) غير متاحة الآن، فـ«ستوك» اتخطّى")
                return []
            en = stock_query_en(q)
            orient = "portrait" if ratio in ("9:16", "4:5") else "landscape" if ratio == "16:9" else "square"
            items = stock.music_search(en) if kind == "audio" else [it for it in stock.search(en, "photo" if kind == "image" else "video", orient)["items"]
                                                                   if stock.allowed_url(it["file"]) and (kind == "image" or (it.get("dur") or 0) >= 2)]
        rnd = random.Random()
        rnd.shuffle(items)
        items.sort(key=lambda it: it["id"] in have)   # الجديد الأول، وبعدين اللي اتنزّل قبل كده
        out, made = [], []
        for it in items:
            if len(out) + len(made) >= n:
                break
            if it["id"] in have:
                out.append(have[it["id"]])
                continue
            ext = {"image": ".jpg", "video": ".mp4"}.get(kind) or f".{it.get('ext') or 'mp3'}"
            name = f"stock_{uuid.uuid4().hex[:10]}{ext}"
            dest = tmp / name
            if atlas.mock_mode() and not it["file"]:
                src = {"image": ["-f", "lavfi", "-i", f"color=c=0x{uuid.uuid4().hex[:6]}:s=720x1280", "-frames:v", "1"],
                       "video": ["-f", "lavfi", "-i", "testsrc2=size=720x1280:rate=30:duration=4", "-pix_fmt", "yuv420p", "-c:v", "libx264", "-preset", "veryfast"],
                       "audio": ["-f", "lavfi", "-i", "sine=frequency=330:duration=10"]}[kind]
                ok = subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", *src, str(dest)], capture_output=True, timeout=120).returncode == 0
            else:
                ok = brain_fetch(it["file"], dest, 200 * 1024 * 1024)
            if not ok or not dest.exists():
                dest.unlink(missing_ok=True)
                continue
            f = {"id": lib_.fid(), "file": name, "name": lib_.clean_name(f"🌐 {(it.get('title') or it.get('alt') or q)[:50]}"), "kind": kind, "size": dest.stat().st_size,
                 "desc": (it.get("alt") or it.get("title") or q)[:300], "tags": ["ستوك", en[:40]], "status": "ready", "at": now(), "origin": bid, "stock_id": it["id"],
                 "credit": {"by": (it.get("author") or "")[:120], "by_url": (it.get("author_url") or "")[:300], "page": (it.get("page") or "")[:300],
                            "src": "Openverse" if kind == "audio" else "Pexels", "license": (it.get("license") or "")[:60]}}
            for k in ("w", "h"):
                if it.get(k):
                    f[k] = it[k]
            dur = it.get("dur") or (probe_duration(dest) if kind != "image" else None)
            if dur:
                f["dur"] = float(dur)
            made.append(f)
        if made:
            out += auto_lib_add(bid, AUTO_STOCK_ROOT[kind], made, tmp, AUTO_STOCK_SUB)
        report.append(f"✓ ستوك «{q}»: {len(out)} {what}" + (f" ({len(made)} جديد حُفظ في «{AUTO_STOCK_SUB}»)" if made else "") if out
                      else f"⚠️ ستوك «{q}» مالقاش {what}. جرّب كلمة أخرى")
        return out
    except (stock.StockError, wallet.NoCredits) as exc:
        report.append(f"⚠️ ستوك «{q}»: {exc}")
        return []
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


