@app.post("/api/automations/{rid}/run")
def automation_run(rid: str, request: Request):
    """▶ شغّل: الخطوات تتحول لمشروع مونتاج جديد (يُفتح في المحرر أو يُصدّر مباشرة)."""
    bid = active_client_id()
    d = auto_load(rid, bid)
    if any(r.get("status") == "working" for r in d.get("runs") or []):
        raise HTTPException(400, "فيه تشغيل يعمل، انتظر ينتهي")
    if not any(s["verb"] in ("pull", "intro", "outro", "split", "genimg", "genvid", "frames") for s in d.get("steps") or []):
        raise HTTPException(400, "القالب يحتاج خطوة «اسحب» أو «ولّد صورة» أو «ولّد فيديو» أو «قطّع الفيديو»، على الأقل")
    run = {"id": uuid.uuid4().hex[:8], "at": now(), "status": "working", "step": "يبدأ…", "project_id": None, "report": [], "error": None}
    auto_update(rid, lambda x: x.update(runs=[run, *(x.get("runs") or [])][:20]), bid)
    port = (request.scope.get("server") or ("127.0.0.1", 8000))[1]
    threading.Thread(target=run_automation, args=(rid, run["id"], bid, port), daemon=True).start()
    return auto_to_dict(rid, auto_load(rid, bid), bid)


def auto_cache(bid: str) -> tuple[dict, Path]:
    f = auto_dir(bid) / "_cache.json"
    try:
        return (json.loads(f.read_text(encoding="utf-8")) if f.exists() else {}), f
    except ValueError:
        return {}, f


def auto_video_gen(bid: str, f: dict, cache: dict) -> str:
    """فيديو من المكتبة ← مكتبة فيديوهات المونتاج (مرة واحدة لكل ملف)."""
    k = f"vid:{f['id']}"
    if cache.get(k):
        return cache[k]
    src = lib_path(f, bid)
    dest = GENERATED_DIR / f"auto_{f['id']}{src.suffix.lower()}"
    if not dest.exists():
        shutil.copy(src, dest)
    cache[k] = phone_gen(dest, f"📁 {f['name']}")
    return cache[k]


def auto_image_gen(bid: str, f: dict, sec: float, ratio: str, cache: dict) -> str:
    """صورة ← لقطة فيديو بطولها، مالية الكادر وبزووم بطيء."""
    sec = round(max(0.6, sec) * 2) / 2
    k = f"img:{f['id']}:{sec}:{ratio}"
    if cache.get(k):
        return cache[k]
    W, H = AUTO_CANVAS.get(ratio, AUTO_CANVAS["9:16"])
    W, H = W * 2 // 3 // 2 * 2, H * 2 // 3 // 2 * 2   # 720 أسرع، والمونتاج بيكبّر
    n = int(sec * 30)
    dest = GENERATED_DIR / f"auto_{f['id']}_{int(sec * 10)}_{ratio.replace(':', 'x')}.mp4"
    subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-loop", "1", "-i", str(lib_path(f, bid)), "-t", f"{sec:.2f}",
                    "-vf", f"scale={W * 2}:{H * 2}:force_original_aspect_ratio=increase,crop={W * 2}:{H * 2},"
                           f"zoompan=z='1+0.06*on/{max(1, n)}':x='iw/2-(iw/zoom/2)':y='ih/2-(ih/zoom/2)':d=1:s={W}x{H}:fps=30,format=yuv420p",
                    "-r", "30", "-c:v", "libx264", "-preset", "veryfast", "-crf", "20", str(dest)], check=True, capture_output=True, timeout=300)
    cache[k] = phone_gen(dest, f"📁 {f['name']}")
    return cache[k]


def auto_audio_id(bid: str, f: dict, kind: str, cache: dict) -> tuple[str, float]:
    k = f"aud:{f['id']}:{kind}"
    if cache.get(k):
        with closing(db()) as conn:
            r = conn.execute("SELECT duration FROM audio WHERE id = ?", (cache[k],)).fetchone()
        if r:
            return cache[k], float(r["duration"])
    src = lib_path(f, bid)
    aid = uuid.uuid4().hex[:12]
    name = f"{kind}_{aid}{src.suffix.lower()}"
    shutil.copy(src, AUDIO_DIR / name)
    dur = probe_duration(AUDIO_DIR / name)
    with closing(db()) as conn, conn:
        conn.execute("INSERT INTO audio (id, kind, name, filename, duration, created_at) VALUES (?, ?, ?, ?, ?, ?)",
                     (aid, kind, f["name"][:80], name, dur, now()))
    cache[k] = aid
    return aid, dur


def auto_cut_spans(src: Path, dur: float, s: dict, run_id: str, report: list[str]) -> list[tuple[float, float]]:
    """مكان القطع: إذا كاتب «يحتاج ماذا في التقطيع» العقل يسمع النص ويختار، وإلا قطع متساوية متزقوقة على أماكن السكوت."""
    mx, note = float(s["opts"].get("max") or 15), (s["opts"].get("note") or "").strip()
    base = automate.even_spans(dur, mx)
    has_audio = media_info(src).has_audio
    if note and not atlas.mock_mode() and atlas.api_key():
        try:
            words = []
            if has_audio:
                wallet.need(wallet.credits(wallet.est(chars=6000, stt_min=dur / 60)), "تقطيع الفيديو")
                audio = TMP_DIR / f"autosplit_{run_id}.m4a"
                subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", str(src), "-vn", "-ac", "1", "-c:a", "aac", "-b:a", "96k", str(audio)],
                               check=True, capture_output=True, timeout=300)
                try:
                    words = atlas.transcribe(audio, dur) or []
                finally:
                    audio.unlink(missing_ok=True)
            spans = automate.clean_spans(dict_chat(automate.split_messages(note, words, dur, mx)), dur, mx)
            wallet.charge(wallet.credits(wallet.est(chars=6000, stt_min=dur / 60 if has_audio else 0)), "قالب مخصص: التقطيع على حسب طلبك", run_id)
            if spans:
                report.append(f"✂️ قطّع على حسب «{note[:60]}»")
                return spans
        except wallet.NoCredits:
            raise
        except Exception as exc:  # noqa: BLE001 — لو المخ مارجعش حاجة نافعة بنقطع بالتساوي
            report.append(f"⚠️ التقطيع الذكي ماشتغلش ({str(getattr(exc, 'detail', None) or exc)[:80]})، فقطّع بالتساوي")
    return automate.snap_quiet(base, silences(src) if has_audio else [], mx)


def auto_ref_audio(r: dict | None, src: Path | None, tmp: Path) -> Path | None:
    """إشارة صوت ← ملف: صوت شخصية، صوتك من «نسختي»، تعليق/موسيقى من المكتبة، أو صوت القطعة نفسها."""
    if not r:
        return None
    k, rid = r.get("kind"), str(r.get("id") or "")
    try:
        if k == "piece_audio" and src:
            out = tmp / "piece.m4a"
            subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", str(src), "-vn", "-c:a", "aac", "-b:a", "160k", str(out)],
                           check=True, capture_output=True, timeout=120)
            return out if out.exists() and out.stat().st_size > 1000 else None
        if k != "audio":
            return None
        if rid.startswith("cv:"):
            with closing(db()) as conn:
                row = conn.execute("SELECT voice_filename FROM coaches WHERE id = ?", (rid[3:],)).fetchone()
            return COACHES_DIR / row["voice_filename"] if row and row["voice_filename"] else None
        if rid.startswith("tv:"):
            v = (twin_load(rid[3:]).get("voice") or {}).get("file")
            return twin_dir(rid[3:]) / v if v else None
        if rid.startswith("lib:"):
            f = next((x for x in lib_merged(active_client_id(), ready=False)["files"] if x["id"] == rid[4:]), None)
            return lib_path(f, active_client_id()) if f else None
    except (subprocess.SubprocessError, OSError, KeyError, ValueError, HTTPException):
        return None
    return None


@wallet.covering   # بتخصم بنفسها
def auto_gen_piece(src: Path, dur: float, g: dict, dest: Path, run_id: str, ratio: str) -> str:
    """«ولّد»: الوصف + ما النموذج ياخده (القطعة نفسها، أو صورة بداية/نهاية، أو مراجع من الإشارة) ← فيديو جديد، والخصم على قدر الثواني."""
    o = g["opts"]
    prompt = (o.get("prompt") or "").strip()
    ms = auto_gen_models()
    cand = next((m for m in ms if m["model"] == o.get("model")), None) or (ms[0] if ms else None)
    if not cand:
        raise RuntimeError("لا يوجد نموذج توليد فيديو متاح على Atlas الآن")
    mode = cand.get("mode") or ("video" if cand.get("kind") == "edit" else "refs")
    if not prompt and mode != "lipsync":
        raise RuntimeError("خطوة «ولّد» بدون وصف")
    tmp = GENERATED_DIR / f"autoref_{run_id}_{g['id']}"
    tmp.mkdir(parents=True, exist_ok=True)
    try:
        refs = [(r, p) for r in o.get("refs") or [] if (p := auto_ref_image(r, src, tmp)) and p.exists()]
        # المنشن في البرومبت بيتحول لرقم المرجع علشان الموديل يعرف مين مين
        if mode in ("refs", "video"):
            for i, (r, _) in enumerate(refs):
                if r.get("label"):
                    prompt = prompt.replace(f"@{r['label']}", f"{r['label']} (reference image {i + 1})")
        prompt = re.sub(r"@(?=\S)", "", prompt)   # أي منشن تاني بيفضل اسم عادي
        if (o.get("rules") or "").strip():   # «قواعدي» بتتضاف للبرومبت
            prompt = (prompt + "\nRules: " + o["rules"].strip()).strip()
        pick = lambda key, fallback: (auto_ref_image(o[key], src, tmp) if o.get(key) else None) or fallback  # noqa: E731
        start = pick("start", refs[0][1] if refs else auto_ref_image({"kind": "frame"}, src, tmp)) if mode in ("image", "startend", "avatar") else None
        voice = auto_ref_audio(o.get("audio") or ({"kind": "piece_audio"} if mode == "avatar" else None), src, tmp) if mode in ("avatar", "lipsync") else None
        if mode in ("avatar", "lipsync") and not voice:
            raise RuntimeError("هذا النموذج يحتاج صوت: اختر صوت من «الصوت» (صوت شخصية، صوتك، أو تعليق من المكتبة)")
        end = pick("end", refs[1][1] if len(refs) > 1 else None) if mode == "startend" else None
        if mode == "refs" and not refs and not (cand.get("video_in") and o.get("use_piece", True)):
            raise RuntimeError("هذا النموذج يشتغل بمراجع: إشارة شخصية أو خلفية أو صورة (@)")
        if mode == "startend" and not end:
            raise RuntimeError("هذا النموذج يحتاج صورة نهاية: اخترها من «صورة النهاية»")
        if voice:   # الأفاتار والليب سينك: الفيديو على قد الصوت
            dur = probe_duration(voice) or dur
        if atlas.mock_mode():
            subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", str(src), "-vf", "hue=h=140:s=1.6,eq=contrast=1.15",
                            "-c:a", "copy", str(dest)], check=True, capture_output=True, timeout=300)
            return f"{cand['label']} · {GEN_MODE_T.get(mode, mode)}" + (f" · {len(refs)} مرجع" if refs else "") + (" · بصوت" if voice else "")
        cost = wallet.credits((cand.get("per_sec") or 0.3) * dur * (2 if mode == "refs" and cand.get("video_in") else 1))
        wallet.need(cost, "توليد قطعة فيديو")
        imgs = [atlas.upload_media(seedance_ref(p)) for _, p in refs]
        secs = max(4, round(dur))
        if mode == "avatar":
            img = atlas.upload_media(seedance_ref(start))
            body = {"model": cand["model"], "image": img, "image_url": img, "audio": atlas.upload_media(voice), "audio_url": atlas.upload_media(voice),
                    "prompt": prompt + " Lips perfectly synced to the audio, natural blinking and subtle head movement. Keep the face, outfit and background as in the image."}
        elif mode == "lipsync":
            vurl, aurl = atlas.upload_media(src), atlas.upload_media(voice)
            body = {"model": cand["model"], "video_url": vurl, "audio_url": aurl, "video": vurl, "audio": aurl}
        elif mode == "video":
            body = vmodels.camera_body({**cand, "kind": cand.get("kind") or "edit"}, atlas.upload_media(src), prompt, dur, ratio, images=imgs or None)
        else:
            body = {"model": cand["model"], "prompt": prompt, "duration": secs, "ratio": ratio, "resolution": "720p"}
            if mode == "refs":
                body["reference_images"] = imgs[:4]
                if cand.get("video_in") and o.get("use_piece", True):
                    body["reference_videos"] = [atlas.upload_media(src)]
            elif mode in ("image", "startend"):
                body["image"] = atlas.upload_media(seedance_ref(start))
                if end:
                    body["last_image"] = atlas.upload_media(seedance_ref(end))
        atlas.download(atlas.run_model("Video", body, cand["label"], max_seconds=2400, interval=6), dest)
        wallet.charge(cost, f"قالب مخصص: توليد قطعة ({cand['label']})", run_id)
        return cand["label"]
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


AUTO_VID_MODES = ("text", "refs", "image", "startend", "avatar")   # «ولّد فيديو» في الخط الأساسي: من غير قطعة


def auto_vid_models() -> list[dict]:
    """النماذج التي لا تحتاج قطعة، و«من النص» أولًا (الافتراضي يشتغل بالبرومبت فقط)."""
    return sorted((m for m in auto_gen_models() if (m.get("mode") or "") in AUTO_VID_MODES), key=lambda m: AUTO_VID_MODES.index(m["mode"]))


def auto_gen_video(bid: str, s: dict, ratio: str, run_id: str, report: list[str]) -> list[dict]:
    """«ولّد فيديو»: الوصف (والمراجع/الصورة/الصوت على حسب النموذج) ← فيديو أو أكثر، يدخل الفيديو ويُحفظ في المكتبة."""
    ms = auto_vid_models()
    if not ms:
        raise RuntimeError("لا يوجد نموذج توليد فيديو متاح الآن")
    o = s["opts"]
    m = next((x for x in ms if x["model"] == o.get("model")), ms[0])
    g = {**s, "opts": {**o, "model": m["model"], "use_piece": False}}
    tmp = GENERATED_DIR / f"autovid_{run_id}_{s['id']}"
    tmp.mkdir(parents=True, exist_ok=True)
    try:
        made = []
        for i in range(max(1, min(4, int(o.get("count") or 1)))):
            name = f"gen_{uuid.uuid4().hex[:10]}.mp4"
            dest = tmp / name
            if atlas.mock_mode():
                W, H = AUTO_CANVAS.get(ratio, AUTO_CANVAS["9:16"])
                subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-f", "lavfi", "-i", f"testsrc2=size={W // 2}x{H // 2}:rate=30:duration={float(o.get('sec') or 5)}",
                                "-pix_fmt", "yuv420p", "-c:v", "libx264", "-preset", "veryfast", str(dest)], check=True, capture_output=True, timeout=300)
                label = f"{m['label']} · {GEN_MODE_T.get(m.get('mode'), '')}"
            else:
                label = auto_gen_piece(None, float(o.get("sec") or 5), g, dest, run_id, ratio)
            dur = probe_duration(dest) or float(o.get("sec") or 5)
            made.append({"id": lib_.fid(), "file": name, "name": lib_.clean_name(f"✨ {o.get('prompt', '')[:40]}"), "kind": "video", "size": dest.stat().st_size, "dur": dur,
                         "desc": o.get("prompt", "")[:300], "tags": ["وُلّدت"], "status": "ready", "at": now(), "origin": bid})
        report.append(f"✓ وُلّد {len(made)} فيديو ({label})")
        return auto_lib_add(bid, "videos", made, tmp)
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


FRAME_MODELS = ["google/gemini-2.5-flash-lite", "google/gemini-3.1-flash-lite", "google/gemini-2.5-flash"]   # رخاص وبيشوفوا صور كويس
AUTO_FRAMES_SUB = "🎯 فريمات مختارة"


def auto_pick_frames(bid: str, s: dict, f: dict, ratio: str, run_id: str, report: list[str]) -> list[dict]:
    """«اختر الفريمات»: فريم كل ثانية (صغير) ← نموذج رخيص يقول أي فريمات فيها الوصف ← هذه الفريمات بجودة كاملة (أو لقطات قصيرة حواليها).
    التكلفة على قدر عدد الفريمات (فيديو دقيقة ≈ أقل من سنت)."""
    o = s["opts"]
    want = (o.get("want") or "").strip()
    if not want:
        report.append("⚠️ «اختر الفريمات» بدون وصف للي تريده، فاتخطّت")
        return []
    src = lib_path(f, bid)
    dur = float(f.get("dur") or probe_duration(src) or 0)
    if dur <= 0:
        report.append(f"⚠️ تعذّر ذلك أعرف طول «{f['name']}»")
        return []
    step = max(1.0, dur / 120)   # لحد ١٢٠ فريم للفيديو الطويل
    tmp = GENERATED_DIR / f"autofr_{run_id}_{s['id']}"
    tmp.mkdir(parents=True, exist_ok=True)
    try:
        subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-i", str(src), "-vf", f"fps=1/{step:.3f},scale=384:-2", "-q:v", "5", str(tmp / "s_%04d.jpg")],
                       capture_output=True, timeout=600)
        shots = sorted(tmp.glob("s_*.jpg"))
        if not shots:
            report.append(f"⚠️ تعذّر ذلك أطلّع فريمات من «{f['name']}»")
            return []
        times = [round(i * step, 2) for i in range(len(shots))]
        keep: list[int] = []
        meter = {"usd": 0.0}
        if atlas.mock_mode():
            keep = list(range(0, len(shots), 3))
        else:
            wallet.need(max(1, wallet.credits(len(shots) * 0.0001 + 0.002)), "اختيار الفريمات")
            for a in range(0, len(shots), 40):
                parts = [{"type": "text", "text": (f"These are {len(shots[a:a + 40])} frames from a video, numbered from {a}. "
                                                   f"Which frames clearly show: «{want}»? Be strict: only frames that really match. "
                                                   'Reply JSON only: {"keep": [frame numbers]}')}]
                for i, p in enumerate(shots[a:a + 40]):
                    parts += [{"type": "text", "text": f"Frame {a + i}:"}, {"type": "image_url", "image_url": {"url": data_url(p, "image/jpeg")}}]
                raw = ad_json(ad_media_chat([{"role": "user", "content": parts}], 2000, models=FRAME_MODELS, meter=meter), "اختيار الفريمات")
                keep += [int(x) for x in raw.get("keep") or [] if isinstance(x, (int, float)) and a <= int(x) < a + 40]
            wallet.charge(max(1, wallet.credits(meter["usd"] or len(shots) * 0.0001)), f"قالب مخصص: اختيار الفريمات ({len(shots)} فريم)", run_id)
        keep = sorted(set(keep))
        if not keep:
            report.append(f"⚠️ «اختر الفريمات»: لم أجد «{want[:40]}» في «{f['name']}»")
            return []
        n = max(1, min(20, int(o.get("count") or 6)))
        made = []
        if o.get("out") == "clips":   # الثواني اللي ورا بعض بتبقى لقطة واحدة
            spans = []
            for i in keep:
                t0, t1 = max(0.0, times[i] - step / 2), min(dur, times[i] + step / 2)
                if spans and t0 <= spans[-1][1] + 0.05:
                    spans[-1][1] = t1
                else:
                    spans.append([t0, t1])
            spans = sorted(spans, key=lambda x: x[1] - x[0], reverse=True)[:n]
            for t0, t1 in sorted(spans):
                t1 = max(t1, min(dur, t0 + 1.0))
                name = f"pick_{uuid.uuid4().hex[:10]}.mp4"
                r = subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-ss", f"{t0:.2f}", "-i", str(src), "-t", f"{t1 - t0:.2f}",
                                    "-vf", "format=yuv420p", "-c:v", "libx264", "-preset", "veryfast", "-crf", "20", "-c:a", "aac", str(tmp / name)], capture_output=True, timeout=300)
                if r.returncode == 0 and (tmp / name).exists():
                    made.append({"id": lib_.fid(), "file": name, "name": lib_.clean_name(f"🎯 {want[:30]} {t0:.0f}s"), "kind": "video", "size": (tmp / name).stat().st_size,
                                 "dur": round(t1 - t0, 2), "desc": f"{want[:200]} · من «{f['name']}»", "tags": ["فريمات مختارة"], "status": "ready", "at": now(), "origin": bid})
        else:
            if len(keep) > n:   # متوزعين على طول الفيديو
                keep = [keep[round(i * (len(keep) - 1) / (n - 1))] for i in range(n)] if n > 1 else keep[:1]
            for i in keep:
                name = f"pick_{uuid.uuid4().hex[:10]}.jpg"
                r = subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-ss", f"{times[i]:.2f}", "-i", str(src), "-frames:v", "1", "-q:v", "2", str(tmp / name)],
                                   capture_output=True, timeout=120)
                if r.returncode == 0 and (tmp / name).exists():
                    made.append({"id": lib_.fid(), "file": name, "name": lib_.clean_name(f"🎯 {want[:30]} {times[i]:.0f}s"), "kind": "image", "size": (tmp / name).stat().st_size,
                                 "desc": f"{want[:200]} · من «{f['name']}»", "tags": ["فريمات مختارة"], "status": "ready", "at": now(), "origin": bid})
        report.append(f"✓ «اختار الفريمات»: {len(made)} {'لقطة' if o.get('out') == 'clips' else 'فريم'} فيها «{want[:40]}» من {len(shots)} اتشافوا (والباقي اتشال)")
        return auto_lib_add(bid, "videos" if o.get("out") == "clips" else "images", made, tmp, AUTO_FRAMES_SUB) if made else []
    finally:
        shutil.rmtree(tmp, ignore_errors=True)


def auto_run_split(bid: str, s: dict, merge: dict | None, f: dict, ratio: str, run_id: str, setr, report: list[str]) -> list[dict]:
    """قطّع ← كل قطعة تسير في مسارها (ولّد…) ← جمّع المخرجات المختارة بالترتيب. يعود لقطات للمونتاج."""
    src = lib_path(f, bid)
    dur = float(f.get("dur") or probe_duration(src))
    setr(step=f"✂️ يقطّع «{f['name']}»")
    spans = auto_cut_spans(src, dur, s, run_id, report)
    lanes = s.get("lanes") or [[]]
    outs: dict[tuple[int, str], tuple[Path, float]] = {}
    last: list[tuple[int, str]] = []
    for i, (a, b) in enumerate(spans):
        piece = GENERATED_DIR / f"autosplit_{run_id}_{i}.mp4"
        subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", "-ss", f"{a:.2f}", "-to", f"{b:.2f}", "-i", str(src),
                        "-c:v", "libx264", "-preset", "veryfast", "-crf", "19", "-c:a", "aac", "-b:a", "160k", "-movflags", "+faststart", str(piece)],
                       check=True, capture_output=True, timeout=600)
        outs[(i, "piece")] = (piece, b - a)
        cur, cur_key = piece, (i, "piece")
        for g in automate.lane_for(lanes, i):
            if g["verb"] != "gen":
                continue
            setr(step=f"✨ يولّد القطعة {i + 1} من {len(spans)}")
            dest = GENERATED_DIR / f"autogen_{run_id}_{i}_{g['id']}.mp4"
            try:
                label = auto_gen_piece(cur, b - a, g, dest, run_id, ratio)
                outs[(i, g["id"])] = (dest, probe_duration(dest) or (b - a))
                cur, cur_key = dest, (i, g["id"])
                report.append(f"✓ القطعة {i + 1}: وُلّدت ({label})")
            except wallet.NoCredits:
                raise
            except Exception as exc:  # noqa: BLE001 — قطعة واحدة فشلت: بنكمّل بالأصل بتاعها
                report.append(f"⚠️ القطعة {i + 1}: التوليد فشل ({str(getattr(exc, 'detail', None) or exc)[:90]})، فوُضعت كما هي")
        last.append(cur_key)
    items = [(it["lane"], it["node"]) for it in ((merge or {}).get("opts") or {}).get("items") or []]
    chosen = [k for k in items if k in outs] or last
    if items and len(chosen) < len(items):
        report.append(f"⚠️ «جمّع»: {len(items) - len(chosen)} من المخرجات التي اخترتها غير موجودة في هذا التشغيل (عدد القطع طلع {len(spans)})")
    report.append(f"✂️ {len(spans)} قطعة · اتجمّع منهم {len(chosen)} في فيديو واحد")
    Wc, Hc = AUTO_CANVAS.get(ratio, AUTO_CANVAS["9:16"])
    clips = []
    for lane, node in chosen:
        path, L = outs[(lane, node)]
        info = media_info(path)
        ok = info.width and info.height and abs(info.width / info.height - Wc / Hc) < 0.08
        clips.append({"gen_id": phone_gen(path, f"✂️ قطعة {lane + 1}" + ("" if node == "piece" else " ✨")), "start": 0, "end": None,
                      "fit": "fill" if ok else "blur", "_dur": L})
    return clips


def auto_export_publish(pid: str, steps: list[dict], name: str, port: int, setr, report: list[str]) -> None:
    """صدّر (مثل زر التصدير في المونتاج) وانتظر ينتهي، ثم انشر إذا الخطوة تقول «مباشرة»."""
    setr(step="🎬 يصدّر الفيديو")
    with closing(db()) as conn, conn:
        row = get_project(conn, pid)
        data = json.loads(row["data"])
        cw, ch, fps, crf = export_settings(data)
        with montage.canvas(cw, ch, fps, crf):
            start_render(conn, row, pid, data, SimpleNamespace(scope={"server": ("127.0.0.1", port)}))
    t0 = time.time()
    while time.time() - t0 < 1800:
        time.sleep(3)
        with closing(db()) as conn:
            r = conn.execute("SELECT render_status, render_error, export_id FROM projects WHERE id = ?", (pid,)).fetchone()
        if r["render_status"] != "rendering":
            break
    if r["render_status"] == "rendering" or r["render_error"] or not r["export_id"]:
        raise RuntimeError(f"التصدير فشل: {r['render_error'] or 'خذ وقت أطول من اللازم'}")
    report.append("✓ صُدّر")
    pub = next((s["opts"] for s in steps if s["verb"] == "publish"), {})
    if pub.get("when") != "now" or not pub.get("platforms"):
        report.append("⏸ النشر مستني موافقتك: الفيديو في صفحة النشر" if pub.get("when") != "now" else "⚠️ مفيش حسابات متختارة في «انشر»")
        return
    setr(step="📣 ينشر")
    caption = pub.get("caption") or name
    post = create_post(PostIn(export_id=r["export_id"], caption=caption, platforms=pub["platforms"], scheduled_at=datetime.now(timezone.utc)))
    report.append(f"✓ أُرسل للنشر على {len(post.get('platforms') or pub['platforms'])} حساب")


def run_automation(rid: str, run_id: str, bid: str, port: int = 8000) -> None:
    def setr(**kw):
        def fn(x):
            for r in x.get("runs") or []:
                if r["id"] == run_id:
                    r.update(**kw)
        auto_update(rid, fn, bid)
    report: list[str] = []
    try:
        d = auto_load(rid, bid)
        lib, (cache, cache_f) = lib_merged(bid, ready=False), auto_cache(bid)
        rnd, used = random.Random(), dict(d.get("used") or {})
        steps = automate.clean_steps(d.get("steps") or [])
        opt = lambda verb: next((s["opts"] for s in steps if s["verb"] == verb), None)  # noqa: E731
        ratio = (opt("export") or {}).get("ratio", "9:16")
        cut = opt("cut") or {}
        cap = float(cut.get("max") or 0) or None
        trans = cut.get("trans") or ""
        picked: list[dict] = []
        voice = music = None
        intro = outro = None
        split_f = None
        setr(step="📁 يختار من المكتبة")
        def take(s: dict, kinds: tuple[str, ...], n: int, order: str) -> tuple[list[dict], bool]:
            """من الستوك أونلاين (يتنزّل ويُحفظ في المكتبة) أو من ملفات الإشارة في المكتبة."""
            if (s.get("src") or {}).get("mode") == "stock":
                setr(step="🌐 يجلب من الستوك")
                if "audio" in kinds:
                    return auto_stock(bid, s, "audio", 1, ratio, run_id, report), False
                parts = [("image", (n + 1) // 2), ("video", n // 2)] if len(kinds) == 2 else [(kinds[0], n)]
                return [f for k, c in parts if c for f in auto_stock(bid, s, k, c, ratio, run_id, report)], False
            if (s["opts"].get("rules") or "").strip():
                files = auto_files(lib, s.get("src"), kinds)
                ids = {f["id"] for f in lib_.search(lib, s["opts"]["rules"])}
                if files and not any(f["id"] in ids for f in files):
                    report.append(f"⚠️ «{automate.VERBS[s['verb']]['t']}»: لا يوجد ملف طابق قواعدك «{s['opts']['rules'][:40]}»، فاختر من الكل")
            return automate.pick(auto_src_files(lib, s, kinds), n, order, used, rnd)
        for s in steps:
            v, o = s["verb"], s["opts"]
            if v == "split":
                got, _ = take(s, ("video",), 1, o.get("order") or "fresh")
                if not got:
                    report.append(f"⚠️ «قطّع الفيديو» مالقاش فيديو في «{(s.get('src') or {}).get('label') or 'المكتبة'}»")
                    continue
                split_f = got[0]
                report.append(f"✓ الفيديو الذي سيُقطّع: {got[0]['name']}")
            elif v == "merge":
                if split_f:
                    picked.append({"split": s, "merge": next((x for x in steps if x["verb"] == "merge"), None), "f": split_f})
            elif v == "pull":
                kinds = auto_kinds(s)
                got, wrapped = take(s, kinds, 1 if kinds == ("audio",) else int(o.get("count") or 1), o.get("order") or "fresh")
                if got and kinds == ("audio",):   # اسحب صوت: يا تعليق صوتي (الفيديو على قده) يا موسيقى تحت الفيديو
                    if o.get("role") == "voice":
                        voice = {"f": got[0], "fit": True}
                    else:
                        music = {"f": got[0], "volume": int(o.get("volume") or 35), "duck": bool(o.get("duck", True))}
                    report.append(f"✓ {'التعليق' if o.get('role') == 'voice' else 'الموسيقى'}: {got[0]['name']}")
                    continue
                if not got:
                    report.append(f"⚠️ «اسحب» مالقاش {lib_.KINDS.get(kinds[0], 'ملفات')} في «{(s.get('src') or {}).get('label') or 'المكتبة'}»")
                    continue
                if wrapped:
                    report.append(f"🔁 «{(s.get('src') or {}).get('label') or 'المكتبة'}» خلص، فبدأ من أولًا")
                picked += [{"f": f, "sec": float(o.get("sec") or 2.5)} for f in got]
                report.append(f"✓ سحب {len(got)} من «{(s.get('src') or {}).get('label') or 'المكتبة'}»")
            elif v in ("intro", "outro"):
                got, _ = take(s, ("video",), 1, "random") if (s.get("src") or {}).get("mode") == "stock" else automate.pick(auto_src_files(lib, s, ("video",)), 1, "random", {}, rnd)
                if got:
                    if v == "intro":
                        intro = got[0]
                    else:
                        outro = got[0]
                    report.append(f"✓ {'الإنترو' if v == 'intro' else 'الأوترو'}: {got[0]['name']}")
            elif v == "genvid":
                setr(step="🎬 يولّد الفيديو")
                picked += [{"f": f, "sec": float(f.get("dur") or o.get("sec") or 5)} for f in auto_gen_video(bid, s, ratio, run_id, report)]
            elif v == "frames":
                got, _ = take(s, ("video",), 1, o.get("order") or "fresh")
                if not got:
                    report.append(f"⚠️ «اختر الفريمات» مالقاش فيديو في «{(s.get('src') or {}).get('label') or 'المكتبة'}»")
                    continue
                setr(step="🎯 يشاهد على الفيديو ويختار الفريمات")
                picked += [{"f": f, "sec": float(o.get("sec") or 2.5)} for f in auto_pick_frames(bid, s, got[0], ratio, run_id, report)]
            elif v == "genimg":
                setr(step="🖼️ يولّد الصور")
                picked += [{"f": f, "sec": float(o.get("sec") or 2.5)} for f in auto_gen_images(bid, s, ratio, run_id, report)]
            elif v == "genvoice":
                setr(step="🎙️ يولّد الصوت")
                got = auto_gen_voice(bid, s, run_id, report)
                if got and got[1] == "voice":
                    voice = {"f": got[0], "fit": bool(o.get("fit", True))}
                elif got:
                    music = {"f": got[0], "volume": int(o.get("volume") or 35), "duck": bool(o.get("duck", True))}
            elif v in ("voice", "music"):
                if v == "voice" and (s.get("src") or {}).get("mode") == "stock":
                    report.append("⚠️ الستوك فيه موسيقى فقط، لا يوجد تعليقات صوتية. اختر تعليق من المكتبة أو استخدم «ولّد صوت»")
                    continue
                got, _ = take(s, ("audio",), 1, o.get("order") or "fresh")
                if not got:
                    report.append(f"⚠️ مالقاش {'تعليق صوتي' if v == 'voice' else 'موسيقى'} في «{(s.get('src') or {}).get('label') or 'المكتبة'}»")
                    continue
                if v == "voice":
                    voice = {"f": got[0], "fit": bool(o.get("fit"))}
                else:
                    music = {"f": got[0], "volume": int(o.get("volume") or 35), "duck": bool(o.get("duck"))}
                report.append(f"✓ {'التعليق' if v == 'voice' else 'الموسيقى'}: {got[0]['name']}")
        if not picked and not intro and not outro:
            raise RuntimeError("لا يوجد أي صورة ولا فيديو. راجع الإشارة في «اسحب» أو «قطّع الفيديو»، أو وصف «ولّد صورة»")
        # التقطيع والتوليد الأول (أطول حاجة)، والقطع المتجمّعة بتاخد مكان «جمّع» في الترتيب
        for x in picked:
            if "split" in x:
                sp = next(s for s in steps if s["verb"] == "split")
                x["clips"] = auto_run_split(bid, sp, x["merge"], x["f"], ratio, run_id, setr, report)
        setr(step="🎞️ يُجهّز اللقطات")
        voice_id = music_id = None
        target = None
        if voice:
            voice_id, vdur = auto_audio_id(bid, voice["f"], "voice", cache)
            target = vdur if voice["fit"] else None
        if music:
            music_id, _ = auto_audio_id(bid, music["f"], "music", cache)
        lib_picks = [x for x in picked if "split" not in x]
        fixed_sec = sum(c["_dur"] for x in picked for c in x.get("clips") or [])
        lens = automate.plan_lengths([(x["f"]["kind"], x["f"].get("dur")) for x in lib_picks], max(1.0, target - fixed_sec) if target else None, cap,
                                     [x["sec"] for x in lib_picks])
        len_of = {id(x): L for x, L in zip(lib_picks, lens)}
        clips = []
        Wc, Hc = AUTO_CANVAS.get(ratio, AUTO_CANVAS["9:16"])
        def vclip(f, L):
            ok = f.get("w") and f.get("h") and abs((f["w"] / f["h"]) - (Wc / Hc)) < 0.08
            return {"gen_id": auto_video_gen(bid, f, cache), "start": 0, "end": round(min(L, f.get("dur") or L), 2) if L else None, "fit": "fill" if ok else "blur"}
        if intro:
            clips.append(vclip(intro, None))
        for x in picked:
            if "split" in x:   # القطع بطولها (مابيتطبقش عليها «طول اللقطات»)
                for c in x["clips"]:
                    c = {k: v for k, v in c.items() if k != "_dur"}
                    if trans and clips:
                        c["trans"] = {"type": trans, "dur": 0.3}
                    clips.append(c)
                continue
            f, L = x["f"], len_of[id(x)]
            c = {"gen_id": auto_image_gen(bid, f, L, ratio, cache), "start": 0, "end": None, "fit": "fill"} if f["kind"] == "image" else vclip(f, L)
            if trans and clips:
                c["trans"] = {"type": trans, "dur": 0.3}
            clips.append(c)
        if outro:
            clips.append({**vclip(outro, None), **({"trans": {"type": trans, "dur": 0.3}} if trans else {})})
        cache_f.write_text(json.dumps(cache, ensure_ascii=False), encoding="utf-8")
        mo = opt("montage")   # 🎬 «مونتاج»: الاختيارات فوق «تعليق نصي» والتوطية لو موجودة
        cap_style = (mo or {}).get("cap_style") or "off"
        caps = voice_id and ((cap_style != "off") if mo else (opt("caption") or {}).get("on"))
        duck = ((mo or {}).get("duck_pct", 75) / 100 if mo else 0.75) if voice_id and (mo or (music or {}).get("duck")) else 0
        data = {"name": f"🤖 {d.get('name') or 'قالب'}"[:100], "section": "free", "clips": clips, "outro": False,
                "brand_intro": bool((mo or {}).get("b_intro")), "brand_outro": bool((mo or {}).get("b_outro")),
                "char_intro": False, "canvas": {"ratio": ratio, "bg": "#000000"},
                "captions": ({"enabled": True, **({"template": cap_style} if cap_style in captions.TEMPLATES else {})}) if caps else {},
                "voice": {"id": voice_id} if voice_id else None,
                "music": {"id": music_id, "volume": round((music or {}).get("volume", 35) / 100, 2)} if music_id else None,
                "mix": {"duck": round(duck, 2), "normalize": True, "enhance": bool(voice_id) and (mo or {}).get("denoise", True)}}
        if mo:
            pos = automate.LOGO_POS.get(mo.get("logo") or "tr", automate.LOGO_POS["tr"])
            data["logo"] = {**LOGO_DEFAULTS, "enabled": mo.get("logo") != "off", "x": pos[1], "y": pos[2], "size": int(mo.get("logo_size") or 18)}
            lvl = automate.SILENCE.get(mo.get("silence") or "off", automate.SILENCE["off"])
            if lvl[1]:
                setr(step="✂️ يشيل السكتات")
                with closing(db()) as conn:
                    n_sil, sec_sil = cut_silences(conn, data, lvl[1])
                if n_sil:
                    report.append(f"✂️ اتشال {n_sil} سكتة ({sec_sil} ثانية، مستوى {lvl[0]})")
        pj = create_project(ProjectIn(**data))
        if caps:   # الكابشن محتاج الكلام مكتوب بتوقيته
            setr(step="✍️ يكتب النص لكي التعليق النصي", project_id=pj["id"])
            with closing(db()) as conn:
                tr = transcript_of(conn.execute("SELECT transcript FROM audio WHERE id = ?", (voice_id,)).fetchone())
            if tr.get("status") != "done":
                set_transcript(voice_id, {"status": "working", "words": []})
                run_transcribe(voice_id)
                if not atlas.mock_mode():
                    with closing(db()) as conn:
                        r = conn.execute("SELECT duration FROM audio WHERE id = ?", (voice_id,)).fetchone()
                    wallet.charge(wallet.credits(wallet.est(stt_min=float(r["duration"]) / 60)), "قالب مخصص: كتابة النص للكابشن", run_id)
        for x in picked + ([voice] if voice else []) + ([music] if music else []):
            used[x["f"]["id"]] = used.get(x["f"]["id"], 0) + 1   # الفيديو اللي اتقطّع كمان (المرة الجاية ياخد غيره)
        auto_update(rid, lambda z: z.update(used=used), bid)
        report.append(f"🎬 {len(clips)} لقطة · مقاس {ratio}" + (f" · نحو {round(target)} ثانية على قدر التعليق" if target else ""))
        setr(project_id=pj["id"], report=report)
        auto_export_publish(pj["id"], steps, d.get("name") or "", port, setr, report)
        with closing(db()) as conn:
            ex = conn.execute("SELECT export_id FROM projects WHERE id = ?", (pj["id"],)).fetchone()["export_id"]
        setr(status="done", step=None, project_id=pj["id"], export_url=f"/media/exports/{ex}.mp4" if ex else None, report=report, error=None)
    except Exception as exc:  # noqa: BLE001
        setr(status="failed", step=None, report=report, error=str(getattr(exc, "detail", None) or exc)[:300])


# ---------------------------------------------------------------- 📡 قواعد الخوارزميات (دراع لوحده في العقل)
playbook.OVERRIDE = lambda: playbook.active((active_client() or {}).get("algo_rules"))
ALGO_WARN = "نرجو عدم تعديل أو إزالة أو حذف أي قاعدة: القواعد هذه الأساسية اتجمعت من دراسات متعمقة في خوارزميات السوشيال ميديا، وكل الأدوات تسير عليها."


@app.get("/api/ad-brains/{bid}/algo-rules")
def brain_algo_rules(bid: str):
    b = brain_row(bid)
    if b is None:
        raise HTTPException(404, "هذا العميل غير موجود")
    return {"parts": playbook.editable(b.get("algo_rules")), "groups": playbook.GROUPS, "warn": ALGO_WARN, "updated": algo.UPDATED, "changed": bool(b.get("algo_rules"))}


class AlgoRulesIn(BaseModel):
    parts: dict = {}     # {id: [{t, on}]}
    reset: list[str] = []   # فريمويركس ترجع للأصل (أو "all")


@app.put("/api/ad-brains/{bid}/algo-rules")
def brain_algo_rules_put(bid: str, body: AlgoRulesIn):
    def fn(d):
        cur = dict(d.get("algo_rules") or {})
        if "all" in body.reset:
            cur = {}
        for k in body.reset:
            cur.pop(k, None)
        for fid, rows in playbook.clean_saved(body.parts).items():
            cur[fid] = rows
        for fid in body.parts:   # اتبعتت زي الأصل بالظبط = رجعت للأصل
            if fid not in playbook.clean_saved(body.parts):
                cur.pop(fid, None)
        d["algo_rules"] = cur
    update_brain(bid, fn)
    return brain_algo_rules(bid)


# ---------------------------------------------------------------- 📈 الترند (دراع لوحده في العقل)
TRENDS_BUSY: set[str] = set()


def trends_state(bid: str) -> dict:
    return (brain_row(bid) or {}).get("trends") or {}


def trends_out(bid: str) -> dict:
    t = trends_state(bid)
    items = t.get("items") or []
    return {"items": items, "new": sum(1 for x in items if not x.get("seen")), "status": "working" if bid in TRENDS_BUSY else t.get("status") or "idle",
            "error": t.get("error"), "checked_at": t.get("checked_at"), "live": rivals.live(), "market": (brain_row(bid) or {}).get("market") or ""}


def run_trends(bid: str) -> None:
    try:
        b = brain_row(bid) or {}
        old = (b.get("trends") or {}).get("items") or []
        if atlas.mock_mode() or not rivals.live():
            new = trends.mock(old)
        else:
            qs = (b.get("competitors") or {}).get("queries") or []
            if not qs:
                raw = rivals_llm(rivals.queries_messages(b), "كلمات البحث")
                qs = [str(q).strip()[:60] for q in raw.get("queries") or [] if str(q).strip()][:6] or [b.get("domain") or b.get("name") or ""]
            wallet.need(wallet.credits(wallet.est(scrape=len(qs) * len(rivals.PLATFORMS), chars=12000)), "الترند")
            posts = []
            for q in qs[:6]:
                for plat in rivals.PLATFORMS:
                    try:
                        posts += rivals.search(plat, q)
                    except rivals.RivalsError:
                        continue
            top = trends.recent(posts)
            raw = rivals_llm(trends.messages(rivals.brand_info(b), b.get("market") or "", top, [x.get("title", "") for x in old]), "الترند") if top else {}
            new = trends.clean(raw, top, old)
            wallet.charge(wallet.credits(wallet.est(scrape=len(qs[:6]) * len(rivals.PLATFORMS), chars=12000)), "عقل العلامة: الترند في السوق", bid)
        update_brain(bid, lambda d: d.update(trends={**(d.get("trends") or {}), "items": trends.merge((d.get("trends") or {}).get("items") or [], new),
                                                      "checked_at": time.time(), "status": "ready", "error": None}))
    except Exception as exc:  # noqa: BLE001
        msg = str(getattr(exc, "detail", None) or exc)[:240]
        update_brain(bid, lambda d: d.update(trends={**(d.get("trends") or {}), "status": "failed", "error": msg, "checked_at": time.time()}))
    finally:
        TRENDS_BUSY.discard(bid)


def start_trends(bid: str) -> None:
    if bid in TRENDS_BUSY:
        return
    TRENDS_BUSY.add(bid)
    threading.Thread(target=run_trends, args=(bid,), daemon=True).start()


@app.get("/api/ad-brains/{bid}/trends")
def brain_trends(bid: str):
    """الترندات: تُحدّث تلقائيًا إذا آخر تحديث عدّى عليه ١٢ ساعة (والسوق أو المجال مكتوبين)."""
    b = brain_row(bid)
    if b is None:
        raise HTTPException(404, "هذا العميل غير موجود")
    t = b.get("trends") or {}
    if (b.get("market") or b.get("domain")) and time.time() - float(t.get("checked_at") or 0) > trends.EVERY:
        start_trends(bid)
    return trends_out(bid)


@app.post("/api/ad-brains/{bid}/trends/refresh")
def brain_trends_refresh(bid: str):
    b = brain_row(bid)
    if b is None:
        raise HTTPException(404, "هذا العميل غير موجود")
    if not (b.get("market") or b.get("domain")):
        raise HTTPException(400, "اكتب «السوق» و«المجال» في الهوية أولًا، لكي نعرف نبحث عن الترند أين")
    start_trends(bid)
    return trends_out(bid)


@app.post("/api/ad-brains/{bid}/trends/seen")
def brain_trends_seen(bid: str):
    """فأسفل القائمة: المربع الأحمر يروح (الترندات تظل موجودة)."""
    def fn(d):
        for x in (d.get("trends") or {}).get("items") or []:
            x["seen"] = True
    update_brain(bid, fn)
    return trends_out(bid)


@app.delete("/api/ad-brains/{bid}/trends/{tid}")
def brain_trend_delete(bid: str, tid: str):
    def fn(d):
        t = d.setdefault("trends", {})
        t["items"] = [x for x in t.get("items") or [] if x.get("id") != tid]
    update_brain(bid, fn)
    return trends_out(bid)


class TrendUseIn(BaseModel):
    now: bool = False   # «استخدمه دلوقتي»: أول فكرة في القالب الجاي بتتبني عليه


@app.post("/api/ad-brains/{bid}/trends/{tid}/save")
def brain_trend_save(bid: str, tid: str, body: TrendUseIn):
    """🔖 الترند يُحفظ في «محفوظاتك لبعدين» (بجانب الأفكار)، ويظهر في خطوة الفكرة في أي قالب."""
    t = next((x for x in (trends_state(bid).get("items") or []) if x.get("id") == tid), None)
    if not t:
        raise HTTPException(404, "هذا الترند غير موجود")
    item = {"id": uuid.uuid4().hex[:10], "kind": "trend", "item": trends.to_saved(t), "at": now(), "template": {}, "format": "", "now": body.now, "trend_id": tid}
    cid = re.sub(r"[^\w-]", "", str(bid))[:64] or "default"

    def fn(m):
        saved = [x for x in m.get("saved") or [] if not (x.get("kind") == "trend" and x.get("trend_id") == tid)]
        if body.now:   # ترند واحد بس مستني «دلوقتي»
            for x in saved:
                x.pop("now", None)
        m["saved"] = [*saved, item][-ideamem.SAVED_MAX:]
    mem_update(cid, fn)
    def mark(d):
        for x in (d.get("trends") or {}).get("items") or []:
            if x.get("id") == tid:
                x.update(saved=True, seen=True)
    update_brain(bid, mark)
    return {**trends_out(bid), "saved_id": item["id"]}


# ---------------------------------------------------------------- 🧊 استوديو المشهد: مسودة 3D ← فيديو حقيقي
# المتصفح بيرسم المشهد (أشكال بسيطة + حركة كاميرا) ويطلّع منه فيديو رمادي، والفيديو ده بيروح لموديل بياخد فيديو مرجع
# مع صور العناصر والبرومبت، فالحركة والكادر ثابتين والموديل بيلوّن بس. كل توليدة «لقطة» محفوظة وتدخل الفيديوهات الجاهزة.
import scene3d  # noqa: E402

SCENE_DIR = DATA_DIR / "scenes"
SCENE_DIR.mkdir(parents=True, exist_ok=True)
app.mount("/media/scenes", StaticFiles(directory=SCENE_DIR), name="scenes")
SCENE_LOCK = threading.Lock()


def scene_load(sid: str) -> dict:
    f = SCENE_DIR / Path(sid).name / "scene.json"
    if not f.exists():
        raise HTTPException(404, "هذا المشهد غير موجود")
    d = json.loads(f.read_text(encoding="utf-8"))
    if not owned(d.get("client_id")):
        raise HTTPException(404, "هذا المشهد غير موجود")
    return d


def scene_save(sid: str, d: dict) -> None:
    d["updated_at"] = now()
    f = SCENE_DIR / Path(sid).name / "scene.json"
    f.parent.mkdir(parents=True, exist_ok=True)
    f.with_suffix(".tmp").write_text(json.dumps(d, ensure_ascii=False), encoding="utf-8")
    f.with_suffix(".tmp").replace(f)


def scene_update(sid: str, fn) -> dict:
    with SCENE_LOCK:
        d = scene_load(sid)
        fn(d)
        scene_save(sid, d)
        return d


def scene_models() -> list[dict]:
    """النماذج التي تأخذ فيديو مرجع: تعديل فيديو (فيديو ← فيديو) أو مراجع بفيديو (Seedance وWan وغيرهم)."""
    ms = [m for m in auto_gen_models() if m.get("mode") == "video" or (m.get("mode") == "refs" and m.get("video_in"))]
    # Seedance 2 بيمشي على المسودة بالحرف (ده اللي محتاجينه)، وبعده Wan 3 وKling O3
    pref = ("seedance-2.0/", "seedance-2.5", "wan-3.0/", "kling-video-o3-pro", "kling-video-o3-std", "seedance-2.0-fast")
    return sorted(ms, key=lambda m: next((i for i, p in enumerate(pref) if p in m["model"]), 99))


def scene_dict(sid: str, d: dict) -> dict:
    base = f"/media/scenes/{sid}"
    return {**d, "id": sid, "draft_url": f"{base}/{d['draft']}?v={int(time.time())}" if d.get("draft") else None,
            "takes": [{**t, "url": f"{base}/{t['file']}" if t.get("file") else None} for t in d.get("takes") or []]}


@app.get("/api/scenes-meta")
def scenes_meta():
    return {"shapes": scene3d.SHAPES, "lights": scene3d.LIGHTS, "ratios": scene3d.RATIOS,
            "models": [{k: m.get(k) for k in ("model", "label", "per_sec", "mode")} for m in scene_models()]}


@app.get("/api/scenes")
def scenes_list():
    out = []
    for f in sorted(SCENE_DIR.glob("*/scene.json"), key=lambda x: x.stat().st_mtime, reverse=True):
        try:
            d = json.loads(f.read_text(encoding="utf-8"))
        except ValueError:
            continue
        if owned(d.get("client_id")):
            out.append({"id": f.parent.name, "name": d.get("name"), "updated_at": d.get("updated_at"), "takes": len(d.get("takes") or []),
                        "busy": any(t.get("status") == "working" for t in d.get("takes") or [])})
    return out


class SceneNewIn(BaseModel):
    name: str = ""


@app.post("/api/scenes")
def scene_new(body: SceneNewIn):
    sid = uuid.uuid4().hex[:10]
    d = {"name": body.name.strip()[:80] or "مشهد جديد", "client_id": active_client_id(), "scene": scene3d.default(), "prompt": "", "refs": [],
         "model": "", "draft": None, "takes": [], "say": "", "created_at": now()}
    scene_save(sid, d)
    return scene_dict(sid, d)


@app.get("/api/scenes/{sid}")
def scene_get(sid: str):
    return scene_dict(sid, scene_load(sid))


class ScenePatch(BaseModel):
    name: str | None = None
    scene: dict | None = None
    prompt: str | None = None
    refs: list | None = None
    model: str | None = None


@app.patch("/api/scenes/{sid}")
def scene_patch(sid: str, body: ScenePatch):
    def fn(d):
        if body.name is not None:
            d["name"] = body.name.strip()[:80] or d["name"]
        if body.scene is not None:
            new = scene3d.clean(body.scene)
            if new != d.get("scene"):
                d["draft"] = None   # المشهد اتغيّر: المسودة القديمة مابقتش شبهه
            d["scene"] = new
        if body.prompt is not None:
            d["prompt"] = body.prompt.strip()[:3000]
        if body.refs is not None:
            d["refs"] = [r for r in (scene3d.clean_ref(x) for x in body.refs[:6]) if r]
        if body.model is not None:
            d["model"] = body.model[:120]
    return scene_dict(sid, scene_update(sid, fn))


@app.delete("/api/scenes/{sid}")
def scene_delete(sid: str):
    scene_load(sid)
    shutil.rmtree(SCENE_DIR / Path(sid).name, ignore_errors=True)
    return {"ok": True}


class ScenePlanIn(BaseModel):
    text: str


@app.post("/api/scenes/{sid}/plan")
def scene_plan(sid: str, body: ScenePlanIn):
    """«صِفه بكلامك»: العقل يبني المسودة (الأشكال وحركتها والكاميرا) ويكتب وصف الشكل الحقيقي (يُخصم على قدر النص)."""
    text = body.text.strip()[:2000]
    if not text:
        raise HTTPException(400, "صِف الفيديو أولًا")
    d = scene_load(sid)
    if atlas.mock_mode() or not atlas.api_key():
        res = scene3d.mock_plan(text)
    else:
        cost = wallet.credits(wallet.est(chars=9000 + len(text)))
        wallet.need(cost, "بناء المشهد")
        b = active_client() or {}
        brand = " · ".join(str(b.get(k) or "") for k in ("name", "domain", "about") if b.get(k))
        names = [f["name"] for f in lib_merged(active_client_id(), ready=False)["files"] if f.get("kind") == "image"][:40]
        res = flow_llm(scene3d.plan_messages(text, brand, d.get("scene") or {}, names), "المشهد")
        wallet.charge(cost, "استوديو المشهد: بناء المسودة", sid)
    sc = scene3d.clean(res.get("scene") or {})
    old = {o["name"]: o.get("img") for o in (d.get("scene") or {}).get("objects") or [] if o.get("img")}
    for o in sc["objects"]:   # الصور اللي العميل كان حاططها على الأشكال بتفضل لو الاسم زي ما هو
        o["img"] = o.get("img") or old.get(o["name"])
    d = scene_update(sid, lambda x: x.update(scene=sc, draft=None, prompt=str(res.get("prompt") or x.get("prompt") or "")[:3000],
                                             say=str(res.get("say") or "")[:400]))
    return scene_dict(sid, d)


@app.post("/api/scenes/{sid}/draft")
def scene_draft(sid: str, frames: list[UploadFile] | None = File(None), video: UploadFile | None = File(None), fps: int = Form(24)):
    """المسودة من المتصفح: فيديو VP8 (IVF) كل فريم بوقته، أو فريمات صور (المتصفحات القديمة) ← mp4 بنفس المدة بالضبط."""
    d = scene_load(sid)
    folder = SCENE_DIR / Path(sid).name
    fps = max(12, min(30, int(fps or 24)))
    if not video and (not frames or len(frames) > fps * 16):
        raise HTTPException(400, "المسودة تحتاج فريمات (حتى ١٥ ثانية)")
    tmp = TMP_DIR / f"scdraft_{uuid.uuid4().hex[:8]}"
    tmp.mkdir(parents=True, exist_ok=True)
    name = f"draft_{uuid.uuid4().hex[:6]}.mp4"
    W, H = {"9:16": (720, 1280), "16:9": (1280, 720), "1:1": (960, 960), "4:5": (864, 1080)}[d["scene"]["ratio"]]
    try:
        if video:
            (tmp / "in.ivf").write_bytes(video.file.read()[:200_000_000])
            src = ["-r", str(fps), "-i", str(tmp / "in.ivf")]
        else:
            for i, up in enumerate(frames):
                (tmp / f"f{i:04d}.jpg").write_bytes(up.file.read()[:8_000_000])
            src = ["-framerate", str(fps), "-i", str(tmp / "f%04d.jpg")]
        subprocess.run([ffmpeg_exe(), "-hide_banner", "-loglevel", "error", "-y", *src, "-t", f"{d['scene']['duration']:.2f}",
                        "-vf", f"scale={W}:{H}:force_original_aspect_ratio=increase,crop={W}:{H},format=yuv420p",
                        "-c:v", "libx264", "-preset", "veryfast", "-crf", "18", "-r", str(fps), "-movflags", "+faststart", str(folder / name)],
                       check=True, capture_output=True, timeout=300)
    except subprocess.SubprocessError as exc:
        raise HTTPException(400, f"تعذّر ذلك أجهّز المسودة: {exc}") from exc
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    old = d.get("draft")
    d = scene_update(sid, lambda x: x.update(draft=name))
    if old and old != name and not any(t.get("draft") == old for t in d.get("takes") or []):
        (folder / old).unlink(missing_ok=True)
    return scene_dict(sid, d)


def run_scene_take(sid: str, tid: str) -> None:
    folder = SCENE_DIR / Path(sid).name
    def setp(**kw):
        scene_update(sid, lambda x: next((t.update(**kw) for t in x["takes"] if t["id"] == tid), None))
    try:
        d = scene_load(sid)
        t = next(t for t in d["takes"] if t["id"] == tid)
        src = folder / t["draft"]
        g = {"id": tid, "opts": {"prompt": t["prompt_full"], "model": t["model"], "refs": t.get("refs") or [], "use_piece": True}}
        dest = folder / f"take_{tid}.mp4"
        label = auto_gen_piece(src, float(d["scene"]["duration"]), g, dest, f"scene_{sid}", d["scene"]["ratio"])
        dur = probe_duration(dest)
        export_id = uuid.uuid4().hex[:12]
        filename = f"scene_{export_id}.mp4"
        shutil.copy(dest, EXPORTS_DIR / filename)
        with closing(db()) as conn, conn:
            conn.execute("INSERT INTO exports (id, name, filename, duration, source, project_id, created_at) VALUES (?, ?, ?, ?, 'scene', NULL, ?)",
                         (export_id, f"🧊 {d.get('name') or 'مشهد'}"[:100], filename, dur, now()))
        setp(status="done", step=None, file=dest.name, label=label, export_id=export_id, error=None)
    except wallet.NoCredits as exc:
        setp(status="failed", step=None, error=str(exc)[:300])
    except Exception as exc:  # noqa: BLE001
        setp(status="failed", step=None, error=str(getattr(exc, "detail", None) or exc)[:300])


@app.post("/api/scenes/{sid}/generate")
def scene_generate(sid: str):
    """ولّد: المسودة + صور العناصر (المرجع) + الوصف ← لقطة حقيقية بنفس الحركة. كل مرة لقطة جديدة (القديمة تظل)."""
    d = scene_load(sid)
    if not d.get("draft"):
        raise HTTPException(400, "طلّع المسودة أولًا")
    if any(t.get("status") == "working" for t in d.get("takes") or []):
        raise HTTPException(400, "فيه لقطة تُولّد الآن، انتظر تنتهي")
    ms = scene_models()
    m = next((x for x in ms if x["model"] == d.get("model")), None) or (ms[0] if ms else None)
    if not m:
        raise HTTPException(400, "لا يوجد نموذج فيديو يأخذ فيديو مرجع متاح الآن")
    # صور العناصر: اللي على الأشكال + اللي متضافة كمراجع، من غير تكرار
    refs, seen = [], set()
    for r in [o["img"] for o in d["scene"]["objects"] if o.get("img")] + (d.get("refs") or []):
        k = (r["kind"], r["id"])
        if k not in seen:
            seen.add(k)
            refs.append(r)
    full = scene3d.gen_prompt(d["scene"], d.get("prompt") or "", refs)
    per = m.get("per_sec") or 0.17
    est = wallet.credits(per * d["scene"]["duration"] * (2 if m.get("mode") == "refs" else 1))
    if not atlas.mock_mode():
        wallet.need(est, "توليد لقطة المشهد")
    tid = uuid.uuid4().hex[:8]
    take = {"id": tid, "status": "working", "step": f"✨ يولّد بـ {m['label']}", "model": m["model"], "model_label": m["label"], "draft": d["draft"],
            "prompt": d.get("prompt") or "", "prompt_full": full, "refs": refs[:automate.MAX_REFS], "est": est, "at": now(), "error": None}
    d = scene_update(sid, lambda x: x.update(takes=[*(x.get("takes") or []), take][-20:]))
    threading.Thread(target=run_scene_take, args=(sid, tid), daemon=True).start()
    return scene_dict(sid, d)


@app.delete("/api/scenes/{sid}/takes/{tid}")
def scene_take_delete(sid: str, tid: str):
    folder = SCENE_DIR / Path(sid).name
    gone = []
    d = scene_update(sid, lambda x: (gone.extend(t for t in x["takes"] if t["id"] == tid), x.update(takes=[t for t in x["takes"] if t["id"] != tid])))
    for t in gone:
        if t.get("file"):
            (folder / t["file"]).unlink(missing_ok=True)
    return scene_dict(sid, d)


# ---------------------------------------------------------------- 🛫 الأوتوبايلوت: كام بوست في اليوم، في أحسن أوقات، من القوالب اللي اخترتها
# كل ميعاد بيبقى «مهمة»: فكرة ← سكريبت ← (تصوير / صوت / أفاتار / رسم) ← فيديو ← جدولة في ميعادها.
# بيمشي على لفة المجدول الموجودة (كل ٢٠ ثانية) خطوة صغيرة لكل مهمة، والشغل التقيل بيتعمل بنفس دوال القوالب.
# لو العميل اختار «أوافق على كل خطوة» المهمة بتقف عند الخطوة دي لحد ما يوافق. قالب الموبايل بيستنى العميل يصوّر.
PILOT_FILE = DATA_DIR / "pilot.json"
PILOT_LOCK, PILOT_TICK = threading.Lock(), threading.Lock()
PILOT_STEPS = ("idea", "script", "montage", "video")
PILOT_BEST = {1: ["19:00"], 2: ["13:00", "20:00"], 3: ["12:00", "17:00", "21:00"], 4: ["09:00", "13:00", "18:00", "21:30"],
              5: ["09:00", "12:00", "15:00", "18:00", "21:30"], 6: ["08:00", "11:00", "13:30", "16:30", "19:00", "22:00"]}
PILOT_DEFAULTS = {"on": False, "per_day": 2, "times": [{"t": t, "mine": False} for t in PILOT_BEST[2]], "tz": 180, "templates": [],
                  "mode": "approve", "steps": list(PILOT_STEPS), "platforms": [], "twin": "", "names": {}}
PILOT_ACTIVE = ("run", "wait", "cam")


def pilot_load() -> dict:
    try:
        d = json.loads(PILOT_FILE.read_text(encoding="utf-8")) if PILOT_FILE.exists() else {}
    except ValueError:
        d = {}
    return {"settings": {**PILOT_DEFAULTS, **(d.get("settings") or {})}, "jobs": d.get("jobs") or [], "rot": int(d.get("rot") or 0), "port": d.get("port") or 8000}


def pilot_save(d: dict) -> None:
    PILOT_FILE.with_suffix(".tmp").write_text(json.dumps(d, ensure_ascii=False), encoding="utf-8")
    PILOT_FILE.with_suffix(".tmp").replace(PILOT_FILE)


def pilot_update(fn) -> dict:
    with PILOT_LOCK:
        d = pilot_load()
        fn(d)
        pilot_save(d)
        return d


def pilot_job_set(jid: str, **kw) -> None:
    hit = []
    def fn(d):
        for j in d["jobs"]:
            if j["id"] == jid:
                was = (j.get("status"), j.get("gate"))
                j.update(kw, updated_at=now())
                if j.get("status") in ("wait", "cam") and (j.get("status"), j.get("gate")) != was:
                    hit.append(dict(j))
    pilot_update(fn)
    for j in hit:
        pilot_push(j)


# 🔔 إشعارات تطبيق الموبايل (Expo push): كل موبايل داخل على الحساب بيسجّل توكنه، والأوتوبايلوت بيبعت لما يستناك
PUSH_FILE = DATA_DIR / "push_tokens.json"
PUSH_LOCK = threading.Lock()
PUSH_TEXT = {"idea": ("فكرة جديدة لفيديو جاي", "اختار الفكرة اللي تعجبك"), "script": ("السكريبت جاهز", "راجعه واختار النسخة اللي تعجبك"),
             "montage": ("المونتاج جاهز", "اتفرج عليه ووافق عشان يتصدّر"), "video": ("الفيديو جاهز قبل النشر", "اتفرج عليه ووافق عشان يتجدول"),
             "shoot": ("📱 مستني تصويرك", "السكريبت جاهز على التيلي برومتر")}


def push_tokens() -> list[str]:
    try:
        return [t for t in json.loads(PUSH_FILE.read_text(encoding="utf-8")) if isinstance(t, str)]
    except (OSError, ValueError):
        return []


def push_send(title: str, body: str, data: dict) -> None:
    toks = push_tokens()
    if not toks or os.environ.get("PUBLISH_MOCK"):
        return
    msgs = [{"to": t, "title": title, "body": body[:180], "data": data, "sound": "default", "channelId": "approvals"} for t in toks]
    def go():
        try:
            r = httpx.post("https://exp.host/--/api/v2/push/send", json=msgs, timeout=15)
            dead = [m["to"] for m, x in zip(msgs, (r.json().get("data") or [])) if (x.get("details") or {}).get("error") == "DeviceNotRegistered"]
            if dead:
                with PUSH_LOCK:
                    PUSH_FILE.write_text(json.dumps([t for t in push_tokens() if t not in dead]), encoding="utf-8")
        except Exception:  # noqa: BLE001
            pass   # الإشعار مش أساسي: الموافقة بتفضل مستنية في التطبيق والويب
    threading.Thread(target=go, daemon=True).start()


def pilot_push(j: dict) -> None:
    gate = "shoot" if j.get("status") == "cam" else j.get("gate") or ""
    title, body = PUSH_TEXT.get(gate, ("الأوتوبايلوت مستنيك", "فيه خطوة مستنية موافقتك"))
    name = j.get("title") or ""
    if not name and j.get("fid"):
        try:
            d = flow_load(j["fid"])
            name = (d.get("scenario") or {}).get("title") or (d.get("idea") or {}).get("title") or ""
        except HTTPException:
            pass
    push_send(title, f"«{name}» · {body}" if name else body, {"kind": "pilot", "jid": j["id"], "gate": gate})


# 📱 «كمّل على موبايلك»: خطوة على الويب (تصوير بالسكريبت أو تسجيل صوت) بتتبعت للموبايل بإشعار أو QR،
# والموبايل بيرجّع النتيجة لنفس الخطوة والويب شايفها لوحده (بيسأل كل كام ثانية)
HANDOFF_FILE = DATA_DIR / "handoffs.json"
HANDOFF_DIR = DATA_DIR / "handoff"
HANDOFF_LOCK = threading.Lock()
HANDOFF_KINDS = ("shoot", "voice")


def handoffs_load() -> list[dict]:
    try:
        return [h for h in json.loads(HANDOFF_FILE.read_text(encoding="utf-8")) if isinstance(h, dict)]
    except (OSError, ValueError):
        return []


def handoff_update(fn) -> list[dict]:
    with HANDOFF_LOCK:
        hs = handoffs_load()
        fn(hs)
        HANDOFF_FILE.write_text(json.dumps(hs[-60:], ensure_ascii=False), encoding="utf-8")
        return hs


def handoff_get(hid: str) -> dict:
    h = next((x for x in handoffs_load() if x["id"] == hid), None)
    if not h:
        raise HTTPException(404, "الطلب ده مش موجود أو خلص")
    return h


def handoff_dict(h: dict) -> dict:
    return {**h, "link": f"simsimkit://handoff/{h['id']}", "open_url": f"/go#{h['id']}",
            "audio_url": f"/api/handoff/{h['id']}/audio" if h.get("audio") else None}


def handoff_finish_flow(fid: str) -> None:
    """الفيديو وصل للمشروع (من أي طريق): أي طلب تصوير مستني على المشروع ده بيخلص."""
    def fn(hs):
        for h in hs:
            if h.get("fid") == fid and h["kind"] == "shoot" and h["status"] == "waiting":
                h.update(status="done", done_at=now())
    handoff_update(fn)


class HandoffIn(BaseModel):
    kind: str
    fid: str = ""
    jid: str = ""
    title: str = ""
    prompt: str = ""


@app.post("/api/handoff")
def handoff_new(body: HandoffIn):
    if body.kind not in HANDOFF_KINDS:
        raise HTTPException(400, "نوع الطلب غير معروف")
    fid = body.fid.strip()
    if body.kind == "shoot":
        if body.jid and not fid:
            fid = (next((j for j in pilot_load()["jobs"] if j["id"] == body.jid), None) or {}).get("fid") or ""
        flow_load(fid)   # المشروع لازم يكون موجود وبتاع العميل ده
    h = {"id": uuid.uuid4().hex[:10], "kind": body.kind, "fid": fid or None, "jid": body.jid.strip() or None,
         "title": body.title.strip()[:120] or ("صوّر الفيديو بالسكريبت" if body.kind == "shoot" else "سجّل بصوتك"),
         "prompt": body.prompt.strip()[:600], "status": "waiting", "created_at": now()}
    handoff_update(lambda hs: hs.append(h))
    push_send("📱 كمّل على موبايلك", h["title"], {"kind": "handoff", "hid": h["id"]})
    return handoff_dict(h)


@app.get("/api/handoff/{hid}")
def handoff_read(hid: str):
    return handoff_dict(handoff_get(hid))


@app.delete("/api/handoff/{hid}")
def handoff_cancel(hid: str):
    handoff_update(lambda hs: hs.__setitem__(slice(None), [x for x in hs if x["id"] != hid]))
    return {"ok": True}


@app.get("/api/handoff/{hid}/qr.svg")
def handoff_qr(hid: str, base: str = ""):
    """QR بيفتح صفحة صغيرة على الموقع، والصفحة بتفتح التطبيق على الطلب ده (كاميرا الموبايل العادية بتقرا https)."""
    import segno
    handoff_get(hid)
    origin = base if re.fullmatch(r"https?://[\w.:-]+", base or "") else "https://simsimkit.com"
    buf = io.BytesIO()
    segno.make(f"{origin}/go#{hid}", error="m").save(buf, kind="svg", scale=7, border=2, dark="#181718")
    return Response(buf.getvalue(), media_type="image/svg+xml")


@app.post("/api/handoff/{hid}/voice")
def handoff_voice(hid: str, file: UploadFile = File(...)):
    h = handoff_get(hid)
    if h["kind"] != "voice":
        raise HTTPException(400, "الطلب ده مش تسجيل صوت")
    HANDOFF_DIR.mkdir(parents=True, exist_ok=True)
    name = save_upload(file, IDEA_AUDIO_EXT, HANDOFF_DIR, f"h_{hid}")
    def fn(hs):
        for x in hs:
            if x["id"] == hid:
                x.update(status="done", audio=name, done_at=now())
    handoff_update(fn)
    return handoff_dict(handoff_get(hid))


@app.get("/api/handoff/{hid}/audio")
def handoff_audio(hid: str):
    h = handoff_get(hid)
    f = HANDOFF_DIR / Path(h.get("audio") or "_").name
    if not f.is_file():
        raise HTTPException(404, "لسه مفيش تسجيل")
    return FileResponse(f)


class PushIn(BaseModel):
    token: str


@app.post("/api/push/register")
def push_register(body: PushIn):
    t = body.token.strip()
    if not re.fullmatch(r"Expo(nent)?PushToken\[[\w-]{10,80}\]", t):
        raise HTTPException(400, "توكن الإشعارات غير صحيح")
    with PUSH_LOCK:
        PUSH_FILE.write_text(json.dumps([*[x for x in push_tokens() if x != t], t][-20:]), encoding="utf-8")
    return {"ok": True}


@app.post("/api/push/unregister")
def push_unregister(body: PushIn):
    with PUSH_LOCK:
        PUSH_FILE.write_text(json.dumps([x for x in push_tokens() if x != body.token.strip()]), encoding="utf-8")
    return {"ok": True}


def pilot_kind(tpl: str) -> str:
    return "custom" if tpl.startswith("auto:") else tpl if tpl in ("phone", "avatar", "carousel") else "motion"


def pilot_tpl_name(tpl: str, names: dict) -> str:
    if tpl == "phone":
        return "تصوير بالجوال"
    if tpl == "avatar":
        return "تصوير الفيديو بالأفاتار"
    if tpl == "carousel":
        return "كاروسيل"
    if tpl.startswith("auto:"):
        try:
            return auto_load(tpl[5:], active_client_id()).get("name") or "قالب مخصص"
        except HTTPException:
            return "قالب مخصص (حُذف)"
    return names.get(tpl) or tpl   # أسماء قوالب الكود زي ما هي في معرض القوالب (الواجهة بتبعتها)


def pilot_twin(s: dict) -> str | None:
    """النسخة التي ستتكلم: ما اخترها، وإلا أول نسخة جاهزة."""
    ts = twins_list()
    for t in ts:
        if t["id"] == s.get("twin") and (t["ready"]["video"] or t["ready"]["photo"]):
            return t["id"]
    return next((t["id"] for t in ts if t["ready"]["video"] or t["ready"]["photo"]), None)


def pilot_slots(s: dict, start: datetime, hours: float = 24) -> list[datetime]:
    """مواعيد النشر (بتوقيت العميل) ما قادمة في الـ ٢٤ ساعة القادمة، بتوقيت UTC."""
    tz = timezone(timedelta(minutes=int(s.get("tz") or 0)))
    local = start.astimezone(tz)
    out = []
    for day in (0, 1, 2):
        base = (local + timedelta(days=day)).date()
        for x in s.get("times") or []:
            try:
                hh, mm = (int(v) for v in str(x.get("t")).split(":"))
            except ValueError:
                continue
            at = datetime(base.year, base.month, base.day, hh % 24, mm % 60, tzinfo=tz).astimezone(timezone.utc)
            if start < at <= start + timedelta(hours=hours):
                out.append(at)
    return sorted(set(out))


def pilot_plan() -> None:
    """مهمة جديدة لكل موعد قادم في الـ ٢٤ ساعة ليس له مهمة، والقالب يتلف على القوالب المختارة بالدور."""
    def fn(d):
        s = d["settings"]
        if s.get("on") and s.get("source") == "plan":
            return pilot_plan_month(d)
        pool = [t for t in s.get("templates") or [] if isinstance(t, str)]
        if not s.get("on") or not pool:
            return
        have = {j["at"][:16] for j in d["jobs"] if j.get("at")}
        for at in pilot_slots(s, datetime.now(timezone.utc)):
            key = at.isoformat(timespec="minutes")
            if key[:16] in have:
                continue
            tpl = pool[d["rot"] % len(pool)]
            d["rot"] += 1
            d["jobs"].insert(0, {"id": uuid.uuid4().hex[:8], "at": key, "tpl": tpl, "kind": pilot_kind(tpl), "name": pilot_tpl_name(tpl, s.get("names") or {}),
                                 "status": "run", "phase": "start", "gate": None, "passed": [], "note": "في الطابور", "error": None,
                                 "fid": None, "project_id": None, "export_id": None, "post_id": None, "tries": 0, "created_at": now()})
            have.add(key[:16])
        d["jobs"] = d["jobs"][:60]
    pilot_update(fn)


def pilot_plan_month(d: dict) -> None:
    """🗓️ الأوتوبايلوت حسنًا على خطة الشهر: كل منشور موعده قادم في الـ ٢٤ ساعة يصبح مهمة بفكرته الجاهزة."""
    s = d["settings"]
    bid = s.get("plan_bid") or ""
    m = (brain_row(bid) or {}).get("month") or {}
    if m.get("status") != "applied":
        return
    tz = timezone(timedelta(minutes=int(s.get("tz") or 0)))
    t0 = datetime.now(timezone.utc)
    made = {}
    for it in m.get("items") or []:
        if it.get("job"):
            continue
        try:
            at = datetime.fromisoformat(f"{it['date']}T{it['time']}").replace(tzinfo=tz).astimezone(timezone.utc)
        except ValueError:
            continue
        if not t0 < at <= t0 + timedelta(hours=24):
            continue
        jid = uuid.uuid4().hex[:8]
        d["jobs"].insert(0, {"id": jid, "at": at.isoformat(timespec="minutes"), "tpl": it["tpl"], "kind": pilot_kind(it["tpl"]),
                             "name": (lambda nm: (it.get("tpl_name") or nm) if nm == it["tpl"] else nm)(pilot_tpl_name(it["tpl"], s.get("names") or {})),
                             "status": "run", "phase": "start", "gate": None, "passed": ["idea"], "note": "من خطة الشهر", "error": None,
                             "fid": None, "project_id": None, "export_id": None, "post_id": None, "tries": 0, "created_at": now(),
                             "plan_item": it["id"], "preset": {k: it.get(k) or "" for k in ("title", "idea", "hook")}, "caption": None})
        made[it["id"]] = jid
    d["jobs"] = d["jobs"][:80]
    if made:
        def mark(x):
            for it in (x.get("month") or {}).get("items") or []:
                if it["id"] in made:
                    it["job"] = made[it["id"]]
        update_brain(bid, mark)
    # قرّبت تخلص: إشعار مرة واحدة إن خطة الشهر الجاي محتاجة تتعمل
    last = max((it["date"] for it in m.get("items") or []), default="")
    if last and s.get("plan_warned") != m.get("start") and (datetime.fromisoformat(last).date() - t0.date()).days <= 5:
        s["plan_warned"] = m.get("start")
        notify("plan", "info", "🗓️ خطة الشهر قرّبت تنتهي", "أنشئ خطة الشهر القادم من خطة المحتوى ووافق عليها", "plan", bid)


def pilot_gate(j: dict, s: dict, step: str) -> bool:
    """هذه الخطوة تحتاج موافقة العميل وما زال ماوافقش؟"""
    return s.get("mode") == "approve" and step in (s.get("steps") or []) and step not in (j.get("passed") or [])


def pilot_export_file(src: Path, name: str) -> str:
    """فيديو جاهز ← «الفيديوهات الجاهزة» (ما النشر يقرأ منها)."""
    eid = uuid.uuid4().hex[:12]
    filename = f"pilot_{eid}.mp4"
    shutil.copy(src, EXPORTS_DIR / filename)
    with closing(db()) as conn, conn:
        conn.execute("INSERT INTO exports (id, name, filename, duration, source, project_id, created_at) VALUES (?, ?, ?, ?, 'pilot', NULL, ?)",
                     (eid, name[:120], filename, probe_duration(EXPORTS_DIR / filename), now()))
    return eid


def pilot_render(pid: str, port: int) -> None:
    with closing(db()) as conn, conn:
        row = get_project(conn, pid)
        if row["render_status"] == "rendering":
            return
        data = json.loads(row["data"])
        cw, ch, fps, crf = export_settings(data)
        with montage.canvas(cw, ch, fps, crf):
            start_render(conn, row, pid, data, SimpleNamespace(scope={"server": ("127.0.0.1", port)}))


def pilot_caption(d: dict) -> str:
    sc, idea = d.get("scenario") or {}, d.get("idea") or {}
    return (sc.get("caption") or "").strip() or "\n".join(x for x in (idea.get("title"), idea.get("hook")) if x)[:2000]


def pilot_say(sc: dict) -> str:
    return " ".join(str(b.get("say") or "").strip() for b in sc.get("beats") or [] if str(b.get("say") or "").strip())


# 💰 رسم الأوتوبايلوت: نقط ثابتة على كل بوست بيتجهّز ويتجدول لوحده (فوق تكلفة التوليد نفسها)، حتى لو الخطوات مافيهاش ذكاء صناعي
PILOT_FEE_USD = float(os.environ.get("PILOT_FEE_USD") or 0.15)


def pilot_fee() -> int:
    return wallet.credits(PILOT_FEE_USD)


def pilot_step(j: dict, s: dict, port: int) -> None:
    """خطوة واحدة للمهمة (بدون ما نستنى عمل تقيل: العمل التقيل يُنشأ في الخلفية ونرجعله اللفة القادمة)."""
    jid, kind, ph = j["id"], j["kind"], j["phase"]
    put = lambda **kw: pilot_job_set(jid, **kw)  # noqa: E731
    gate = lambda step, note: put(status="wait", gate=step, note=note) or True if pilot_gate(j, s, step) else False  # noqa: E731

    if ph == "start":
        wallet.need(pilot_fee() + wallet.credits(0.05), "منشور من الأوتوبايلوت")
        if kind == "custom":
            rid, bid = j["tpl"][5:], active_client_id()
            auto_load(rid, bid)
            run = {"id": uuid.uuid4().hex[:8], "at": now(), "status": "working", "step": "يبدأ…", "project_id": None, "report": [], "error": None, "pilot": jid}
            auto_update(rid, lambda x: x.update(runs=[run, *(x.get("runs") or [])][:20]), bid)
            threading.Thread(target=run_automation, args=(rid, run["id"], bid, port), daemon=True).start()
            return put(phase="custom", run_id=run["id"], note="القالب المخصص يعمل")
        if kind == "avatar" and not pilot_twin(s):
            raise HTTPException(400, "لا يوجد أفاتار جاهز في «الأفاتار». سجّل فيديو القراءة أو صورة أمامية أولًا")
        pre = j.get("preset") or {}
        f = flow_new(FlowNewIn(template=j["tpl"], name=j["name"] if j["name"] != j["tpl"] else "", skip_ideas=bool(pre.get("title") or pre.get("idea"))))
        flow_update(f["id"], lambda x: x.update(pilot=jid))
        if pre.get("title") or pre.get("idea"):   # 🗓️ الفكرة من خطة الشهر: على السكريبت على طول
            flow_pick_idea(f["id"], FlowPickIn(item={"title": pre.get("title"), "idea": pre.get("idea"), "hook": pre.get("hook")}))
            return put(phase="script", fid=f["id"], note="يكتب النص")
        return put(phase="idea", fid=f["id"], note="يفكّر في أفكار")

    if kind == "custom" and ph == "custom":
        rid = j["tpl"][5:]
        run = next((r for r in auto_load(rid, active_client_id()).get("runs") or [] if r["id"] == j.get("run_id")), None)
        if not run:
            raise HTTPException(400, "التشغيل حُذف")
        if run["status"] == "working":
            return put(note=run.get("step") or "يعمل")
        if run["status"] == "failed":
            raise HTTPException(400, run.get("error") or "القالب المخصص توقف")
        ex = Path(str(run.get("export_url") or "")).stem
        if not ex:
            raise HTTPException(400, "القالب المخصص خلص بدون فيديو")
        return put(phase="final", project_id=run.get("project_id"), export_id=ex, note="الفيديو جاهز")

    if ph in ("final", "schedule"):
        if gate("video", "الفيديو جاهز: انظر إليه ووافق لكي يتجدول"):
            return
        if not j.get("fee_paid"):   # الرسم مرة واحدة على البوست، قبل ما يتجدول
            wallet.need(pilot_fee(), "رسم الأوتوبايلوت")
            wallet.charge(pilot_fee(), f"الأوتوبايلوت: تجهيز وجدولة «{j['name']}»", jid)
            put(fee_paid=True)
        when = max(datetime.fromisoformat(j["at"]), datetime.now(timezone.utc) + timedelta(minutes=3))
        plats = s.get("platforms") or [k for k in (publisher.accounts() if publisher.service_name() == "zernio" else {"instagram": 1})]
        caption = j.get("caption") or (pilot_caption(flow_load(j["fid"])) if j.get("fid") else j["name"])
        if kind == "carousel":   # 🖼️ الكاروسيل بيتنشر صور على إنستجرام
            post = publish_carousel(j["carousel_id"], CarouselPostIn(caption=caption, scheduled_at=when))
        else:
            post = create_post(PostIn(export_id=j["export_id"], caption=caption, platforms=plats, scheduled_at=when))
        notify("autopilot", "ok", f"🛫 جُدول: {j['name']}", when.isoformat(timespec="minutes"), "7", post["id"])
        return put(status="done", phase="done", gate=None, post_id=post["id"], note="جُدول")

    fid = j["fid"]
    d = flow_load(fid)
    if d.get("busy") and not flow_stale(d):
        return
    if d.get("error") or flow_stale(d):
        if j.get("tries", 0) >= 2:
            raise HTTPException(400, d.get("error") or "الخطوة وقفت")
        put(tries=j.get("tries", 0) + 1, note="يحاول مرة أخرى")
        if ph == "idea":
            return flow_job(fid, "ideas", lambda: flow_gen_ideas(fid))
        if ph == "script":
            return flow_job(fid, "scenarios", lambda: flow_gen_scenarios(fid))
        flow_update(fid, lambda x: x.update(error=None, busy=None))
        back = {"vo": "voice", "review": "shoot", "montage": "review"}.get(ph)   # نرجع للخطوة اللي بتبدأ الشغل ده ونعيده
        return put(phase=back) if back else None

    if ph == "idea":
        if not d.get("ideas"):
            return put(note="يفكّر في أفكار")
        if gate("idea", "اختر فكرة من التلاتة"):
            return
        pick = j.get("pick") if any(i["id"] == j.get("pick") for i in d["ideas"]) else d["ideas"][0]["id"]
        flow_pick_idea(fid, FlowPickIn(id=pick))
        return put(phase="script", pick=None, note="يكتب النص")

    if ph == "script":
        if not d.get("scenarios"):
            return put(note="يكتب النص")
        if gate("script", "اختر نص"):
            return
        pick = j.get("pick") if any(x["id"] == j.get("pick") for x in d["scenarios"]) else d["scenarios"][0]["id"]
        flow_pick_scenario(fid, FlowPickIn(id=pick))
        nxt = {"motion": "voice", "phone": "shoot", "avatar": "say", "carousel": "car"}[kind]
        return put(phase=nxt, pick=None, note="يُكمل")

    # 🖼️ الكاروسيل: نص السلايدات ← الشكل العام (مراجعة «المونتاج») ← السلايدات
    if ph == "car":
        sc = d.get("scenario") or {}
        n = max(2, min(10, len(sc.get("slides") or []) or 6))
        if not atlas.mock_mode():
            wallet.need(wallet.credits(wallet.est(chars=12000)) + carousel_img_credits() * (n + 1), "كاروسيل")
        car = create_carousel(CarouselIn(name=f"🛫 {(d.get('idea') or {}).get('title') or j['name']}"[:80]))
        cid = car["id"]
        patch_carousel(cid, CarouselPatch(settings={"slides": n}))
        brief = flow_brief({**d, "_id": fid})
        put(phase="car_plan", carousel_id=cid, note="يكتب السلايدات")

        def write():   # الكتابة بتاخد دقيقة: في الخلفية عشان لفة المجدول ماتقفش
            try:
                carousel_chat(cid, ChatIn(message="أنشئ هذا الكاروسيل بالضبط، بنفس السلايدات والنص:\n" + brief))
                carousel_plan(cid)
                carousel_overview(cid)
                pilot_job_set(jid, phase="car_over", note="يرسم الشكل العام")
            except Exception as exc:  # noqa: BLE001
                pilot_job_set(jid, status="failed", error=str(getattr(exc, "detail", None) or exc)[:300], note=None)
        threading.Thread(target=write, daemon=True).start()
        return
    if ph == "car_plan":
        return
    if ph in ("car_over", "car_slides"):
        c = get_carousel(j["carousel_id"])
        if c["busy"]:
            return
        if ph == "car_over":
            if c["overview"]["status"] == "failed":
                raise HTTPException(400, c["overview"].get("error") or "رسم الشكل العام توقف")
            if c["overview"]["status"] != "done":
                return
            if gate("montage", "شكل الكاروسيل جاهز: انظر إليه ووافق لكي يرسم السلايدات"):
                return
            carousel_approve(j["carousel_id"])
            carousel_slides(j["carousel_id"])
            return put(phase="car_slides", note="يرسم السلايدات")
        bad = [s for s in c["slides"] if s.get("status") == "failed"]
        if bad:
            raise HTTPException(400, bad[0].get("error") or "سلايد وقفت")
        if any(s.get("status") != "done" for s in c["slides"]):
            return put(note=f"بيرسم السلايدات {sum(s.get('status') == 'done' for s in c['slides'])}/{len(c['slides'])}")
        if not atlas.mock_mode():   # الرسم والكتابة على حساب العميل
            wallet.charge(wallet.credits(wallet.est(chars=12000)), "الأوتوبايلوت: كتابة الكاروسيل", jid)   # الصور بتتخصم وهي بتترسم
        return put(phase="final", note="الكاروسيل جاهز")

    # 🎨 قالب كود: فويس أوفر ← رسم الفيديو
    if ph == "voice":
        lang = d.get("lang") if d.get("lang") in dub.DIALECTS else flow_lang_guess(d)
        flow_voice(fid, FlowVoiceIn(speaker="narrator", lang=lang, voice=dub.DIALECTS[lang]["voices"][0]))
        return put(phase="vo", note="يسجّل التعليق الصوتي")
    if ph == "vo":
        if not (d.get("vo_track") or {}).get("file"):
            return
        try:
            flow_export(fid, FlowExportIn())
        except HTTPException as exc:
            return put(note=str(exc.detail)[:120])
        return put(phase="draw", note="يرسم الفيديو")
    if ph == "draw":
        o = flow_to_dict(fid, d).get("output") or {}
        if o.get("status") == "failed":
            raise HTTPException(400, o.get("error") or "الرسم توقف")
        if o.get("status") != "done" or not o.get("asset"):
            return put(note=f"يرسم الفيديو {round((o.get('progress') or 0) * 100)}%")
        ex = pilot_export_file(ASSETS_DIR / Path(o["asset"]).name / "clip.mp4", f"🛫 {(d.get('idea') or {}).get('title') or j['name']}")
        return put(phase="final", export_id=ex, note="الفيديو جاهز")

    # 📱 الموبايل: العميل بيصوّر ← ملاحظات ← مونتاج أوتوماتيك ← تصدير
    if ph == "shoot":
        if not ((d.get("footage") or {}).get("main") or {}).get("gen_id"):
            if j.get("status") == "cam":
                return
            return put(status="cam", gate="shoot", note="📱 صوّر النص وارفع الفيديو")
        put(status="run", gate=None)
        flow_phone_review(fid)
        return put(phase="review", note="يشاهد الفيديو")
    if ph == "review":
        if not d.get("review"):
            return
        flow_phone_montage(fid, PhoneMontageIn())
        return put(phase="montage", note="يعمل المونتاج")
    if ph == "montage":
        pid = (d.get("montage") or {}).get("project_id")
        if not pid:
            return
        put(project_id=pid)
        if gate("montage", "المونتاج جاهز: افتحه وعدّل إذا حابب، ووافق"):
            return
        pilot_render(pid, port)
        return put(phase="export", note="يصدّر الفيديو")
    if ph == "export":
        with closing(db()) as conn:
            r = conn.execute("SELECT render_status, render_error, export_id FROM projects WHERE id = ?", (j["project_id"],)).fetchone()
        if not r:
            raise HTTPException(400, "مشروع المونتاج حُذف")
        if r["render_status"] == "rendering":
            return put(note=f"يصدّر: {RENDER_ACTIVE.get(j['project_id']) or ''}".strip(" :"))
        if r["render_error"] or not r["export_id"]:
            raise HTTPException(400, f"التصدير فشل: {r['render_error'] or ''}"[:300])
        return put(phase="final", export_id=r["export_id"], note="الفيديو جاهز")

    # 🪞 الأفاتار: السكريبت بصوت ← نسختك بتقوله
    if ph == "say":
        tid = pilot_twin(s)
        if not tid:
            raise HTTPException(400, "لا يوجد أفاتار جاهز في «الأفاتار»")
        text = pilot_say(d.get("scenario") or {})
        if not text:
            raise HTTPException(400, "النص لا يحتوي نص يُقال")
        lang = d.get("lang") if d.get("lang") in dub.DIALECTS else flow_lang_guess(d)
        voice = dub.DIALECTS[lang]["voices"][0]
        cost = wallet.credits(dub.estimate([text], voice, len(text) / dub.CHARS_PER_SEC, None) or 0.01)
        wallet.need(cost, "صوت الأفاتار")
        cid = uuid.uuid4().hex[:8]
        wav = vo_say(text, voice, lang, twin_dir(tid) / f"say_{cid}.wav")   # الصوت بيتخصم جوّه vo_say
        t = twin_load(tid)
        method = "video" if twin.ready(t)["video"] else "photo"
        item = {"id": cid, "method": method, "quality": "veed" if method == "video" else "pro", "text": text[:2000], "audio": wav.name,
                "status": "queued", "step": "في الطابور", "file": None, "error": None, "created_at": now(), "pilot": jid}
        twin_update(tid, lambda x: x.setdefault("clips", []).append(item))
        threading.Thread(target=run_twin_clip, args=(tid, cid), daemon=True).start()
        return put(phase="twin", twin=tid, clip=cid, note="الأفاتار يتكلم (يأخذ كم دقيقة)")
    if ph == "twin":
        c = next((x for x in twin_load(j["twin"]).get("clips") or [] if x["id"] == j.get("clip")), None)
        if not c:
            raise HTTPException(400, "فيديو النسخة حُذف")
        if c["status"] == "failed":
            raise HTTPException(400, c.get("error") or "فيديو النسخة توقف")
        if c["status"] != "done":
            return put(note=c.get("step") or "يعمل")
        ex = pilot_export_file(twin_dir(j["twin"]) / c["file"], f"🛫 {(d.get('idea') or {}).get('title') or j['name']}")
        return put(phase="final", export_id=ex, note="الفيديو جاهز")


def pilot_tick() -> None:
    """تتنادى من لفة المجدول: مهام جديدة للمواعيد القادمة، وخطوة لكل مهمة تعمل."""
    if not PILOT_TICK.acquire(blocking=False):
        return
    try:
        if not PILOT_FILE.exists():
            return
        pilot_plan()
        d = pilot_load()
        for j in d["jobs"]:
            if j.get("status") not in ("run", "cam"):
                continue
            try:
                pilot_step(j, d["settings"], d["port"])
            except wallet.NoCredits as exc:
                pilot_job_set(j["id"], status="failed", error=str(exc), note=None)
            except HTTPException as exc:
                pilot_job_set(j["id"], status="failed", error=str(exc.detail)[:300], note=None)
            except Exception as exc:  # noqa: BLE001
                pilot_job_set(j["id"], status="failed", error=str(exc)[:300], note=None)
                log_render(f"pilot {j['id']}: {exc}")
            if j.get("status") == "run":
                after = next((x for x in pilot_load()["jobs"] if x["id"] == j["id"]), {})
                if after.get("status") in ("failed", "wait", "cam") and after.get("status") != j.get("status"):
                    level, title = ("bad", f"🛫 وقف: {j['name']}") if after["status"] == "failed" else ("info", f"🛫 مستنيك: {j['name']}")
                    notify("autopilot", level, title, after.get("error") or after.get("note") or "", "pilot", j["id"])
    finally:
        PILOT_TICK.release()


def pilot_job_dict(j: dict) -> dict:
    out = {k: v for k, v in j.items() if k not in ("passed", "tries")}
    d = None
    if j.get("fid"):
        try:
            d = flow_load(j["fid"])
        except HTTPException:
            d = None
    if d:
        idea, sc = d.get("idea") or {}, d.get("scenario") or {}
        out["title"] = sc.get("title") or idea.get("title") or ""
        if j.get("gate") == "idea":
            out["options"] = [{"id": i["id"], "title": i.get("title", ""), "text": i.get("hook") or i.get("idea", "")} for i in d.get("ideas") or []]
        elif j.get("gate") == "script":
            out["options"] = [{"id": x["id"], "title": x.get("title", ""), "text": pilot_say(x) or x.get("summary", "")} for x in d.get("scenarios") or []]
        if j["kind"] == "phone" and sc:
            out["script"] = [str(b.get("say") or "") for b in sc.get("beats") or [] if b.get("say")]
    if j.get("export_id"):
        with closing(db()) as conn:
            r = conn.execute("SELECT filename FROM exports WHERE id = ?", (j["export_id"],)).fetchone()
        out["video_url"] = f"/media/exports/{r['filename']}" if r else None
    if j.get("carousel_id"):   # صور الكاروسيل: الشكل العام وقت مراجعته، والسلايدات بعد ما تترسم
        try:
            c = get_carousel(j["carousel_id"])
            out["images"] = [s["url"] for s in c["slides"] if s.get("url")] or ([c["overview"]["url"]] if c["overview"].get("url") else [])
        except HTTPException:
            out["images"] = []
    return out


def pilot_state() -> dict:
    d = pilot_load()
    s = d["settings"]
    jobs = [pilot_job_dict(j) for j in d["jobs"][:30]]
    custom = [{"id": f"auto:{a['id']}", "name": a["name"], "kind": "custom"} for a in automations_list() if a.get("saved")]
    twins = [{"id": t["id"], "name": t.get("name") or "", "ready": bool(t["ready"]["video"] or t["ready"]["photo"])} for t in twins_list()]
    upcoming = [a.isoformat(timespec="minutes") for a in pilot_slots(s, datetime.now(timezone.utc), 48)][:12]
    return {"settings": s, "jobs": jobs, "custom": custom, "twins": twins, "best": PILOT_BEST, "upcoming": upcoming,
            "waiting": sum(1 for j in d["jobs"] if j.get("status") in ("wait", "cam")), "fee": pilot_fee()}


class PilotIn(BaseModel):
    on: bool | None = None
    per_day: int | None = None
    times: list[dict] | None = None
    tz: int | None = None
    templates: list[str] | None = None
    mode: str | None = None
    steps: list[str] | None = None
    platforms: list[str] | None = None
    twin: str | None = None
    names: dict | None = None   # أسماء قوالب الكود (للعرض)


def pilot_port(request: Request) -> int:
    return (request.scope.get("server") or ("127.0.0.1", 8000))[1]


@app.get("/api/pilot")
def pilot_get(request: Request):
    port = pilot_port(request)
    if pilot_load()["port"] != port:
        pilot_update(lambda d: d.update(port=port))
    return pilot_state()


@app.put("/api/pilot")
def pilot_put(body: PilotIn, request: Request):
    def fn(d):
        s = d["settings"]
        if body.per_day is not None:
            s["per_day"] = max(1, min(6, int(body.per_day)))
        if body.times is not None:
            seen, times = set(), []
            for x in body.times[:6]:
                t = str(x.get("t") or "")
                if re.fullmatch(r"([01]\d|2[0-3]):[0-5]\d", t) and t not in seen:
                    seen.add(t)
                    times.append({"t": t, "mine": bool(x.get("mine"))})
            s["times"] = sorted(times, key=lambda x: x["t"])
            s["per_day"] = max(1, len(times))
        if body.tz is not None:
            s["tz"] = max(-720, min(840, int(body.tz)))
        if body.templates is not None:
            s["templates"] = [t for t in dict.fromkeys(body.templates) if t in ("phone", "avatar", "carousel") or t.startswith("auto:") or re.fullmatch(r"t-[\w-]+", t)][:30]
        if body.mode in ("auto", "approve"):
            s["mode"] = body.mode
        if body.steps is not None:
            s["steps"] = [x for x in PILOT_STEPS if x in body.steps]
        if body.platforms is not None:
            s["platforms"] = [p for p in dict.fromkeys(body.platforms) if publisher.valid_target(p)][:20]
        if body.twin is not None:
            s["twin"] = body.twin[:40]
        if body.on is not None:
            s["on"] = bool(body.on)
        if not s["on"]:   # الإيقاف بيوقف المهام اللي لسه مابدأتش بس
            d["jobs"] = [j for j in d["jobs"] if not (j.get("status") == "run" and j.get("phase") == "start")]
        d["port"] = pilot_port(request)
        if body.names:
            s["names"] = {**(s.get("names") or {}), **{k: str(v)[:80] for k, v in body.names.items() if str(k).startswith("t-")}}
    pilot_update(fn)
    return pilot_state()


class PilotOkIn(BaseModel):
    pick: str = ""


@app.post("/api/pilot/jobs/{jid}/ok")
def pilot_ok(jid: str, body: PilotOkIn):
    """موافقة على الخطوة التي المهمة واقفة لديها (ومعها الاختيار: الفكرة أو النص)."""
    def fn(d):
        j = next((x for x in d["jobs"] if x["id"] == jid), None)
        if not j or j.get("status") != "wait":
            raise HTTPException(400, "هذه المهمة غير تنتظر موافقة")
        j.update(status="run", passed=[*(j.get("passed") or []), j["gate"]], gate=None, pick=body.pick or None, note="يُكمل", updated_at=now())
    pilot_update(fn)
    return pilot_state()


@app.post("/api/pilot/jobs/{jid}/footage")
def pilot_footage(jid: str, file: UploadFile = File(...)):
    """📱 الفيديو الذي العميل صوّره بالسكريبت."""
    j = next((x for x in pilot_load()["jobs"] if x["id"] == jid), None)
    if not j or not j.get("fid"):
        raise HTTPException(404, "هذه المهمة غير موجودة")
    flow_footage_upload(j["fid"], "main", file)
    if j.get("status") == "cam":
        pilot_job_set(jid, status="run", gate=None, note="يشاهد الفيديو")
    return pilot_state()


@app.post("/api/pilot/jobs/{jid}/footage/shots")
def pilot_footage_shots(jid: str, files: list[UploadFile] = File(...)):
    """📱 نفس اللي فوق، بس اللقطات جاية من تطبيق الموبايل لقطة لقطة."""
    j = next((x for x in pilot_load()["jobs"] if x["id"] == jid), None)
    if not j or not j.get("fid"):
        raise HTTPException(404, "هذه المهمة غير موجودة")
    flow_footage_shots(j["fid"], files)
    if j.get("status") == "cam":
        pilot_job_set(jid, status="run", gate=None, note="يشاهد الفيديو")
    return pilot_state()


@app.post("/api/pilot/jobs/{jid}/retry")
def pilot_retry(jid: str):
    def fn(d):
        for j in d["jobs"]:
            if j["id"] == jid and j.get("status") in ("failed", "stopped"):
                j.update(status="run", error=None, tries=0, note="يحاول مرة أخرى", updated_at=now())
                if j["kind"] == "custom" and j["phase"] == "custom":
                    j["phase"] = "start"
    pilot_update(fn)
    return pilot_state()


@app.post("/api/pilot/jobs/{jid}/stop")
def pilot_stop(jid: str):
    def fn(d):
        for j in d["jobs"]:
            if j["id"] == jid and j.get("status") in PILOT_ACTIVE:
                j.update(status="stopped", gate=None, note="اتوقفت", updated_at=now())
    pilot_update(fn)
    return pilot_state()


@app.delete("/api/pilot/jobs/{jid}")
def pilot_delete(jid: str):
    pilot_update(lambda d: d.update(jobs=[j for j in d["jobs"] if not (j["id"] == jid and j.get("status") not in PILOT_ACTIVE)]))
    return pilot_state()


